quests[14382] = { id = 14382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nimm mich mit, Kapitän, auf die Reise", description = "Die Katapulte der Verlassenen machen uns ganz schön zu schaffen, {name}. Und selbst wenn wir ihrer Herr würden, stehen da noch zwei Schiffe mit zwei Reihen Kanonen.\n\nIch habe jedoch einen Plan, mit dem wir zwei Fliegen mit einer Klappe schlagen. Ihr seid bei diesem Plan die Klappe.\n\nBeseitigt die Maschinisten an den Katapulten. Nutzt danach die Katapulte, um Euch selbst an Bord der Schiffe der Verlassenen zu katapultieren.\n\nWenn Ihr nicht gerade komplett daneben zielt, solltet Ihr sicher landen. Sobald Ihr an Bord seid, geht unter Deck und erledigt den Kapitän jedes Schiffes. Viel Erfolg, {class}.", sourceObjective = "Benutzt die Katapulte der Verlassenen, um auf die Schiffe zu gelangen und tötet Kapitän Morris und Kapitän Anson.", completion = "Gut gemacht, {name}. Ihr seid vielleicht eine blutrünstige Bestie, aber Ihr seid unsere Bestie.", sourceObjectiveStatus = "unverified-source-field" }
quests[14383] = { id = 14383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die tobenden Tüftler der Verfallenen Gegenden", description = "Halunken! Ungläubige! Seit ich meine Arbeit hier Azshara aufgenommen habe, haben die Federdings meine Experimente behindert und meine Forschungen sabotiert. Und jetzt ist ihnen eine Bande von mittelmäßigen, zweitklassigen Tüftlern zu Hilfe geeilt! Ich habe mich dringenden Geschäften zuzuwenden. Kümmert Euch darum, dass diese Gnome für immer erledigt werden.\n\nBegebt Euch in die Verfallenen Gegenden an der Küste, südlich meines Geheimlabors und lasst ihre überdimensionierten Köpfe für mich rollen.", sourceObjective = "Tötet Bingham Federdings in den Verfallenen Gegenden und dazu 4 Netzgewehrgnome und 6 Britzelgnome.", completion = "Oh - fabelhaft. Erzählt mir mehr. Und dieser altkluge junge Federdings? Auch tot? Ah, wunderbar. Meine Arbeit hier ist sehr wichtig, aber manchmal vermisse ich das Gemetzel, wenn ich meine Feinde auf einem persönlicheren Level demontiere. Hier, vielleicht kann Euch etwas von meiner ausgemusterten Ausrüstung nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14384] = { id = 14384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgeleitet!", description = "Halt!\n\nIm Namen der Wache der Nijelspitze - ich habe Befehl, dafür zu sorgen, dass alle tauglichen Verbündeten sich bei Korporal Melkins melden.\n\nIch bin nicht befugt, weitere Informationen zu geben.\n\nIch kann allerdings Transport anbieten. Ihr dürft mein Reittier benutzen. Es wird Euch direkt dort absetzen.\n\nWegtreten.", sourceObjective = "Offizierin Jankie möchte, dass Ihr auf ihrem Reittier zur Nijelspitze fliegt und dort mit Korporal Melkins sprecht.", completion = "Willkommen auf der Nijelspitze, {race}. \n\nAlso, dann wollen wir Euch mal über unsere Situation hier aufklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[14385] = { id = 14385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharitexperiment Nummer Eins", description = "Nun, ich kann mir einen todsicheren Weg vorstellen, wie man einen Riesen dazu bringt, zur Toilette zu rennen, aber das wird Euch nicht gefallen. Wir brauchen einfach ein ... gewaltiges ... Abführmittel. Oh hey! Ihr werdet es nicht glauben, aber die Gnome haben tatsächlich so etwas. Das kann kein Zufall sein. Ich frage mich, was die da drüben wohl durchdrücken wollen.\n\nUnser Geheimdienst berichtet, dass das Abführmittel bei Federdings' Turm unten an der Küste südlich des Geheimlabors abgegeben wurde. Holt das Abführmittel und verabreicht es Gormungan!", sourceObjective = "Besorgt Euch ein Abführmittel in Riesengröße von dem Gnomenturm in den Verfallenen Gegenden. Versucht, das Abführmittel dem Riesen Gormungan zu verabreichen.", progress = "Sobald Ihr das Abführmittel habt, versucht, es Gormungan zu verabreichen. Und gebt ihm vielleicht eine Zeitschrift oder so etwas. Tut es für die Wissenschaft!", completion = "Also ist nichts dabei rausgekommen? Im wahrsten Sinne des Wortes? Nun, Wurfhammer wird ein Nein nicht akzeptieren. Wir müssen etwas Anderes ausprobieren.\n\nVielleicht lasse ich meine Praktikanten dieses Abführmittel in das Lager der Nachtelfen schmuggeln. Das wäre doch bestimmt sehr lustig.", sourceObjectiveStatus = "unverified-source-field" }
quests[14386] = { id = 14386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leithund", description = "Ausgezeichnete Arbeit bisher, {name}. Unsere Späher haben die Anführerin des Bodenangriffs der Verlassenen ermittelt.\n\nEine von Sylvanas persönlich ausgewählte Dunkelläuferin kontrolliert das Schlachtgeschehen vom Haus der Waldens bei der Küste aus. Nehmt diese Pfeife mit und benutzt sie, wenn Ihr in ihrer Nähe seid.\n\nIch befehle meinen Männern dann, unsere Angriffsmastiffs loszulassen, um sie zur Strecke zu bringen. Seid vorsichtig, {name}. Ihr solltet ihr nicht allein gegenübertreten.", sourceObjective = "Benutzt die Mastiffpfeife, um Hilfe dabei zu bekommen, Dunkelläuferin Thyala zu töten.", completion = "Ihr habt es geschafft, {name}. Das sollte ihnen den Wind aus den Segeln nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14387] = { id = 14387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffenheit des Geländes", description = "Ja, ja. Willkommen in Desolace, {race}.\n\nTut mir leid, dass wir so darauf bestehen mussten, aber wir sind nur ein kleiner Außenposten und es gibt große Probleme in dieser Region - die meisten davon ziemlich dringend.\n\nUnterm Strich heißt das: Wir können jede Hilfe gebrauchen, die wir bekommen können.\n\nZunächst einmal ist unser Freund Vahlarriel da drüben ziemlich nervös geworden und besteht darauf, dass wir ein Aufgebot zu den Ruinen im Osten entsenden.\n\nWarum geht Ihr nicht und stellt Euch vor...", sourceObjective = "Hauptmann Pentigast möchte, dass Ihr mit Vahlarriel auf der Nijelspitze sprecht.", completion = "Ist mir ein Vergnügen, Euch kennenzulernen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14388] = { id = 14388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharitexperiment Nummer Zwei", description = "Ok - neuer Plan. Wir ERSCHRECKEN sie so, dass wir es bekommen! Meiner Erfahrung nach ängstigen große Kreaturen sich vor kleinen - wie Ratten. Hmm. Hier wimmelt es nur so von Ratten, aber wie locken wir sie zu dem Riesen?\n\nHey! Es macht Euch doch nichts aus, wenn Eure Zellenmatrix auseinandergenommen und wieder zusammengesetzt wird, oder? Es tut nur während des Vorgangs weh. Ich kann Euch auf Rattengröße zusammenschrumpfen und Ihr könnt eins von den Viechern dort drüben reiten wie ein Pferd. Das ist so verrückt, dass es funktionieren muss! Lasst mich wissen, wenn Ihr zum Schrumpfen bereit seid...", sourceObjective = "Sprecht mit Assistentin Greely, um auf Rattengröße zusammengeschrumpft zu werden. Steigt auf eine Ratte der Raketenbahn und jagt Gormungan dem Riesen damit Angst ein.", completion = "Also hat Angst einjagen auch nichts bewirkt? Verflixt nochmal! Das muss ich Wurfhammer schonend beibringen. Azsharit wird wohl die seltenste Substanz auf dem Planeten bleiben. Wir müssen es äußerst sparsam verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14389] = { id = 14389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War das nicht klar?", description = "Azuregos! Ja, natürlich! Verstörter, alter Drache, aber ein gutes Herz. Ich glaube, all die Jahre, in denen er von Vagabunden angegriffen wurde, haben ihm nicht gutgetan. Heutzutage ist er ein wenig seltsam.\n\nVor nicht allzu langer Zeit, als ich wieder einmal zu Anara, unserer hiesigen Geistheilerin, zurückkehrte, fiel mir auf, dass sie und Azuregos sich anscheinend sehr gut verstehen. Ich könnte mir vorstellen, dass er ihr immer noch Gesellschaft leistet.\n\nDas Portal hinter mir ist der wahrscheinlich schnellste Weg, um zu ihr zu gelangen. Es könnte allerdings ein wenig zwicken.", sourceObjective = "Benutzt das Portal hinter Joanna in Xylems Turm, um Anara, die Geistheilerin - und hoffentlich Azuregos - zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14390] = { id = 14390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach kann jeder", description = "Nach langer Suche mit einigen zweifelhaften Wendungen habt Ihr endlich Azuregos gefunden.\n\nJetzt müsst Ihr ihn nur noch davon überzeugen, sich mit Kalecgos zu treffen und der Bedrohung Azsharas durch den schwarzen Drachenschwarm ein Ende zu bereiten.", sourceObjective = "Überzeugt Azuregos, in die Welt der Lebenden zurückzukehren und sich mit Kalecgos zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14391] = { id = 14391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wenden", description = "Azuregos und Kalecgos sind kurz davor, sich an der Nördlichen Endhaltestelle der Raketenbahn zu treffen. Ihr solltet dort zu ihnen stoßen, um sicherzustellen, dass Kalecgos keine zusätzliche Hilfe benötigt.\n\nSolltet Ihr es vorziehen, nicht tot zu sein, wird Anara Euch höchstwahrscheinlich helfen können.", sourceObjective = "Sprecht mit Anara, um in die Welt der Lebenden zurückzukehren, dann sprecht mit Kalecgos an der Nördlichen Endhaltestelle der Raketenbahn.", completion = "Schön, Euch wiederzusehen! Danke, dass Ihr Azuregos gefunden und zu mir geschickt habt.\n\nIch glaube, ich muss mich bei Euch entschuldigen - möglicherweise habe ich ein wenig untertrieben, als ich Euch über die Schwierigkeit der Aufgabe, die ich Euch stellte, ins Bild setzte. Ihr habt Euch bewundernswert geschlagen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14392] = { id = 14392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leb wohl, Minnow", description = "Danke, kleines Wesen.\n\nManchmal ist es einfach, sich in der Umklammerung der Liebe zu verirren und die Sicht auf die wichtigen Dinge zu verlieren, sogar für einen Drachen. Ich gedenke, mich wieder vollkommen dem Ziel zu verschreiben, dass Kalec niemals Malygos' Platz einnehmen wird. Das ist die edelste Sache, die ich mir vorstellen kann.\n\nIhr solltet Euch auf den Weg zurück zum Hafen machen. Soweit ich weiß, wartet dort jemand auf Euch.\n\nVersucht, nicht zerquetscht oder von etwas gefressen zu werden.", sourceObjective = "Sprecht mit Sorata Feuerspinner im Bilgewasserhafen.", completion = "Hallo - wieder einmal.\n\nHört mal, ich habe Euch meinen Hut gegeben. Er war ein Geschenk. Ich dachte, er könnte Euch vielleicht irgendwie nützlich sein. Um genau zu sein, dachte ich, Ihr würdet ihn so weit wie möglich von mir wegbringen.\n\nKönnt Ihr Euch meine Überraschung vorstellen, als Xylem höchstpersönlich hier vorbeikam, um ihn mir zurückzugeben? \"Willst du mehr wie meine anderen Lehrlinge sein, Sorata? Dann versuch's nochmal mit deinem Hut.\" Das war nicht einer der Momente, auf die ich stolz bin.\n\nAlso wie war das... Ihr habt ihn achtlos zur Seite geworfen, damit er ihn findet? Nein. Das glaube ich nicht. Ihr werdet diesen Hut nehmen und Ihr werdet ihn mögen. Ganz bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14393] = { id = 14393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Kampf!", description = "Seit unzähligen Generationen bekämpfen die Zentauren sich untereinander, aber das ist vorbei.\n\nWegen Eurer Taten stehen wir hier Seite an Seite und bekämpfen einen gemeinsamen Feind. Wir werden das Land unserer Vorfahren von diesen Dämonen zurückgewinnen, oder als Brüder sterben.\n\nWie ist es mit Euch, {name}?\n\nIhr habt Euch das Recht verdient, an unserer Seite zu kämpfen. Ich möchte Euch eine Gruppe meiner besten Zentauren anvertrauen, damit Ihr sie in den Kampf führt.\n\nWerdet Ihr den Speer aufnehmen?", sourceObjective = "Khan Leh'prah möchte, dass Ihr 15 Hexenmeister der Brennenden Klinge, 3 Verdammniswacheneindringlinge und Priesterin Than'darissa besiegt.\n\nSprecht mit Khan Leh'prah, um in den Kampf zu ziehen.", completion = "Gut gemacht, {name}!\n\nLasst uns das hier beenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14394] = { id = 14394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Agogridon", description = "Unser Ziel ist zum Greifen nahe, {name}!\n\nWir können den Willen dieser Dämonenarmee brechen, indem wir ihren Anführer zur Strecke bringen. Gelingt es uns, wird Desolace uns gehören!\n\nWenn Ihr bereit seid, führt eine Gruppe Zentauren durch den Pass im Süden nach Schattenklamm. Findet Agogridons Versteck!\n\nIch werde die anderen Khans um mich versammeln und Euch dort treffen, damit wir uns ihm im Kampf stellen.", sourceObjective = "Besiegt Agogridon.", completion = "Agogridon gibt es nicht mehr.\n\nDie Dämonen werden sich nie wieder in unseren Landen ausbreiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[14395] = { id = 14395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atemlos", description = "{name}! Ich war gerade unterwegs, als es passiert ist.\n\nWir haben keine Zeit zu verlieren. Gut die Hälfte der Wachleute der Stadt hat sich in dem Bereich aufgehalten, der eingestürzt ist. Geht dorthin und rettet so viele, wie Ihr könnt.\n\nZieht sie aus dem Wasser ans Ufer. Ich kümmere mich darum, dass sie die benötigte Hilfe bekommen.", sourceObjective = "Rettet 4 ertrinkende Wachleute.", progress = "Es sind nicht mehr viele von uns übrig, {name}. Wir müssen uns um die letzten verbliebenen Gilneer kümmern.", completion = "Ihr habt getan, was Ihr konntet, {name}. Mit etwas Glück schaffen es noch ein paar andere ans Ufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14396] = { id = 14396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als das Land zerbarst", description = "Was in aller Welt war das, {name}?\n\nDas waren keine Kanonen oder Katapulte, so viel steht fest.\n\nGeht nach draußen und seht nach, was los ist.", sourceObjective = "Sprecht mit Prinz Liam Graumähne auf Allens Bauernhof.", completion = "Das Meer, {name}! Es hat alles verschlungen… das Land… die Verlassenen… unsere Männer!", sourceObjectiveStatus = "unverified-source-field" }
quests[14397] = { id = 14397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierung", description = "Wir sind dem Tod nur durch schieres Glück entkommen, {name}. Aber unser Glück ist langsam erschöpft.\n\nNoch während wir hier sprechen wird die Küste überflutet. Und auch die Landmasse unter uns scheint sich noch nicht beruhigt zu haben.\n\nIch sage es nicht gerne, aber wir müssen hier weg. Verdammt, {name}... Ich darf mein Heimatland nicht zweimal in meinem Leben verlieren. Aber diese Erdbeben sind kein Feind, den wir besiegen können.\n\nSagt Gwen Armstead, dass sie die Evakuierung einleiten soll.", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Liam hat Recht. Wir müssen in ein höher gelegenes Gebiet fliehen.\n\nHelft mir, die Leute zu benachrichtigen, während ich die Organisation der Evakuierung übernehme.", sourceObjectiveStatus = "unverified-source-field" }
quests[14398] = { id = 14398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oma Wahl", description = "Es wird nicht leicht, Oma Wahl dazu zu bewegen, mit uns zu kommen. Ihr müsst dennoch alles in Eurer Macht Stehende tun, um sie zu überzeugen.\n\nIhr findet sie in Wahls Landhaus. Bitte, {name}, seid geduldig mit ihr. Sie ist schon sehr alt und ihr Geist wird immer schwächer.", sourceObjective = "Findet Oma Wahl in Wahls Landhaus.", completion = "Oh, Besuch! Bleibt Ihr auf eine Tasse Tee, Herzchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14399] = { id = 14399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oma hat sie nicht mehr alle", description = "Gehen? Jetzt?\n\nNun, was sein muss, muss wohl sein. Aber wärt Ihr ein Engel und würdet etwas für mich suchen?\n\nIch habe mein Lieblingsbuch verlegt und werde ganz sicher nicht ohne es gehen.\n\n<Nachdem Ihr Oma die Dringlichkeit der Lage erläutert habt, schüttelt sie herablassend den Kopf.>\n\nLiebes, sucht einfach das Buch für mich, ja?", sourceObjective = "Findet das leinengebundene Buch.", progress = "Wie läuft es, Schätzchen? Bleibt Ihr zum Tee?", completion = "Vielen Dank, {name}. Ich hoffe, Ihr habt nicht hineingelinst!\n\nWo bleiben Eure Manieren, Herzchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14400] = { id = 14400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So gehe ich nicht außer Haus", description = "Was wolltet Ihr nochmal?\n\nOh, stimmt ja. Der Evakuierungsbefehl.\n\nAber so kann ich ja schlecht unter die Leute gehen, oder?\n\nSeid so lieb und holt mir meine guten Kleider. Sie hängen draußen auf der Wäscheleine.\n\n<Ihr versucht vergeblich, Oma Wahl davon zu überzeugen, dass ihre jetzige Kleidung völlig angemessen ist.>\n\nIhr jungen Leute habt einfach keine Manieren. Wurdet Ihr von Ogern großgezogen? Und jetzt geht und bringt mir meine Kleider, Liebes.", sourceObjective = "Besorgt Omas gute Kleider.", progress = "Habt Ihr alles gefunden, Schätzchen?", completion = "Ihr seid ein Goldschatz, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[14401] = { id = 14401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omas Katze", description = "Genau! Was die Evakuierung angeht, Liebes.\n\nIch kann nicht ohne meine Katze gehen. Er ist ein zuckersüßer orangefarbener Tigerkater.\n\nFelix spielt am liebsten in der Nähe eines alten Karrens in der Nähe einer Laube nordöstlich von hier.\n\nBringt ihn zu mir, dann können wir sofort aufbrechen.", sourceObjective = "Holt Felix, die Katze.", progress = "Ihr seid so ein bezaubernder junger Mann, {name}.", completion = "Da ist er ja! Omas kleiner Liebling!\n\nVielen Dank, dass Ihr ihn gefunden habt. Ich hoffe, es hat Euch nicht allzu viele Umstände bereitet.\n\nOh je… meine Fingernägel sind ja ganz dreckig!", sourceObjectiveStatus = "unverified-source-field" }
quests[14402] = { id = 14402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abmarschbereit", description = "Ich schätze, jetzt aufzubrechen ist genauso gut wie zu jedem anderen Zeitpunkt.\n\nIch habe meine schönste Kleidung, mein Lieblingsbuch und meine geliebte Katze bei mir.\n\nIch hoffe, ich habe nichts vergessen.\n\nSagt dieser Bürgermeisterin, dass ich auf dem Weg bin. Dann sehe ich Euch wohl zusammen mit den anderen in der Stadt!", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Ihr habt das Unmögliche geschafft, {name}! Ihr habt Oma Wahl überredet, ihr Zuhause zu verlassen.\n\nIch muss schon sagen, Ihr seid etwas ganz Besonderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[14403] = { id = 14403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brüder Hayward", description = "Weit im Süden findet Ihr die Fischerei Hayward. Die Brüder Hayward führen sie schon seit vielen Jahren.\n\nSie kommen nicht oft in die Stadt, nur um ihre Fische zu verkaufen. Gebt ihnen Bescheid, dass die Evakuierung eingeleitet wurde.", sourceObjective = "Sprecht mit Sebastian Hayward in der Fischerei Hayward.", completion = "Seid Ihr hier, um uns zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14404] = { id = 14404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht alles im Lot auf'm Boot", description = "Evakuierung, sagt Ihr? Nun, nachdem die Verlassenen hier aufgetaucht sind, kam uns diese Idee von ganz alleine.\n\nWir dachten, zur See wäre der sicherste Fluchtweg.\n\nLeider haben unsere Boote das letzte Erdbeben nicht unbeschadet überstanden.\n\nIch benötige noch ein wenig Material, um meine Reparaturen abzuschließen: Holz, Teer und meine Werkzeuge. Besorgt sie mir, damit ich und meine Brüder von hier entkommen können.", sourceObjective = "Besorgt Holzplanken, Kohlenteer und Schiffbauerwerkzeuge.", progress = "Habt Ihr mein Material, {name}?", completion = "Toll, {name}. Jetzt kann ich die Reparaturen im Handumdrehen fertigstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14405] = { id = 14405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht zur See", description = "Danke für Eure Hilfe, {name}. Unser Schiff ist bereit zum Ablegen.\n\nUnd jetzt geht und sagt Fräulein Armstead, dass wir nicht an der Evakuierung über Land teilnehmen.\n\nWir Haywards sind seit Jahren Männer der See. Wenn wir unser Zuhause verlassen müssen, dann nur zu Wasser.", sourceObjective = "Kehrt zu Gwen Armstead in Dämmerhafen zurück.", completion = "Soll mir Recht sein, {name}. Vielleicht ergeht es den Haywards ja besser als uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[14406] = { id = 14406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crowleys Obstgarten", description = "Ihr erinnert Euch doch sicher an Lord Darius Crowleys Tochter Lorna.\n\nSie hat sich nie ganz vom Verlust ihres Vaters in Gilneas erholt. Seitdem fristet sie ihr Leben als Einsiedlerin. Der einzige Besucher, den sie je in ihr Haus gelassen hat, war Krennan... und er verliert kein Wort über die ganze Sache.\n\nBenachrichtigt sie über die Evakuierung.", sourceObjective = "Sprecht mit Lorna Crowley bei Crowleys Obstgarten.", completion = "Bleibt zurück! Sonst werde ich…\n\nSeid Ihr das? Beim Licht! Ihr seid es, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14407] = { id = 14407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azshara Blues", description = "He! Ich bin froh, dass ich Euch erwischt habe.\n\nIch komme im Auftrag meines Meisters, Kalec. Er benötigt Eure Hilfe. Sucht ihn unter der Brücke in den Slums so bald wie möglich auf!", sourceObjective = "Sprecht mit Kalec im Bilgewasserhafen.", completion = "Danke, dass Ihr gekommen seid. Ich muss mich für die Geheimnistuerei entschuldigen, aber es ist ungeheuer wichtig, dass ich von gewissen Individuen nicht gesehen werde.\n\nIch bin nämlich ziemlich in der Klemme und mir sind Eure Taten in letzter Zeit aufgefallen. Hört Euch an, was ich zu sagen habe, helft mir und ich werde dafür sorgen, dass Ihr angemessen belohnt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14408] = { id = 14408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuns Plan", description = "Meine Wohltäter haben ihre spärliche Intelligenz dazu benutzt, ein interplanetares Transportmittel zu konstruieren. Mit dem jetzigen Design ist diese sogenannte \"Rakete\" eine Todesfalle. Aber ich denke, dass eine Umarbeitung der Klappe des Treibstoffkatalysators eine stabile Mischung erbringt, die ein atembares Sauerstoffnebenprodukt liefern würde. Um derartige Veränderungen einzubauen, benötige ich die Originalbaupläne.\n\nFindet die Laborarchive und betätigt die Türglocke, um hineinzugelangen. Der Labordirektor selbst hat die Pläne, wenn er denn noch lebt.", sourceObjective = "Beschafft die geheimen Raketenbaupläne aus den Laborarchiven am östlichen Ende des Geheimlabors. Betätigt die Türklingel und tötet den Labordirektor, wenn er herauskommt.", progress = "Ich nehme an, dass die Archive sich in der Nähe befinden, {name}. Findet diese Pläne!", completion = "<Das Raptorenweibchen schnappt sich die Papiere mit ihren Greifklauen und hält sie sich vors Gesicht. Dabei klappert sie verächtlich mit den Zähnen.>\n\nDas sieht wie das Gekritzel von Kindern aus. Der gesunde Menschenverstand sagt, dass man die hydraulischen Kontrollen nicht so nah an die Brenner der zweiten Stufe legt. Immerhin, man kann noch etwas daraus machen.\n\nWisst Ihr, wie man eine Treibstoffmatrix so verändert, dass sich der Druck ändert und man eine bestimmte Beschleunigung erhält? Nein? Also schön, vielleicht könnt Ihr dann etwas anderes für mich erledigen, während ich die Rakete repariere...", sourceObjectiveStatus = "unverified-source-field" }
quests[14409] = { id = 14409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine vorsichtige Rückkehr", description = "Schenkt mir einen Moment Eurer Zeit, {class}.\n\nVeränderung liegt in der Luft. Sie hat uns aus den Ruinen von Eldre'Thalas gelockt, ein weiteres Mal hinaus in die weite Welt. Ich bin gekommen, um diese Stadt zu erforschen und darf von dieser Aufgabe nicht abweichen, doch wenn Ihr interessiert wärt, hätte ich einen Auftrag für Euch.\n\nMein Kollege ist auf dem Weg nach Darnassus, um mit der Hohepriesterin zu sprechen, auf dass wir eine Übereinkunft erreichen. Nehmt dieses Tagebuch und bringt es zu Mordent Schattenfall im Tempel. Es könnte ihm bei seiner diplomatischen Mission nützlich sein.", sourceObjective = "Bringt Mordent Schattenfall in DarnassusDaros' Tagebuch.", progress = "Es scheint, als hätte ich Zeit für eine Unterredung. Worum geht es?", completion = "Ah, Daros' Aufzeichnungen. Er war schon immer ein sehr sorgfältiger Chronist des Fortschritts. Seine Worte könnten helfen, zu erklären, wie weit wir gekommen sind.\n\nIhr habt meinen Dank dafür, dass Ihr mir dies hier gebracht habt, {race}. Vielleicht werden wir einander häufiger sehen, sobald erkannt wurde, dass wir niemandem schaden wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14410] = { id = 14410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wildnis von Feralas", description = "Es ist wahrlich heldenhaft von Euch, uns beim Schutz dieses Landes zu helfen. Solltet Ihr noch mehr für die Wildnis tun wollen - es gibt noch andere, die Eure Hilfe benötigen.\n\nIm Süden liegen die grünen Wälder von Feralas. Sucht im Schatten der mächtigen Zwillingskolosse nach Telaron Windsegler. Bei Träumersruh haben er und seine Druidenfreunde der Kralle Zeichen einer beunruhigenden Krankheit gefunden.\n\nSie werden Eure Hilfe benötigen, {class}. Geht in Frieden.", sourceObjective = "Reist nach Feralas und sprecht mit Telaron Windsegler bei Träumersruh.", completion = "Willkommen in Feralas, {class}. Ich danke Euch, dass Ihr gekommen seid, um uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14412] = { id = 14412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angespült", description = "Die Schiffe der Verlassenen sind viel zu nahe an unserer Fischerei gesunken. All die Überlebenden machen sich auf den Weg hierher. Wie Ihr sehen könnt, sind wir zahlenmäßig unterlegen.\n\nHelft uns, sie zurückzuhalten, während ich die Boote fertig repariere.", sourceObjective = "Tötet 6 schiffbrüchige Verlassene.", progress = "Verdammte Verlassene! Nicht einmal die See will sie haben!", completion = "Ausgezeichnet! Ich bin hier fast fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[14413] = { id = 14413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel des Lernens", description = "Ist das aufregend! Ihr fragt, was aufregend ist? Na, DIES ist natürlich aufregend!\n\nDie Zeit der Prüfungen....Zeit EURER Prüfungen. Es gilt, so viele Herausforderungen zu meistern, so vieles zu lernen. Ihr lernt etwas über Prüfungen. Ich lerne etwas über Euch.\n\nUnd jetzt geht nur. Zu meiner Arkanen Spitze. Natürlich werde ich Euch dort treffen, denn ich bin so ziemlich überall.", sourceObjective = "Sprecht mit dem Abbild von Erzmagier Xylem am Fuß der Arkanen Spitze.", completion = "Ihr seid schon da. Ich hoffe, Ihr hattet eine angenehme Reise. Euch ist doch nicht übel geworden, oder?\n\nEs wird viel Herumrennen und genausoviel Springen geben, deshalb ist ein ausgeglichener Magen von großem Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[14416] = { id = 14416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der hungrige Ettin", description = "Hört zu, {name}. Wir werden es ohne ein Transportmittel nicht weit schaffen, nicht wahr?\n\nWenn wir uns hier einfach nur so aus dem Staub machen, werden die Verlassenen uns im Handumdrehen einholen.\n\nNormalerweise wäre es überhaupt kein Problem, ein paar Pferde in den Stallungen im Südosten aufzutreiben, aber da gibt es einen Haken.\n\nDas letzte Erdbeben muss Koroth den Ettin aus den Bergen herunter zu uns vertrieben haben. Wenn wir uns die Pferde nicht bald schnappen, fürchte ich, dass er uns zuvorkommt.", sourceObjective = "Bringt 5 Gebirgspferde zu Lorna Crowley bei Crowleys Obstgarten.", completion = "Wir haben die Pferde. Ich stelle sicher, dass sie nach Dämmerhafen gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14418] = { id = 14418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.\n\nHawkins wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.\n\nAh, und wie konnte ich das vergessen?\n\nWillkommen bei den Todespirschern.", sourceObjective = "Bringt Androns Geschäftsbuch zu Aleric Hawkins in die Halle der Dunklen Fürstin in Unterstadt.", progress = "Ja?", completion = "Hmm, das ist interessant. Die Todespirscher haben ihre Pflicht bei der Erledigung dieser Aufgabe meisterlich erfüllt.\n\nWie mir gesagt wurde, verdient Ihr eine Belohnung für das, was Ihr in dieser Sache geleistet habt. Immer weiter so, {name}; die Todespirscher haben immer Verwendung für gute Männer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14419] = { id = 14419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Vorstellungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nUnser Anführer vermutet, dass Andron einer anderen Gruppe Unterstützung zuteilwerden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", sourceObjective = "Sprecht mit Andron Gant in Unterstadt.", progress = "Hallo. Kann ich etwas für Euch tun?", completion = "Ah, ja, ich habe Euch erwartet. Ich darf davon ausgehen, dass unsere gemeinsamen Bekannten mit den Informationen, die ich bisher lieferte, zufrieden waren?\n\nVermutlich hat es keinen Sinn, Euch zu fragen. Ich bezweifle, dass sie Euch mit diesem Wissen belasten würden. Warum so viel Vertrauen in den Boten setzen, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[14420] = { id = 14420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache der Dunklen Fürstin, so müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, {name}, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Unterstadt pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", sourceObjective = "Beschafft Astors Vorstellungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", progress = "Erfolgsmeldung?", completion = "Gut gemacht, {name}. Ihr habt den ersten Teil dieser Prüfung bestanden. Hoffentlich hat Andron keinen Wind von Euren Aktivitäten bekommen, sodass wir ihn davon überzeugen können, dass Ihr wirklich der Bote seid, den er erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14421] = { id = 14421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", sourceObjective = "Bringt Androns Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Unterstadt.", progress = "Erfolg, {name}?", completion = "Das sind eindeutig mehr Informationen, als ich mir je von Andron erhofft hätte. Lasst sie mich einen Moment studieren, bevor ich Euch Eure nächste Aufgabe nenne.", sourceObjectiveStatus = "unverified-source-field" }
quests[14422] = { id = 14422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Rakete", description = "Kurz nachdem meine Intelligenz erweitert worden war, habe ich mich mit Versuchsobjekt vier verpaart, um eine einzigartige Rasse geistig überlegener Raptoren zu erschaffen. Im Anschluss hat Versuchsobjekt vier weder angerufen, noch geschrieben: Ich habe beschlossen, ihn auseinanderzunehmen, wenn wir uns noch einmal begegnen.\n\nNichtsdestotrotz sind in diesem Labor genug Raptorenkinder gefangen, die einen angemessenen genetischen Grundstock bilden, um meine Rasse wieder aufleben zu lassen. Bitte befreit sie aus ihren Käfigen und tragt sie zu der Rakete.", sourceObjective = "Befreit fünf Versuchsraptoren aus ihren Käfigen im Geheimlabor und liefert sie bei der Rakete neben Versuchsobjekt neun ab.", completion = "Wunderbar! Eine beispielhafte Leistung, {name}! Wie Ihr Euch zweifellos schon gedacht habt, ist es mein Ziel, diese Rakete als eine Art Sternenwiege zu benutzen - eine Arche, wenn Ihr so wollt -, die es meiner neuerschaffenen Rasse erlaubt, den trostlosen Fesseln dieses geschundenen Planeten zu entfliehen und eine Welt zu kolonisieren, die uns gefällt. Ihr habt bei dieser Sache eine entscheidende Rolle gespielt. Bitte nehmt diese Währung an, da ich bei unserer Ankunft meine eigenen Geldeinheiten prägen werde. Lebt wohl, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14423] = { id = 14423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raupenexorzismus", description = ".. wir brauchen einen Priester!\n\nZum Glück habe ich ein bisschen Geld zur Seite gelegt, um die Maschinen segnen zu lassen. Nehmt diese Leuchtpistole und geht hinüber zu Margene, meiner armen, kleinen, kaputten Planierraupe Feuert das Signal ab und einer unserer besten fliegenden Priester sollte mit dem Fallschirm eintreffen, um die Situation unter Kontrolle zu bringen. Kommt zurück, wenn meine Planierraupe in guten Händen ist!", sourceObjective = "Benutzt die gesegnete Leuchtpistole in der Nähe von Clubniks Planierraupe, um Hilfe herbeizurufen, dann führt an der Planierraupe einen \"Exorzismus\" durch.", progress = "Wie geht es Margene? Läuft sie wieder so süß wie sie immer läuft?", completion = "Was? ...Was?\n\nMargene! Oh, meine süße Margene!", sourceObjectiveStatus = "unverified-source-field" }
quests[14424] = { id = 14424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Wissenschaft benötigt", description = "<Clubnik wischt sich eine Träne weg. Dann streckt er entschlossen sein Kinn vor.>\n\nNie wieder, {name}! Kein Bulldozer verdient das Schicksal meiner Margene. Wir werden professionelle Geisterjäger brauchen. Das ist ein Job für unsere besten Wissenschaftler und ich kenne genau die richtige Frau dafür! Sucht nach Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn. Sie ist die Verwalterin für Azsharas weltberühmtes Geheimlabor und sie schuldet mir einen Gefallen.", sourceObjective = "Findet Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn. Man kann die Goblinraketenbahn nutzen, um schnell durch Azshara zu reisen.", completion = "Wovon redet Clubnik da? Spukende Bauausrüstung? Seh ich so aus, als ob ich Zeit für Geistergeschichten hätte?\n\nIch habe ein Labor, das kurz vor der Schmelze steht, brennende Feuer, mutierte Tiere und das Schlimmste ... Projekte, die hinter den Zeitplan zurückfallen. Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[14427] = { id = 14427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenstandsquest", description = "Gegenstand einsammeln Quest", sourceObjective = "Holt die Gegenstände", sourceObjectiveStatus = "unverified-source-field" }
quests[14428] = { id = 14428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldwinds Tagebuch", description = "Wenn ich meinen Quellen vertrauen kann, überwacht Wissenshüterin Goldwind die Untersuchung der Ruinen durch die Allianz im Osten. Ich habe das Ausmaß ihrer Fähigkeiten noch nicht auf die Probe gestellt. Ich hoffe, Ihr könnt mir einen vollständigen Bericht liefern, nachdem Ihr sie zum Kampf gestellt und besiegt habt.\n\nJemand, der einen Titel wie 'Wissenshüter' trägt, wie Goldwind, wird ein Tagebuch bei sich haben, das uns sagen wird, was genau diese Nachtelfen vorhaben. Bringt mir dieses Tagebuch. Ihr müsst auch nicht zurück laufen, benutzt ihre Sehersteine, um mich aus der Ferne zu kontaktieren.", sourceObjective = "Tötet Wissenshüterin Goldwind im Darnassischen Basislager und bringt ihr Tagebuch in Euren Besitz.", progress = "<Andorels verzerrtes Gesicht taucht in dem Seherstein auf.>\n\n{name}, habt Ihr den Kontakt herstellen können? Was könnt Ihr mir mitteilen?", completion = "Goldwind hat sich ein Arkanes Konstrukt zunutze gemacht? Ha! Wie erfreulich unerfahren. Das ist, als ob man andere Kinder dabei beobachtet, wie sie mit Feuerwaffen spielen.\n\nSehen wir uns einmal das Tagebuch an, {name}. Haltet es vor den Seherstein... Haltet still...", sourceObjectiveStatus = "unverified-source-field" }
quests[14429] = { id = 14429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Dekonstruktion", description = "Arkane Konstrukte sind Kreaturen, die aus reinem Mana und Intelligenz ins Leben gerufen wurden. In den richtigen Händen befähigen sie ihre Nutzer, sich schnell riesige Mengen arkanes Wissen anzueignen. Aber sie sind gefährlich, {name}. So intelligent! So mächtig! So hilflos Manipulationen von außen ausgesetzt...\n\nLasst uns diesen Amateuren eine Lektion erteilen und ihre eigene Magie gegen sie verwenden. Tötet Lehrlinge und sammelt ihre Runensteine für mich ein. Nehmt über den Unteren Seherstein Kontakt mit mir auf, wenn Ihr fertig seid.", sourceObjective = "Tötet Angehende Ermittler und Angehende Illuminatoren um 10 Abgestimmte Runensteine einzusammeln.", progress = "<Andorels Bild ist verschwommen und unscharf. Er blinzelt Euch an und tippt gegen das Glas des Sehersteins.>\n\n{name}, seid Ihr das? Die Auflösung dieses Steins ist furchtbar. Was benutzen die nur für eine Hardware?", completion = "Gute Arbeit, diese Runensteine zu beschaffen. Um ehrlich zu sein, brauche ich nur einen, aber der Gedanke, dass so viele Nachtelfen für diese nutzlosen Kugeln getötet werden, bringt mir dunkle Freude, die mich ganz schwindelig macht.\n\nBitte haltet eine dieser Runen hoch vor den Seherstein, damit ich sie sehen kann. Hmmm. Wie ich mir bereits dachte - das ist bestenfalls dilettantisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[14430] = { id = 14430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Konstrukt hacken", description = "Jetzt werden wir ihr arkanes Konstrukt hacken und es dazu benutzen, Chaos anzurichten. Habt Ihr diese Art Magie schon einmal verwendet, {name}? Nein? Ha! Das macht meinen Plan noch delikater. In der Nähe solltet Ihr ein beeindruckendes arkanes Konstrukt sehen, das sie herbeigerufen haben. Dank der Runensteine, die ihr gesammelt habt, wissen wir, wie man mit ihm kommuniziert. Sprecht mit dem Konstrukt und sagt:\"Al'teth la c'tolgar.\" Verstanden? Wiederholt es? Sollte reichen. Meldet Euch wieder bei mir und lasst mich wissen, was geschehen ist.", sourceObjective = "Sprecht mit dem arkanen Konstrukt im Darnassischen Basislager und sprecht die Worte der arkanen Macht.", completion = "Haha! Ha - HA! Nachtelfische Magier, die vor ihrer eigenen, arkanen Kreation flüchten. Eure Taten haben mir den ganzen Monat versüßt, {name}. Deshalb benutzen wir Blutelfen die arkanen Konstrukte nicht länger - sie wurden vor, oh, ungefähr 1500 Jahren für ungesetzlich erklärt. Es ist schon lustig für mich zu sehen, wie unsere Feinde die Fehler der Vergangenheit wiederholen. \"Magier\". Dass ich nicht lache.", sourceObjectiveStatus = "unverified-source-field" }
quests[14431] = { id = 14431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarzschlund-Narbe", description = "Die Furbolgs des Schwarzschlunds haben mit ihren Brüdern vom Holzschlund gebrochen, als wir begannen, Azshara aggressiv zu besiedeln. Sie sind wild geworden, {class}, und belästigen unsere Streitkräfte, wo sie nur können. Schlimmer noch - ich habe gesehen, wie sie den Nachtelfen von Talrendis freundlich begegnet sind. Wir können den beiden nicht erlauben, sich zu verbünden!\n\nGenau im Südwesten von hier findet Ihr eine große Narbe quer über die Erde. Von dort melden meine Späher Aktivitäten der Nachtelfen. Tötet sie und sammelt so viele Informationen, wie Ihr finden könnt.", sourceObjective = "Tötet 8 Biologen der Talrendisspitze und nehmt die Geheimdienstinformationen des Schwarzschlunds von einer der Leichen an Euch.", progress = "Die Schwarzschlundfurbolgs sind wild. Wenn sie sich jemals zusammenraufen sollten, würde das unsere Arbeit hier sehr behindern.", completion = "Ich verstehe... Das sieht aus wie die Rohfassung eines Abkommens. Der Ernstfall ist also eingetreten, {name}: Nachtelfen koordinieren ihre Angriffe mit unbeugsamen Furbolgverbündeten.\n\nMein erster Instinkt - ein Frontalangriff - würde sie nur in die Arme der Allianz treiben. Wir müssen uns etwas anderes überlegen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14432] = { id = 14432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fahles Gebräu", description = "Es sieht so aus, als ob unsere Feinde der Allianz uns bei den Gesprächen mit den Schwarzschlund voraus sind, weil sie die Verhandlungen in Furbolgsprache führen. Wenn wir das Abkommen sabotieren wollen, müssen wir das genauso machen.\n\nDas ist nicht so schwer, wie es klingt, {name}. Die Schwarzschlundfurbolgs machen einen starken Kräutertee. Durch seine Dämpfe wird man in eine Art Trance versetzt, in der man beginnt, in Zungen zu reden. Genauer gesagt in der Zunge der Schwarzschlund. Geht zur Schwarzschlundfeste südwestlich von hier und besorgt mir einige Proben von diesem Strauchwurzelgebräu!", sourceObjective = "Sammelt 10 Proben Strauchwurzelgebräu außerhalb der Schwarzschlundfeste.", progress = "Was macht die Jagd? Ich habe das Strauchwurzelzeugs selbst einmal probiert, aber es war zu bitter, sogar für einen alten Kiesfresser wie mich.", completion = "Ah gut, das ist reichlich. Wir kochen das Zeug jetzt auf und Ihr könnt eine Weile die Dämpfe einatmen. Es wird nicht lange dauern, dann sprecht Ihr wie ein Furbolg. Unser Plan nimmt allmählich Gestalt an...", sourceObjectiveStatus = "unverified-source-field" }
quests[14433] = { id = 14433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatie mal anders", description = "Um die Verhandlungen mit den Schwarzschlundfurbolgs zu unterwandern und zu stören, müssen wir wissen, wo sie stattfinden. Ich vermute, Ihr werdet in der Schwarzschlundfeste im Südwesten Botschafter der Nachtelfen vorfinden, die dort geschäftig umherlaufen und Vorbereitungen treffen.\n\n<Haggrum spuckt auf den Boden.>\n\nTötet sie nach Belieben und durchsucht die Gegend nach wichtigen Dokumenten. Oh, und wenn Ihr schon da seid - bringt doch eine Botschafterrobe mit... wir werden sie benötigen.", sourceObjective = "Bringt eine Versammlungsagenda des Schwarzschlunds in der Schwarzschlundfeste an Euch und tötet einen Botschafter der Talrendisspitze, um eine Botschafterrobe in Euren Besitz zu bringen.", progress = "Habt Ihr die Robe? Andorel hat ein bisschen Magie für uns auf die Schnelle bereitgestellt, die wir benutzen können.", completion = "Ihr habt vorzügliche Arbeit geleistet! Lasst mich diese Dokumente einmal sehen. Hmm. Jetzt wissen wir genau, wann und wo die abschließenden Verhandlungen stattfinden werden. Macht Euch keine Sorgen, wenn Euch die Robe nicht passt - ich habe schon alles geplant.", sourceObjectiveStatus = "unverified-source-field" }
quests[14434] = { id = 14434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rut'theran", sourceObjective = "Seid Ihr bereit, die Segel zu setzen, {name}? Euer Volk hat im Land der Kaldorei eine Zuflucht gefunden.\n\nSeid unbesorgt, {race}. Euer Volk wird die Chance haben, wieder für Gilneas zu kämpfen. Dieses Mal mit der ganzen Macht der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[14435] = { id = 14435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppeltes Spiel bei den Schwarzschlund", description = "Andorel hat ein bisschen Magie für mich bereitgestellt. Kommt, stellt Euch neben mein Feuer und taucht in die Dämpfe des Tees ein. Legt die Robe an und Ihr werdet für die Schwarzschlundfurbolgs wie ein Botschafter der Nachtelfen aussehen.\n\nLegt Eure Verkleidung an und sprecht mit Andorel hier im Lager. Er wird Euch in das Herz der Schwarzschlundfeste teleportieren, wo die Verhandlungen stattfinden werden. Sprecht mit Häuptling Ungarl und sabotiert das Abkommen. Dann tötet auf Eurem Rückweg so viele Schwarzschlundfurbolgs wie möglich!", sourceObjective = "Tragt die Verkleidung als Botschafter und sprecht mit Andorel Sonnenschwur, damit er Euch in die Schwarzschlundfeste teleportiert. Sprecht mit Ungarl, um die Verhandlungen zunichte zu machen, dann tötet 4 Krieger des Schwarzschlunds und 4 Schamanen des Schwarzschlunds auf dem Weg nach draußen.", progress = "Wenn unsere List aufgeht, {name}, werden wir für immer einen Keil zwischen die Allianz und die Schwarzschlundfurbolgs treiben.", completion = "Sieg! Die Schwarzschlundfurbolgs wissen jetzt nicht mehr, wem sie trauen sollen.\n\nJetzt, da wir dieses heikle Geschäft erledigt haben, kann ich einen Frontalangriff auf diese Ungeheuer organisieren, ohne dass ich mir Sorgen darüber machen muss, dass sie sich mit der Allianz zusammenschließen.\n\nIhr leistet gute Arbeit, {name}. Vielleicht sollten wir Euch eine Stelle im diplomatischen Corps der Horde verschaffen? Har-har!", sourceObjectiveStatus = "unverified-source-field" }
quests[14436] = { id = 14436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenbuddelei", description = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.\n\nSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.\n\nIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Donnerfels, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.", sourceObjective = "Sammelt 5 Ausgrabungsleiterhacken ein.\n\nZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.\n\nBringt Ahmo Donnerhuf im Dorf der Bluthufe 5 zerbrochene Werkzeuge.", sourceObjectiveStatus = "unverified-source-field" }
quests[14437] = { id = 14437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, {name}.\n\nReist ins Dorf der Bluthufe und sprecht mit Ahmo Donnerhuf. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Donnerfels verdienen.\n\nBringt Ahmo dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.\n\nFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr könntet Euch sonst verirren.", sourceObjective = "Bringt Ahmo Donnerhuf im Dorf der Bluthufe Falkenwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14438] = { id = 14438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Nutzung des Landes", description = "Viele Konflikte verwunden dieses Land, {name}. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.\n\nBleichmähnengnolle haben sich südlich vom Dorf der Bluthufe und in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.\n\nWorte allein genügen nicht mehr als Antwort.", sourceObjective = "Tötet 15 Gnolle der Bleichmähnen und kehrt dann zu Ahmo Donnerhorn ins Dorf der Bluthufe zurück.", completion = "Es ist gut, dass Ihr meine Aufgabe so ernst genommen habt, {name}. Respekt vor dem Land und seinen Kreaturen ist wichtig. Tod und Leben bilden einen Kreis... eine Notwendigkeit. Das eine kann nicht ohne das andere existieren. Nehmt Euch einen Moment Zeit, um darüber nachzudenken, und vergesst es niemals.", sourceObjectiveStatus = "unverified-source-field" }
quests[14439] = { id = 14439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Donnerfels", description = "Jetzt wird man Euch in unserer großen Stadt verehren. <Ein/Eine:r> {race}, <der/die> würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nSucht unseren jungen Anführer Baine Bluthuf auf, um Eure letzte Aufgabe zu erhalten. Er residiert auf der höchsten Anhöhe in Donnerfels.", sourceObjective = "Sprecht mit Baine Bluthuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[14440] = { id = 14440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Donnerfels verdient.\n\nUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.\n\nWir sind Jäger, {name}. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.", sourceObjective = "Baine Bluthuf in Donnerfels möchte, dass Ihr ihm das Horn von Arra'chea bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14441] = { id = 14441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garroshs Autogramm", description = "Man sagt, dass Garrosh Höllschrei einer der größten Helden der Horde ist! Wenn ich einmal groß bin, will ich auch so ein Held sein!\n\nKennst du Garrosh, {name}? Könntest du mir einen Gefallen tun, bitte? Kannst du sein Autogramm für mich bekommen? Ich weiß nicht, wie ich ihn fragen soll, und wahrscheinlich würde er jemandem wie mir gar nicht zuhören... aber du! Du bist ein Abenteurer wie er! Ich wette, dass er dir mir nichts, dir nichts ein Autogramm geben wird!\n\nBitte?", sourceObjective = "Reist nach Orgrimmar und kümmert Euch darum, für Euren Schützling ein Autogramm von Garrosh Höllschrei zu bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14442] = { id = 14442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Lieblingsversuchsobjekt", description = "Ich weiß nicht, ob Ihr es bemerkt habt, {name}, aber dieser ganze Laborkomplex ist jenseits von Gut und Böse! Mir ist es ja egal, diese ganzen Hippogryphen abzuschreiben, aber mein wertvollstes Experiment ist abhandengekommen: Versuchsobjekt neun!\n\nVersuchsobjekt neun ist ein weiblicher Raptor, den wir aus dem Brachland importiert haben. Ich frage mich, ob sie noch am Leben ist? Versucht einmal, oberhalb des Hauptgebäudes westlich von hier nachzusehen, in der Nähe der riesigen, streng geheimen Rakete. Ihr könnt es nicht übersehen.", sourceObjective = "Findet Versuchsobjekt neun irgendwo in der Nähe des Geheimlabors in Azshara.", completion = "Seid Ihr gekommen, um mir bei meiner Arbeit zu helfen? Meine Klauen sind recht geschickt, aber ich muss ich widerwillig zugeben, dass meine Arme extrem kurz und deswegen hinderlich sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[14443] = { id = 14443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ramponierte Schwertgriff", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Der Silberbund wäre sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", sourceObjective = "Bringt den ramponierten Schwertgriff zu Caladis Prunkspeer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", progress = "Was habt Ihr denn da?", completion = "<Caladis nimmt Euch den Schwertgriff ab und begutachtet ihn langsam drehend in seiner Hand.>\n\nDer kommt mir irgendwie bekannt vor, als müsste ich wissen, woher er kommt. Ihr habt ihn in der Zitadelle gefunden? Äußerst interessant.\n\nEs gibt nur wenige, welche die Fähigkeit besitzen, solch eine Klinge herzustellen. Vielleicht können sie uns etwas über Euren Fund sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14444] = { id = 14444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Drachen", description = "Es gibt keinen Zweifel: Dieser Schwertgriff stammt von einer mächtigen, uralten Waffe - aber welcher? Ich kann mich nicht daran erinnern, ein Schwert mit solchen Markierungen gesehen oder davon gehört zu haben, was jedoch nicht heißt, dass wir in einer Sackgasse gelandet sind.\n\nKorialstrasz, besser bekannt als Krasus, ist schon seit Langem ein Freund der Quel'dorei und der Kirin Tor. Seinem immensen Wissen und seinen gewaltigen Ressourcen nach zu urteilen wird er mit Sicherheit etwas wissen. Reist zur Spitze des Wyrmruhtempels und ersucht ihn um Rat. Meldet Euch anschließend bei Arkanist Tybalin im Inneren der Silbernen Enklave in Dalaran.", sourceObjective = "Sprecht mit Krasus in der Spitze des Wyrmruhtempels.", completion = "Wir dürfen das Buch nicht in den Händen der Sonnenhäscher belassen. Wenn wir das Schwert identifizieren und zu unserem Vorteil nutzen wollen, müssen wir einen Weg finden, an das Buch heranzukommen, das Krasus ihnen geliehen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[14445] = { id = 14445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschied auf Zeit", description = "Unsere Schicksale sind bis auf alle Ewigkeit miteinander verwoben. Es geschehen Dinge, die unsere Welt verändern und schließlich zerstören werden. Wir müssen ihnen ein Ende setzen, bevor es zu spät ist.\n\nVergesst nicht, Ihr könnt Euch immer auf mich verlassen, <Bruder/Schwester>! Wir werden uns auf der größeren Insel erneut sehen. Möget Ihr bis dahin Frieden finden, {name}.", sourceObjective = "Sprecht mit Sassy Hartzang an der Wilden Aussicht auf den Verlorenen Inseln.", completion = "Kann ich meinen Augen trauen? Seid Ihr das wirklich?\n\nIhr habt Thrall, den Kriegshäuptling der Horde gerettet?!\n\n<Sassy wirft Euch einen anerkennenden Blick zu.>\n\nNun, dann schauen wir mal, wie wir zu der größeren Insel gelangen. Bei all den Haien da unten habe ich wirklich keine Lust zu schwimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14446] = { id = 14446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kataklysmus!", description = "Hört mich an, {class}!\n\nDie Winde das Wandels haben sich zu einem gewaltigen Sturm vereint, der über ganz Azeroth hinwegfegt.\n\nSeid Ihr kühn genug, Euch dem wahren Grund für unser Elend zu stellen?\n\nNehmt Euren ganzen Mut zusammen, {race}, und betet, dass Stärke und Glück Euch bei den bevorstehenden Prüfungen helfen werden.\n\nEin unerwarteter Verbündeter hat einen Ruf an alle ausgestoßen, die ihn hören. Schaut in das Wasser der Weitsicht und erhascht einen Blick auf das Schicksal der Welt!", sourceObjective = "Nambria möchte, dass Ihr in das Wasser der Weitsicht blickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14447] = { id = 14447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Insider", description = "Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.", sourceObjective = "Himmelshäscher Korm möchte, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[14448] = { id = 14448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Insider", description = "Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.", sourceObjective = "Himmelshäscher Korm möchte, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[14449] = { id = 14449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Was Ihr hier seht, ist das Werk der Stacheleber, mein Kind. Jahr für Jahr sind sie in unser Dorf eingefallen. Durch den großen Kataklysmus sind sie nun aus ihren Dornen hervorgekommen und haben sich wie Heuschrecken im ganzen Land breitgemacht. Das Ergebnis sieht man nur allzu gut; selbst meine Mutter starb aufgrund ihrer Wildheit.\n\nHeute ist der Tag, an dem Ihr Eure Volljährigkeit erreicht. Heute ist der Tag, an dem Ihr Eure Waffe nehmen, für den Klan kämpfen und Großmutter Falkenwind rächen werdet. Folgt dem Weg nach Osten - dort werdet Ihr meinen Sohn Grull finden. Er wird Euch bei Eurem Angriff auf die Stacheleber anführen.", sourceObjective = "Folgt dem Weg, der aus Camp Narache nach Osten führt und sucht Grull Falkenwind auf.", completion = "Willkommen zu Eurer ersten richtigen Prüfung als {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14450] = { id = 14450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randomdrop-Test Progressiv", description = "Diese Quest testet Zufallsdrops mit progressiver Prozentzahl für Drops.", sourceObjective = "Beschafft 10 progressive Dingse.", sourceObjectiveStatus = "unverified-source-field" }
quests[14451] = { id = 14451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randomdrop-Test FlatRate", description = "Diese Quest testet Zufallsdrops mit Flatrate-Prozentzahl für Drops.", sourceObjective = "Beschafft 10 Flatratedingse.", sourceObjectiveStatus = "unverified-source-field" }
quests[14452] = { id = 14452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Kraft", description = "Merkt auf, {name}. Allein schon die Anwesenheit der Borstennacken macht diesen Ort zu einem Schandfleck. Wo sie sind, bleibt nichts übrig außer Leichen und Brachland. In Camp Narache könnte es in nur wenigen Tagen genau so aussehen wie hier, wenn wir nicht standhaft bleiben und kämpfen.\n\nDies wird Euer Ritus der Kraft - die erste Zeremonie, die einem Kriegerhelden der Tauren gewährt wird. Begebt Euch ins Herz von Dornknoten und tötet die Stacheleber der Borstennacken. Kehrt daraufhin zu mir zurück.", sourceObjective = "Tötet 6 Eindringlinge der Borstennacken.", completion = "Ihr habt gut gekämpft, {name}. Wir können vielleicht noch gerettet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14454] = { id = 14454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Krieger", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Kriegerheld Scharfhorn, einen jungen Kriegerlehrer, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen Schlüssel für den Käfig und befreit ihn!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Kriegerheld Scharfhorn gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[14455] = { id = 14455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Dornenrufer auf", description = "Die Eigenheiten seiner Beute zu kennen ist ein sehr wichtiger Aspekt bei der Jagd. In ihrer Heimat leben die Stacheleber in den Schatten und im Schutz großer Dornenwurzeln. Wenn sie unterwegs sind, pflanzen die Schamanen Samen, um neue Dornenbehausungen wachsen zu lassen.\n\nDiese Dornen schädigen das Land und entziehen allen anderen Pflanzen das Leben, so dass ein Brachland entsteht. Reist nach Süden und haltet die Dornenrufer auf, bevor sie noch mehr Land zerstören können, {name}.", sourceObjective = "Tötet 7 Dornenrufer der Borstennacken.", completion = "Nun, da die Dornenrufer tot sind, wird die Erdenmutter ihre eigenen Wunden selbst heilen können. Die Wurzeln sind nicht für diesen Ort bestimmt und werden eingehen. Das Gleichgewicht wird wieder hergestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14456] = { id = 14456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus des Muts", description = "Etwas, dass Ihr bereits sehr früh erlernen müsst, ist, Eure Beute nie zu unterschätzen, {name}.\n\nWährend wir durch die Angriffe in Camp Narache abgelenkt waren, haben einige Borstennacken sich unbemerkt angeschlichen und eine Kiste mit Gewehren geklaut. Ihr könnt von hier aus sehen, wie sie im Süden nun die Luft mit Blei füllen.\n\nDies wird Euer Ritus des Muts: stellt Euch dem Regen der Gewehrschüsse, jagt die Waffendiebe der Borstennacken, und bringt uns unsere Gewehre zurück.", sourceObjective = "Holt 7 gestohlene Gewehre von den Waffendieben der Borstennacken zurück.", progress = "Wie viele der gestohlenen Gewehre konntet Ihr an Euch bringen, Initiand?", completion = "Gut gemacht, {name}. Zeigt Respekt vor Eurer Beute und der Gefahr, die mit ihr verbunden ist, aber fürchtet sie nicht. Wer Furcht zeigt, wird selbst zur Beute.", sourceObjectiveStatus = "unverified-source-field" }
quests[14457] = { id = 14457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan der Sonnenhäscher", description = "Einer meiner Kontakte unten in den Kanälen der Schattenseite hat in der Nähe des Schwarzmarktes einen Agenten der Sonnenhäscher erblickt. Die Sonnenhäscher sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und kümmert Euch um ihn. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass sie ihn zuerst zurück nach Eiskrone bringen.", sourceObjective = "Gelangt an die Befehle der Sonnenhäscher.", progress = "Habt Ihr irgendetwas Brauchbares bei dem Agenten finden können?", completion = "<Arkanist Tybalin sieht sich die gefundenen Befehle genauer an.>\n\nDer Agent, den Ihr abgefangen habt, sollte, nachdem er sich mit einem gewissen Magister Hathorel in Sonnenhäschers Zuflucht getroffen hat, den Folianten nach Eiskrone bringen. Wir müssen dieses Buch bekommen, {name}, und das ist unsere Chance. Es wird jedoch nicht einfach sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14458] = { id = 14458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Adana auf", description = "Wir konnten gegen die Borstennacken hier einiges ausrichten. Ich werde hier bleiben und das Gebiet sichern, aber Ihr müsst weiterreisen.\n\nSucht Adana Donnerhorn auf; sie ist mit ein paar Kriegerhelden nach Südwesten aufgebrochen, um den Rest der Borstennacken auszumerzen.", sourceObjective = "Sucht Adana Donnerhorn im Südwesten auf.", completion = "Es liegen noch weitere Prüfungen vor Euch, {name}. Ich hoffe, Ihr seid gut vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14459] = { id = 14459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kampfeber", description = "Es gibt noch mehr Gefahren, um die wir uns kümmern müssen. Die Borstennacken zähmen wilde Eber und bilden sie zu Kampfebern aus, die im Kampf gegen uns genutzt werden sollen.\n\nDiese gepanzerten Kampfeber wurden ohne Hoffnung auf jegliche Erholung gequält und missbraucht. Sie müssen getötet werden, im Namen unserer Sicherheit und ihres Friedens. Begebt Euch zu den Pferchen im Süden und tötet die Eber, {name}. Kehrt danach wieder zu mir zurück.", sourceObjective = "Tötet 10 gepanzerte Kampfeber.", completion = "Gute Arbeit, {name}. Diese Bestien hätten eine größere Bedrohung als die Borstennacken selbst darstellen können, wenn wir uns nicht rechtzeitig um das Problem gekümmert hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14460] = { id = 14460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Ehre", description = "Diese Stacheleber unterstehen Häuptling Quieker Dornenmantel. Er war es, der beim Angriff auf Camp Narache das Leben von Großmutter Falkenwind genommen hat. Nach dieser grauenvollen Tat ist er geflohen und hat sich versteckt, aber wir haben ihn ausfindig gemacht. Er befindet sich westlich von hier in einem garstigen Dornennest und schafft es, alle Kriegerhelden abzuwehren, die wir schicken, um sich seiner anzunehmen.\n\nIhr habt Euch als mutiger Verteidiger unseres Volkes herausgestellt, {name}. Tötet Dornenmantel und bringt Häuptling Falkenwind seine Mähne, um Großmutter Falkenwind zu ehren!", sourceObjective = "Tötet Häuptling Quieker Dornenmantel.", progress = "Habt Ihr Eure Prüfungen abgeschlossen, Kind?", completion = "<Häuptling Falkenwind hält die Mähne von Dornenmantel über seinen Kopf.>\n\nDer Häuptling der Borstennacken ist gefallen. Der Geist von Großmutter Falkenwind wurde gerächt!", sourceObjectiveStatus = "unverified-source-field" }
quests[14461] = { id = 14461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futter des Bösen", description = "Wir müssen weitaus mehr tun, als nur Eber zu jagen. Der Anblick dieses Landes bereitet Augenschmerzen, und das muss geändert werden.\n\nUm die Kampfeber mit einem ungemeinen Blutdurst zu versehen, werden sie mit rohem Fleisch zwangsernährt. Nehmt diese Fackel und benutzt sie, um die Tröge mit dem Fleisch und dem Blut in Flammen zu setzen.", sourceObjective = "Benutzt Adanas Fackel, um alle 3 Tröge im Kriegseberpferch in Flammen zu setzen.", completion = "Ihr habt nicht nur die Kriegseberpferche gereinigt, sondern auch dieser furchtbaren Entweihung ein Ende gesetzt. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[14462] = { id = 14462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist mein Kopf?", description = "Er ist hier, {name}. Hauptmann Grunwald ist ein hochrangiger Allianzoffizier aus der Feste Nordwacht. Zweifellos ist er hier, um einen Angriff auf Orgrimmar mit seinen Nachtelfenverbündeten zu koordinieren. Wir haben beobachtet, wie er in den Turm südwestlich von hier gegangen ist. Ich will seinen Kopf, {class}. Ich will ihn zurück nach Nordwacht schicken, um einen Keil zwischen unsere Feinde zu treiben!\n\nIch habe eine Goblinattentäterin, Slinky Scharfklinge, zum Turm geschickt, aber sie ist nicht zurückgekommen. Geht und findet sie. Und bringt mir diesen Kopf!", sourceObjective = "Ihr wurdet ausgeschickt, um Euch mit der Goblinattentäterin Slinky Scharfklinge am Fuß des nördlichen Turms von Talrendisspitze zu treffen.", completion = "Ihr kommt gerade rechtzeitig, {class}. Ich will gerade ein blitzschnelles, Präzisionsattentat verüben. Mal sehen...\n\nSprengstoff? Ist da.\n\nPneumatische Enterhaken? Sind da.\n\nTragbarer Fallschirm? Ist da.\n\nLähmendes Nervengift?\n\n\n\nAufgetragen. Dann mal los!", sourceObjectiveStatus = "unverified-source-field" }
quests[14463] = { id = 14463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pferde für Dämmerhafen", description = "Die Pferde gerettet zu haben, könnte bedeuten, dass auch die Stadt gerettet ist. Es gibt zwar ausreichend Karren in Dämmerhafen, aber nicht genügend Pferde, um sie zu ziehen.\n\nGeht und sagt Bürgermeisterin Armstead, dass die Pferde, die Ihr gerettet habt, zu ihrer Verfügung stehen.\n\nIch bereite alles vor und stoße dann bald zu Euch.", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Hervorragende Arbeit, {name}. Ich denke, ich spreche für alle, wenn ich sage: Je früher wir hier herauskommen, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[14464] = { id = 14464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzschnelles Attentat", description = "Am Fuß des Turms patrouillieren Elitewachen des Hauptmanns. Also wir machen das so: Wir hangeln uns mit den Enterhaken bis nach oben, schnetzeln die VIPs und machen uns mit meinem tragbaren Tiefflugfallschirm davon. Ich werde den Turm mit Sprengstoff spicken, damit er hinter uns explodiert. Ihr stellt sicher, dass Ihr Hauptmann Grunwalds Kopf für Chawg mitbringt. Kapiert?\n\nIhr dürft diese Mission nur DANN annehmen, wenn Ihr zu UNGEBREMSTER GEMEINHEIT fähig seid. Ist das klar?", sourceObjective = "Sprecht mit Slinky Scharfklinge, um auf den Turm zu klettern und Hauptmann Grunwald zu töten. Holt Hauptmann Grunwalds Kopf.", progress = "Ich gehe davon aus, dass Ihr gute Nachrichten habt, {name}?", completion = "Ich bin von der Schlauheit unserer neuen Goblinverbündeten beeindruckt, aber Ihr habt mich noch mehr beeindruckt, {name}. Schaut Euch den entsetzten Ausdruck an, der auf dem Gesicht des Hauptmanns eingefroren ist! Er hat Euren Angriff nicht kommen sehen. Stellt Euch die Angst vor, die das in Nordwacht hervorrufen wird, wenn sie sehen, was einem ihrer geschätzten Offiziere in den Ländern der Nachtelfen geschehen ist.\n\nGut gemacht, {class}. Unser Angriff geht weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[14465] = { id = 14465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Graumähnenanwesen", description = "Es ist an der Zeit, alle in Sicherheit zu bringen. Das gilt auch für Euch, {name}. Begebt Euch zum Graumähnenanwesen. Die anderen werden Euch in Kürze folgen.\n\nMacht Euch um mich keine Sorgen. Ich kümmere mich darum, dass alle heil hier rauskommen. Ja, sogar die paar Wilden, die wir in den Ställen eingesperrt haben.\n\nSobald Ihr dort angekommen seid, sprecht mit Königin Graumähne über die Dringlichkeit der Lage.", sourceObjective = "Sprecht mit Königin Mia Graumähne im Graumähnenanwesen.", completion = "{name}. Ich habe schon so viel von Euch gehört.\n\nWie ich hörte habt Ihr beim Überleben meiner Familie während des Ausbruchs in Gilneas eine wichtige Rolle gespielt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14466] = { id = 14466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Observatorium des Königs", description = "Ihr solltet mit Genn sprechen. Seit dieses Martyrium begonnen hat, hat er sich in seinem Observatorium eingeschlossen.\n\nIch bin mir sicher, dass er an einem Plan für sein Volk arbeitet. Er ist ein sehr eigensinniger Zeitgenosse.", sourceObjective = "Sprecht mit König Genn Graumähne im Observatorium des Graumähnenanwesens.", completion = "Da seid Ihr ja, {name}. Ich habe Euch erwartet.\n\nIch habe von Eurer Genesung gehört und… Wartet! Spürt Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[14467] = { id = 14467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh weh, Gilneas!", sourceObjective = "Schaut, {name}! Schaut nur, was aus Dämmerhafen geworden ist!\n\nSchaut, was aus dem letzten sicheren Ort in Gilneas geworden ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[14468] = { id = 14468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein warmer Körper", description = "Oh, ich habe ein tolles Angebot für Euch! Taucht ein in fremde Kulturen, genießt epische Abenteuer, sprengt Dinge in die Luft und lasst Euch dafür auch noch bezahlen! Klingt zu gut, um wahr zu sein? Tja, ist es aber! Genau das tun wir!\n\nWenn Ihr Interesse habt, meldet Euch bei Gallywix' Verteidigungsposten am Einsamen Grat im Norden und haltet nach Kommandant Molotov Ausschau.", sourceObjective = "Meldet Euch bei Kommandant Molotov am Einsamen Grat.", completion = "Der neuste Rekrut, was?\n\nIch fasse mich kurz. Wir wurden angeheuert, um die Naga in den Ruinen von Gallywix und seinem Eigentum fern zu halten. Ihr tut, was wir Euch sagen und ich sorge dafür, dass man Euch am Ende dafür entlohnt.\n\nWillkommen im Bilgewässer Bataillon.", sourceObjectiveStatus = "unverified-source-field" }
quests[14469] = { id = 14469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus zweiter Hand", description = "Zunächst brauchen wir mehr Vorräte für Euch und die anderen neuen Rekruten. Unser letzter Schwung Rekruten, oder besser gesagt ihre Leichen auf dem Minenfeld im Norden, haben noch taugliche Standardversorgungspacks bei sich.\n\nMacht nicht den gleichen Fehler wie sie. Versucht, den Minen auszuweichen.", sourceObjective = "Beschafft Euch 12 Militärversorgungspacks vom mittleren Minenfeld.", progress = "An wiederverwerteten Dingen ist nichts auszusetzen.", completion = "Ihr seid ein ganz gewandtes Schlitzohr, was? Gute Arbeit.\n\nHier habt Ihr ein bisschen was, was Euch am Leben halten soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[14470] = { id = 14470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Militärischer Durchbruch", description = "Wir haben den Kontakt zu Unteroffizier Dynamo verloren, der am nächsten Grat nördlich des mittleren Minenfelds stationiert ist. Wahrscheinlich wurden er und seine Leute überrannt.\n\nEr hatte unsere letzte BGG. Geht zu ihm und holt sie zurück. Löscht alle Naga aus, die unsere Linien durchbrochen haben.", sourceObjective = "Tötet Kriegsherr Krellen und beschafft Euch die BGG.", progress = "Wo ist mein Raketenwerfer, Rekrut?", completion = "Gute und schnelle Arbeit, Rekrut.\n\nIst sie nicht eine Schönheit? Ich habe sie selbst zusammengebaut. Und ich habe ganz besondere Pläne für dieses Schätzchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14471] = { id = 14471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mörser ersten Grades", description = "He Kumpel! Mögt Ihr Explosionen? Natürlich tut Ihr das. Wie kann man Explosionen auch nicht mögen?!\n\nIch habe am Grat Mörser aufstellen lassen, um die Naga zurückzuhalten. Los, Rekrut! Mörsert sie… Mörsert sie alle! Ahahaha!", sourceObjective = "Benutzt einen Goblinmörser, um 60 Angreifer der Grollflossen zu töten.", completion = "Kaum zu glauben, dass sie uns dafür auch noch BEZAHLEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[14472] = { id = 14472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dahin, wo es weh tut!", description = "Die Naga bringen diese Riesen dazu, Pfade durch unsere Minenfelder zu trampeln. Es ist Zeit, unsere BGG einzusetzen!\n\nBegebt Euch zum Eingang des südlichen Minenfelds. Den Rest könnt Ihr Euch sicher denken.", sourceObjective = "Benutzt eine BGG, um einen versklavten Sohn von Arkkoroc auf dem südlichen Minenfeld zu töten.", completion = "BÄMM! Mitten ins Gesicht! Guter Schuss, Kleiner!", sourceObjectiveStatus = "unverified-source-field" }
quests[14473] = { id = 14473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt ist es unser Problem", description = "Sieht aus, als würden diese Affen einfach alles stehlen, was nicht niet- und nagelfest ist! Diese diebischen kleinen Monster haben die Teraptormatriarchin zur Weißglut gebracht, indem sie ihre Eier gestohlen haben. Aber was noch schlimmer ist: Die Eier sind geschlüpft! Jetzt rennen hier überall hungrige Teraptorjunge herum und haben uns als schnelle Mahlzeit auserkoren!\n\nWir haben nicht damit angefangen, aber jetzt ist es unser Problem. Ihr müsst in den Dschungel gehen und diese hungrigen Teraptorjungen töten, bevor sie uns alle töten.", sourceObjective = "Tötet 6 Teraptorjunge.", completion = "Hoffen wir einfach mal, dass wir uns später nicht mit ihrer Mama auseinandersetzen müssen. Das wäre alles andere als gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[14474] = { id = 14474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungskapseln der Goblins", description = "{name}, es tut mir leid. Ich dachte, Ihr wärt tot!\n\nEs ist einfach Irrsinn! Wir sind direkt in einen Kampf zwischen der Allianz und der Horde gesegelt.\n\nWir müssen unsere Brüder und Schwestern retten.\n\n<Er zeigt auf die Rettungskapseln, die um Euch herum im Wasser verstreut sind.>\n\nIch glaube, ich bleibe hier noch ein wenig sitzen und komme zu Atem. Könntet Ihr aufs Meer schwimmen und sie herauslassen? Nehmt meine thermohydraulischen Flossen, damit könnt Ihr Euch schneller fortbewegen.\n\nLasst Sassy wissen, dass ich gleich losschwimme.", sourceObjective = "Rettet 6 überlebende Goblins.", completion = "Oh, dem Himmel sei Dank, dass Ihr überlebt habt, {name}! Ich war mir so sicher, dass Ihr ertrunken seid, nachdem ich Euch über Bord habe gehen sehen.\n\n\n\nSchaut nur, wie viele Leute Ihr gerettet habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[14475] = { id = 14475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandet!", description = "Seht Ihr ein Problem mit diesen Windreitern, {name}? Sie reiten nicht auf dem Wind! Jeder Flug, den ich aussende, wird von diesen Nachtelfenscharfschützen abgeschossen.\n\nScharfschützen aus Talrendis haben sich im südlichsten Turm vor den Bergen verschanzt. Ich hab einen dieser kleinen Goblinanfänger losgeschickt, damit er sich um den Turm kümmert, aber ich habe kein Wort von ihm gehört. Geht und findet Bombardierhauptmann Smooks und macht ihm gehörig Dampf!", sourceObjective = "Findet Bombardierhauptmann Smooks im südlichsten Nachtelfenturm bei der Talrendisspitze.", completion = "Endlich Verstärkung!", sourceObjectiveStatus = "unverified-source-field" }
quests[14476] = { id = 14476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verkabelt zum großen Knall", description = "Dieser Turm war nicht in der Reichweite der Kanonen, also dachte ich, wir lassen ihn auf die altmodische Art in die Luft fliegen - höchstpersönlich. Wir haben die Sprengsätze alle angebracht, aber die Wachen haben uns zurückgeschlagen, bevor wir die Zünder scharfmachen konnten.\n\n{name}! Geht dort hinauf und macht die drei Zünder scharf, die wir am Fuß des Turms platziert haben. Die Dinger sind per Kabel mit einem Satz Thermalbomben verbunden, die ich an der tragenden Wand angebracht habe... Das wird ein Spektakel!", sourceObjective = "Macht die drei Sprengladungen, die um den Fuß des südlichsten Turms an der Talrendisspitze angebracht sind, scharf.", progress = "Habt Ihr sie? Habt Ihr alle drei erwischt?", completion = "Klasse. Dann wollen wir diesen Bananenstand mal anzünden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14477] = { id = 14477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drückt auf den Knopf!", description = "Lass mich die Verbindungen überprüfen... alles klar. Bitte, Ihr habt die Ehre, {name}. Drückt drauf. Drückt auf den Knopf!\n\nDrückt auf den Knopf, {name}!\n\nNach dem Feuerwerk geht zu Kroum in Valormok und sagt ihm, dass der Himmel sauber ist.\n\nDrückt auf den Knopf!", sourceObjective = "Zündet die Sprengladungen!", progress = "Wie sieht's aus, {name}? Blauer Himmel?", completion = "Ja, lasst sie brennen! Lasst sie die Nacht erleuchten und ihr brennender Turm soll das Schlachtfeld unter uns erleuchten während wir Entsetzen über sie bringen.\n\nIch danke Euch, {name}. Bleibt in meiner Nähe: der Einmarsch steht kurz bevor...", sourceObjectiveStatus = "unverified-source-field" }
quests[14478] = { id = 14478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Ausnehmer", description = "Das Bilgewasserbataillon sucht derzeit nach neuen Rekruten für OPERATION AUSNEHMER.\n\nDer Sold besteht aus einer Goldmünze für alle unbescholtenen Soldaten am Ende der Operation. Im Falle des Ablebens erlischt jeglicher Anspruch auf eine Bezahlung. Für alle im Rahmen der Mission durchgeführten Wiederbelebungen wird eine Gebühr von 20 Silberstücken erhoben.\n\nAlle Rekruten sollen sich umgehend bei Kommandant Molotov unter der Hauptkanone melden.", sourceObjective = "Meldet Euch bei Kommandant Molotov unter der Hauptkanone im Bilgewasserhafen zum Dienst.", completion = "Willkommen zurück zum Dienst, Soldat. Schön, dass Ihr wieder da seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[14479] = { id = 14479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt viele andere", description = "Genug geredet. Schwingt die Beine und ab auf eine Rakete, Soldat!\n\nUnd vergesst nicht: Wenn Ihr tot seid, werdet Ihr nicht bezahlt!", sourceObjective = "Nehmt eine Rakete zum Strand der Trümmer und meldet Euch dann bei Leutnant Drex zum Dienst.", completion = "Holprige Reise gehabt?", sourceObjectiveStatus = "unverified-source-field" }
quests[14480] = { id = 14480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschung", description = "Wir schicken Euch dort hinein, um diese Nagaplage auszurotten. Der Gebrauch von Waffen wurde genehmigt.\n\nDer Goblintrupp unterstützt Euch bei dieser Mission, also sollte es ein Kinderspiel werden.", sourceObjective = "Tötet 30 Naga der Grollflossen in den Ruinen von Eldarath.", completion = "Euer Name spricht sich herum… Ihr seid fast schon so berüchtigt wie der Goblintrupp. Ihr seid ein ganz Harter.", sourceObjectiveStatus = "unverified-source-field" }
quests[14482] = { id = 14482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht ruft", description = "<Bürger/Bürgerin>!\n\nWie Ihr vielleicht gehört habt, greift uns die Horde vor der Küste an. Die Schlacht ist heftig und unerbittlich.\n\nWir brauchen jeden Tauglichen, um die Feinde zurückzuschlagen!\n\nMeldet Euch unverzüglich am nördlichsten Dock, um zur Schlacht transportiert zu werden.\n\nOh und unsere offiziellen Schlachtschiffe sind... nun ja, etwas später dran als geplant. Macht Euch aber keine Sorgen, wir haben Söldnerschiffe angeheuert, die in der Zwischenzeit reichen sollten.\n\nBeeilt Euch jetzt, {class}. Sturmwind braucht Euch!", sourceObjective = "Fahrt mit dem Söldnerboot zur Schlacht.", completion = "Ich wette, dass Ihr eine andere Art von Schlacht erwartet habt. Aber es ist dennoch eine Schlacht, Ihr werdet schon sehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[14483] = { id = 14483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", sourceObjective = "Bringt die vergilbte schöne Grußkarte zu Detektiv Snap Schnappbolz in Orgrimmar.", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr da?\n\nOh, hey, das ist was Großes. Was richtig Großes. Die ganzen verrückten Details auf einem Haufen. Danke - Ihr habt uns hier echt geholfen. Es war schön, mit Euch zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14484] = { id = 14484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf der Schlange", description = "Im Offizierslager hat man uns beigebracht, immer den Kopf der Schlange abzuschlagen. Angesichts der Tatsache, dass wir nie irgendwelche Schlangen gefunden haben, schien das ein ganz schön blöder Rat zu sein. Aber jetzt ergibt alles einen Sinn.\n\nBringt Eure Männer dorthin und tötet Lord Kassarus.", sourceObjective = "Tötet Lord Kassarus im Tempel von Zin-Malor.", completion = "Ich bin froh, dass Ihr auf unserer Seite kämpft, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[14485] = { id = 14485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen Ticker", description = "Unser bester Sprengstoffexperte Ticker ist zusammen mit dem Goblintrupp in einer Mission unterwegs. Er hat WEIT mehr als genug Sprengstoff für alle Runensteine in den Ruinen dabei.\n\nIhr müsst ihm nur Deckung geben. Den Rest erledigt er.", sourceObjective = "Bringt Ticker in die Ruinen und gebt ihm Deckung, während er Bomben an 3 der Runensteine der Grollflossen anbringt.", completion = "Wir hoffen, dass wir damit eine ihrer größten Magiequellen abschneiden können. Die Wahrheit ist, dass wir es nicht genau wissen. Aber wer kann schon einer Gelegenheit widerstehen, etwas in die Luft zu jagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14486] = { id = 14486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ware anfassen", description = "He da, Kumpel! Wollt Ihr schnell ein paar Münzen verdienen?\n\nBringt mir alle Tafeln der Hochgeborenen, die Ihr in den Ruinen finden könnt.", sourceObjective = "Sammelt 12 Tafeln der Hochgeborenen aus den Ruinen von Eldarath.", progress = "Die Blutelfen verschlingen diese Tafeln. Pures Geld!", completion = "Ausgezeichnet. Hier ist Eurer Anteil.\n\nSchön, mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14487] = { id = 14487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch schlagendes Herz", description = "Kommandant Molotov hat im Geheimlabor einen Käufer für das Artefakt gefunden, das Ihr für mich ausgespäht habt.\n\nZweifellos befindet es sich noch immer in der Mitte der Ruinen bei der Hohepriesterin, wo Ihr es gefunden habt. Bringt es unbeschadet her, <Soldat/Soldatin>!", sourceObjective = "Beschafft Euch das Herz von Arkkoroc aus der Mitte der Ruinen von Eldarath.", progress = "Ich liebe es, wenn die Leute unschätzbar wertvolle Artefakte einfach herumliegen lassen.", completion = "Haha! Es ist RIESIG!\n\nWir müssen es gleich zu Onkel Tollhaus bringen, sobald wir hier alles aufgeräumt haben und abmarschbereit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[14488] = { id = 14488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung", description = "Ihr habt es geschafft? Gut. Ich habe schon auf Hilfe gewartet. Jetzt ist die beste Zeit, zu handeln.\n\nNehmt dieses Paket und begebt Euch noch tiefer hinein, um Hummel, dem Leiter dieser dreckigen Chemiemanufaktur, ein paar Dokumente zuzustellen. Das Dokument ist hier drin, zusammen mit einer kleinen Hilfe, falls sie irgendwelche chemischen Überraschungen für Euch bereithalten. Verwendet einen der Neutralisatoren, wenn es soweit kommt, okay?", sourceObjective = "Stellt Apotheker Hummel auf Burg Schattenfang die Vorladung bei Gericht zu.", progress = "Ich kann mich nicht erinnern, einen Reinigungsdienst bestellt zu haben... aber ja, ich bin Apotheker Hummel.\n\n...Moment mal, was hat das alles zu bedeuten? Glaubt Ihr etwa, diese bedeutungslosen Papiere könnten mich aufhalten? Pah!", completion = "Was wir hier tun, hat Euch nicht zu interessieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[14491] = { id = 14491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhelose Erde", description = "Bis vor Kurzem schürfte eine Gruppe von Zwergen, die hier eingefallen war, rücksichtslos in unseren Ländern im Westen auf der Suche nach Schätzen. Als die Erde brach, stiegen die Erdgeister des missbrauchten Landes auf und übten Rache an den Zwergen.\n\nDie aufgebrachten Erdgeister suchen die alte Ausgrabungsstätte noch immer heim, {name}. Wir müssen sie beschwichtigen.\n\nNehmt diese Trommel mit Euch nach Westen und trommelt für die Geister. Der Rhythmus sollte ihre Wut und Verwirrung schlichten.", sourceObjective = "Benutzt die Trommel der besänftigten Erde, um 6 aufgebrachte Erdgeister zu beruhigen.", completion = "Das Land ist eindeutig noch immer in Aufruhr, wenn es so schwierig war, die Erdgeister zu beruhigen.\n\nEines sollte Euch in Erinnerung bleiben, {name}. Vergesst nie das Schicksal, das jene ereilt, die der Erdenmutter Schmerzen zufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[20438] = { id = 20438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Verkleidung", description = "Euch ins Innere von Sonnenhäschers Zuflucht zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock der Sonnenhäscher verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", sourceObjective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", progress = "Konnte Shandy Euch dabei helfen, an einen Wappenrock der Sonnenhäscher heranzukommen?", completion = "Ich wusste, dass Shandy für uns einen Weg finden würde, hindurchzukommen. Lasst mich ihn verzaubern, damit Ihr ihn verwenden könnt. Je eher Ihr den Wappenrock nicht mehr braucht, um so schneller können wir ihn Shandy zurückgeben und um so höher wird unsere Chance sein, dass sein Besitzer ihn niemals vermissen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[20439] = { id = 20439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit dem Magister", description = "Ich habe eine Verzauberung auf den Wappenrock gelegt, die es Euch erlauben sollte, einen kurzen Augenblick lang unentdeckt an den Verteidigungsvorkehrungen der Zuflucht der Sonnenhäscher vorbeizukommen. Das sollte Euch genug Zeit geben, das Rattenloch zu betreten und Euch dort mit unserem Kontakt bei den Sonnenhäschern, einem gewissen Magister Hathorel, zu treffen.\n\nBesorgt Euch die Kopie von \"Uralte drachengeschmiedete Klingen\", die seine Männer aus Wyrmruh entliehen haben, solange Eure Verkleidung anhält, und kehrt zu mir zurück.", sourceObjective = "Besorgt den Folianten \"Uralte drachengeschmiedete Klingen\" von Magister Hathorel.", progress = "Habt Ihr das Buch besorgt?", completion = "Ausgezeichnete Arbeit! Jetzt, wo es sich in unserem Besitz befindet, müssen wir es so schnell wie möglich zu Caladis Prunkspeer bringen. Wir dürfen nicht riskieren, dass das Buch wieder in die Hände der Sonnenhäscher gelangt.\n\nIch kümmere mich darum, dass Shandy Lackglanz seinen Wappenrock unbeschadet zurückbekommt und für seine Hilfe reichlich belohnt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[20440] = { id = 20440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergiftetes Wasser", description = "Unsere heiligen Brunnen wurden besudelt und ich werde Eure Hilfe brauchen, um das wieder in Ordnung zu bringen.\n\nUm alle Brunnen zu säubern, muss ich ein Läuterungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.\n\nZuerst werden wir ein Läuterungstotem für den Brunnen der Winterhufe herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und ausgewachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.\n\nKehrt mit den Tatzen und Krallen zu mir zurück, {name}.", sourceObjective = "Sammelt 6 Präriewolftatzen und 4 Ebenenschreiterkrallen.", progress = "Habt Ihr die Tatzen und die Krallen, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ich werde ihre Macht jetzt an ein Totem der Läuterung binden.", sourceObjectiveStatus = "unverified-source-field" }
quests[20441] = { id = 20441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Vision", description = "Stellt sicher, dass Ihr bereit seid, um das Dorf der Bluthufe zu verlassen, {name}. Der nächste Schritt Eurer Reise wird Euch an weit entfernte Orte führen.\n\nEuer Weg führt Euch über die Felder von Mulgore, und die Erdenmutter wird jederzeit über Euch wachen. Wenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, werden sich Eure Augen öffnen, und die Geister werden Euch begleiten.", sourceObjective = "Trinkt vor dem Stammesfeuer im Dorf der Bluthufe das Wasser der Vision.", completion = "Habt keine Angst, {name}. Ihr habt den Ritus der Vision erfolgreich bestanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[23733] = { id = 23733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Heute habt Ihr ein Ritual absolviert, das weitaus schwieriger war als wir es normalerweise von jungen Tauren erwarten. Seid stolz. Es ist nun an der Zeit, Eure Reise fortzusetzen.\n\nWestlich von hier, hinter der Begräbnisstätte, werdet Ihr einen Pfad finden, der zur Ebene führt. Folgt diesem Pfad und sprecht mit Dyami Windsegler.\n\nGeht mit der Erdenmutter. Ihr werdet hier immer willkommen sein.", sourceObjective = "Sprecht mit Dyami Windsegler oben auf der Horizontmesa.", completion = "Wenn Ihr bereit seid, Camp Narache hinter Euch zu lassen, so werde ich die Geister rufen, um Euch auf Eurem Weg zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24215] = { id = 24215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus des Winds", description = "Seht, {name}. Die Wogenden Ebenen Mulgores erstrecken sich vor Euch: unsere Heimat, die Wiege der Erdenmutter. Hier versorgt sie uns mit allem, was wir je brauchen, in einem friedlichen und grünen Land. Zum Schutz dieses Landes werdet Ihr kämpfen.\n\nEure Reise wird Euch weitab von den schützenden Armen der Heimat führen, zu den am weitesten entfernten und schrecklichsten Gegenden der Welt, und noch weiter.\n\nUnter uns könnt Ihr das Dorf der Bluthufe sehen. Hier beginnt der erste Schritt auf Eurem wahren Weg. Trinkt von dem Wasser der Vision und lasst die Geister Euch den Weg zeigen.", sourceObjective = "Trinkt das Wasser der Vision.\n\nBereitgestellter Gegenstand:", completion = "Willkommen im Dorf der Bluthufe. Ich bin froh, dass die Geister Euch einen sicheren Weg gezeigt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24216] = { id = 24216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24217] = { id = 24217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24218] = { id = 24218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Hervorragende Arbeit, {name}. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[24219] = { id = 24219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Hervorragende Arbeit, {name}. Die Sicherheit unserer Grenzen muss unter allen Umständen gewahrt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[24220] = { id = 24220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Das sind gute Neuigkeiten, {class}! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24221] = { id = 24221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24223] = { id = 24223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Arathibecken, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nKehrt erst mit der Nachricht Eures Sieges zu mir zurück, {name}. Wir dürfen es nicht zulassen, dass der Hordenabschaum Ressourcen beansprucht, die rechtmäßig uns gehören!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24224] = { id = 24224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen kämpfen in der Kriegshymnenschlucht, um ihren Wald zu beschützen. Wir unterstützen sie dabei, doch nicht weil wir Baumkuschler sind, sondern weil jede natürliche Barriere auch Schutz für das Gebiet der Allianz bedeutet.\n\nHeute brauchen sie uns mehr denn je. Wenn wir nicht wollen, dass der Feind das Eschental bis hin zum Brachland besetzt, müssen wir umgehend Verstärkungstruppen entsenden!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24225] = { id = 24225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Kriegshymnenschlucht", description = "Die Allianz ist ein heimtückischer Gegner, {name}. Sie rechtfertigt ihr aggressives Vorgehen gegen unsere Territorien im Brachland mit der Behauptung, lediglich das Eschental zu verteidigen.\n\nAm heutigen Tage haben wir die einmalige Chance, den Feind von unserem Land zu vertreiben. Begebt Euch in die Kriegshymnenschlucht und erobert zurück, was rechtmäßig unser ist!", sourceObjective = "Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24226] = { id = 24226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Arathibecken", description = "Wir stehen kurz davor, das Arathibecken an die Allianz zu verlieren. Wenn wir unsere Streitkräfte nicht umgehend verstärken, wird alles umsonst gewesen sein.\n\nZögert nicht zu lange, {class}! Begebt Euch ins Arathibecken und vernichtet den Feind. Sieg für die Horde!", sourceObjective = "Gewinnt eine Schlacht im Arathibecken und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24426] = { id = 24426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, {name}. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24427] = { id = 24427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[24428] = { id = 24428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höchst merkwürdiger Umstand", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und bringt ihn Zardeth der Schwarzen Klaue.", sourceObjective = "Bringt Onyxias Kopf zu Zardeth der Schwarzen Klaue im Keller des Geschlachteten Lamms.", progress = "Bei Nozdormus Zähnen!", completion = "Was? Wie seid Ihr an diesen Kopf gekommen? Ist sie nicht... Nein, die Details sind nicht wichtig vermute ich. Ihr werdet unzweifelhaft ein wenig von diesem Tand als Vergütung erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24429] = { id = 24429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höchst merkwürdiger Umstand", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und bringt ihn Neeru Feuerklinge.", sourceObjective = "Bringt Onyxias Kopf zu Neeru Feuerklinge in der Kluft der Schatten.", progress = "Was hat das zu bedeuten?!", completion = "Ihr habt mir das Haupt von jemandem gebracht, der... Nein, es wäre das Beste, nicht zu viel darüber nachzudenken. Ihr werdet unzweifelhaft eine Vergütung für Eure Heldentaten erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24430] = { id = 24430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Himmel schwärzen", description = "{name}! Helft uns hier mal, ja? Gorsch hier hat schlechte Erfahrungen mit dem 'Iss-soviel-du-kannst' Meeresfrüchteladen in der Stadt gemacht und jetzt fehlt uns ein Pilot.\n\nIch sollte diese Glevenschleudern der Elfen unbrauchbar machen, bevor sie unsere Lufteinheiten zu Konfetti verarbeiten. Setzt Euch auf diesen Windreiter und schwingt Euch in die Lüfte! Einer meiner Bombardierkumpels wird mit Euch kommen und die Ziele auf Euer Kommando bombardieren.\n\nUnd ach ja! Werft eine Bombe genau auf die Kommandozentrale der Nachtelfen - das große Gebäude im Süden neben der Brücke. Großartig!", sourceObjective = "Besteigt einen gestrandeten Windreiter und fliegt über die Talrendisspitze. Zerstört 6 Glevenschleudern der Talrendisspitze und bombardiert die Kommandozentrale.", progress = "Noch mehr Bomben. Noch mehr Bomben!", completion = "Oh ja! Ich liebe den Geruch von frischen Bombenkratern im Schmutz!\n\nMan munkelt im Lager, dass die Frontlinie der Elfen in Richtung Fluss zursammenbricht. Redet mit Chawg und findet heraus, ob Ihr irgendwie helfen könnt, die Sache zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24431] = { id = 24431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässtes Rezept", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...", sourceObjective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", progress = "\"Wein ist nur so fein, wie derjenige, der ihn trinkt\", sag ich immer.", completion = "Das ist ein ziemlicher Fund, {name}. Ich kann Euch nicht erlauben, das an irgendwen anderen zu verkaufen, also bin ich gewillt, Euch ein großzügiges Angebot zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24432] = { id = 24432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seetauglich", description = "Willkommen im Salzkutter, {class}.\n\nIch bin Erunak, der letzte überlebende Passagier dieses einst stolzen Schiffes.\n\nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga greifen unaufhörlich an.\n\nIhr seid an die Bedingungen hier unten nicht ausreichend angepasst, um von großem Nutzen zu sein, aber das kann ich ändern.\n\nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Eure Überlebenschancen deutlich erhöhen wird.", sourceObjective = "Erunak im Salzkutter möchte, dass Ihr ihm 3 Salzwasserseesterne und ein Tritonshorn vom Seefahrergrab bringt.", progress = "Schön zu sehen, dass Ihr noch am Leben seid, {race}.\n\nHabt Ihr die Dinge gefunden, die ich brauche?", completion = "Bitteschön, {class}. Damit solltet Ihr Euch im Meer fast mühelos bewegen können.\n\nDoch jetzt müssen wir uns an die Arbeit machen. Wir haben viel zu tun, aber nur wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24433] = { id = 24433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angst, der große Motivator", description = "Unsere Grunzer sind stark, aber sie zeigen keinerlei Initiative. Sie gehen an den Frontlinien in die direkte Konfrontation. Aber <ein unabhängiger/eine unabhängige:c> {class} wie Ihr - nun jemand wie Ihr könnte sich doch hinter die Linien schleichen und tief hinter den Schanzen der Feinde Chaos und Verwüstung anrichten.\n\nSchlagt eine Schneise der Verwüstung durch das Herz von Talrendis, {name}! Streckt unsere Feinde in dem Gebiet nieder, das sie als sicher erachten und hinterlasst Blut und Angst.", sourceObjective = "Kämpft Euch quer durch Talrendisspitze und tötet 12 Verteidiger der Talrendisspitze und 6 Schildwachen der Talrendisspitze.", completion = "Lok'tar ogar, {name}. Wenn sie die Leichen ihrer Kameraden entdecken, werden sie erkennen, dass man nirgendwo vor dem Zorn der Horde sicher ist und ihr Kampfeswille wird gebrochen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24434] = { id = 24434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen absetzen", description = "Spürt Ihr das leichte Beben der hiesigen Leylinien, {name}? Ich spüre hin und wieder ein Vibrieren, wie nach dem Zupfen einer Saite. Diese Art Resonanz erwarte ich nach einem weitreichenden Beschwörungszauber. Die Wissenshüter an der Talrendisspitze versuchen mit ihrer lächerlich primitiven Magie Verstärkung aus Darnassus herbeizurufen.\n\nDas können wir zu unserem Vorteil nutzen, {name}. Wenn Ihr ihren Beschwörungsstein beeinflusst, können wir ein Spitzenteam von Kommandosoldaten hinter die feindlichen Linien teleportieren.\n\nFindet den Beschwörungsstein der Talrendisspitze!", sourceObjective = "Tötet 5 Wissenshüter der Talrendisspitze und findet den Beschwörungsstein der Wissenshüter irgendwo in Talrendisspitze.", completion = "Bilder eines großen, weit entfernten Baums durchfluten Eure Gedanken. Euer Magen krampft sich zusammen während Ihr den Stein neu ausrichtet. Eure Gedanken füllen sich kurz mit Visionen eines feurigen Portals, eines hochaufragenden Bergs, einer kalten Einöde und einer furchtbaren Narbe, die sich über die Erde erstreckt.\n\nKurz darauf beruhigen sich die magischen Energien des Steins und Ihr fühlt Euch nur einen Schritt entfernt von Valormok. Andorels Einmarsch kann beginnen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24435] = { id = 24435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmal nass wischen", description = "Es gibt noch viel zu viele Naga an diesem Strand. Sieht aus, als hättet Ihr da ein wenig aufzuwischen, <Junge/Mädel>.", sourceObjective = "Tötet 12 Naga der Grollflossen am Strand der Trümmer.", completion = "Da habt Ihr aber schön aufgeräumt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24436] = { id = 24436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles Heil kommt von oben", description = "Am Strand liegen eine Menge \"Soldaten\", die versuchen, durch den Tod ihren Pflichten zu entfliehen. Findet diese Faulpelze und ruft mit der Leuchtpistole einen Priester herbei, der sich der Lage annimmt.\n\nUnsere Männer sollen ja nicht glauben, dass sie so leicht ausmustern können.", sourceObjective = "Ruft an den Leichen von 8 verwundeten Soldaten am Strand der Trümmer einen fliegenden Priester herbei.", completion = "Gute Arbeit, Junge. Wir kriegen diesen Strand im Handumdrehen wieder sauber.", sourceObjectiveStatus = "unverified-source-field" }
quests[24437] = { id = 24437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer zuerst kommt, mahlt zuerst", description = "Am Strand entlang gibt es einige wunderschöne Gebäude, die sich perfekt als Strandhäuschen eignen. Ich könnte sie für das Zehnfache der Reparaturkosten weiterverkaufen.\n\nDie besten Stücke sind die Nagapagode im Süden, der Turm direkt am Wasser und die Ruinen ganz am nördlichen Ende des Strands. Wenn Ihr sie für mich beansprucht, bevor die Kämpfe vorbei sind, werde ich Euch gut belohnen.", sourceObjective = "Stellt Ruckus' Gebietsanspruchsfahne neben den besten Strandgrundstücken am Strand der Trümmer auf.", completion = "Haha! Ausgezeichnet. Sehr gut gemacht, Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[24438] = { id = 24438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus", description = "Wir haben keine Wahl, {name}. Wir müssen weiter ins Landesinnere.\n\nEs gefällt mir zwar überhaupt nicht, aber hier sind wir verwundbar.\n\nKehrt zu den Ställen unterhalb des Anwesens zurück. Lasst uns alle Mann auf Karren verfrachten und ostwärts schicken. Ich hoffe nur, es ist noch nicht zu spät.", sourceObjective = "Geht an Bord eines Karrens unterhalb des Graumähnenanwesens.", completion = "Danke, dass Ihr angehalten habt, {name}. Unseren Karren hat es ziemlich übel erwischt.\n\nAber der vor uns ist noch schlimmer dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[24439] = { id = 24439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterwerfung Azsharas", description = "{name}! Habt Ihr den Windreiter gelenkt, der die Kommandozentrale bombardiert hat? Das war ein Volltreffer!\n\nMeine Späher berichten mir, dass Ihr Jarrodenus, den Flugmeister der Nachtelfen der Himmelsjäger und de facto Kommandanten der gegnerischen Truppen schwer verwundet habt.\n\nJetzt ist die Gelegenheit zuzuschlagen - ich habe nicht genug Zeit, um alle zum Angriff zusammenzurufen. Stürmt das Gebäude der Kommandozentrale und tötet Kommandant Jarrodenus bevor seine Verstärkung eintrifft. Bringt mir seinen Kopf - und Azshara gehört uns!", sourceObjective = "Besiegt Kommandant Jarrodenus an der Talrendisspitze und holt Euch seinen Kopf.", progress = "Brüllt Jarrodenus immer noch Befehle oder habt Ihr ihn von der Last seines Kopfes befreit?", completion = "...dann ist es vollbracht!\n\n<Chawg beobachtet das Schlachtfeld.>\n\nEs befinden sich immer noch vereinzelte Widerstandsnester um unser Lager herum, aber diese Rückzugsgefechte scheinen einen großangelegten Rückzug nach Eschental zu verschleiern. Azshara gehört uns!\n\nDer Kriegshäuptling wird von diesem Sieg und Eurem Anteil daran hören. Aber wir werden sicherlich die Hilfe eines {class} wie Euch anderswo benötigen. Vergesst nicht, mit Kroum hier im Lager zu sprechen, bevor Ihr aufbrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24440] = { id = 24440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhufsäuberung", description = "Ich habe das Totem angefertigt, um den Brunnen der Winterhufe zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet den Brunnen im Südosten, aber nehmt Euch in Acht. Wer auch immer für diese Schandtat verantwortlich war, wird dort eventuell auf der Lauer liegen.\n\nEs kann sein, dass diese Aufgabe sehr schwierig ist, {name}. Seid vorsichtig, und lasst diejenigen, die unseren Brunnen entweiht haben, nicht entkommen.", sourceObjective = "Benutzt das Läuterungstotem der Winterhufe beim Brunnen der Winterhufe.", completion = "Die Grimmtotem...\n\n<Mull verzieht das Gesicht.>\n\nIch hatte gehofft, dass meine Tage gezählt sein würden, bis {race} andere {race} grundlos in den Ländern von Mulgore angreifen. Ihr solltet stolz sein, {name} - Ihr habt unserem Land und unserem Volk einen guten Dienst geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24441] = { id = 24441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Donnerhörner", description = "Es gibt noch mehr zu tun. Wir müssen ein neues Totem erschaffen, um den Brunnen der Donnerhörner zu säubern.\n\nIhr müsst die Klauen der Raubtiere der Mulgoreebene besorgen. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.\n\nIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.", sourceObjective = "Sammelt 6 Pirscherklauen und 6 Pumaklauen.", progress = "{name}, habt Ihr die Klauen, die Ihr für mich besorgen solltet? Der Brunnen der Donnerhörner wird von Stunde zu Stunde verseuchter!", completion = "Vielen Dank, {name}. Die Reinheit, mit der diese Bestien jagen, ist für die Erstellung des Läuterungstotems äußerst wichtig.\n\nDer Brunnen der Donnerhörner ist ein Symbol meines Stamms und das Wissen, dass er von anderen {race} verunreinigt wurde, ruft die größte Wut hervor, die ich in Jahren verspürt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24442] = { id = 24442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtpläne der Kvaldir", description = "Ein Blick auf die erbeuteten Angriffspläne lässt eine Karte von den Östlichen Königreichen und Kalimdor erkennen, auf der die größten Siedlungen markiert sind. Beim Lesen der Befehle erfahrt Ihr, dass die Hauptleute der Kvaldir Pläne für eine Reihe von zerstörerischen Schlachtzügen ausgearbeitet haben.\n\nLaut diesen Befehlen sollen die Angriffe anfangen, nachdem Nebelrufer Yngvar \"das Herz der Nebel befragt hat\". Möglicherweise könnt Ihr die Angriffe ein wenig hinauszögern, indem Ihr das Omen aus der Höhle der Nebelrufer westlich von Hrothgars Landestelle erbeutet und Justiziarin Mariel Treuherz benachrichtigt.", sourceObjective = "Bergt das Herz der Nebel und bringt es zusammen mit den Angriffsplänen der Kvaldir zu Jusitziarin Mariel Treuherz auf dem Argentumturnierplatz.", progress = "Was habt Ihr da gefunden, {name}?", completion = "<Mariel nimmt die Befehle und den erbeuteten Seher-Kristall entgegen und begutachtet beides.>\n\nGute Arbeit, {name}, und gut mitgedacht. Ich bin mir zwar sicher, dass der Diebstahl dieses Schmuckstücks sie nicht lange aufhalten wird, aber ich glaube, dass Ihr uns Zeit verschafft habt, die Anführer der Horde und der Allianz vor den bevorstehenden Angriffen zu warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24443] = { id = 24443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Jägerin", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Honu Hirschjäger, eine junge Jägerlehrerin, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Honu!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Honu Hirschjäger gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24444] = { id = 24444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Schamanin", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Miira Donnerhuf, eine junge Schamanenlehrerin, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Miira!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Miira Donnerhuf gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24445] = { id = 24445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Druidin", description = "Die Verteidigung des Lagers fällt nun den Jüngsten unter uns zu, {name}, und viele unserer mutigsten Lehrlinge bekämpfen in genau diesem Augenblick die Stacheleber. Ich fürchte um ihre Sicherheit...\n\nBitte, sucht die junge Druidin Keshu Baumhuf östlich von hier, tief im Territorium der Stacheleber. Wenn Ihr sie und andere Lehrlinge lebendig vorfindet, können sie Euch vielleicht helfen.", sourceObjective = "Findet Keshu Baumhuf.", sourceObjectiveStatus = "unverified-source-field" }
quests[24446] = { id = 24446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Sonnenläufer", description = "Die Stacheleber haben nicht nur unsere Behausungen vernichtet, sondern auch einige Tauren gefangen genommen. Ich habe gesehen, wie sie Bowe Dämmerhorn, einen jungen Sonnenläufer, in einem ihrer garstigen Käfige weggebracht haben. Bitte, findet bei den Leichen der Stacheleber einen der Schlüssel für die Käfige und rettet Bowe!", sourceObjective = "Erhaltet einen primitiven Schlüssel von einem Stacheleber der Borstennacken und benutzt den Schlüssel, um den Stacheleberkäfig zu öffnen, in dem Bowe Dämmerhorn gefangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24448] = { id = 24448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beförderung", description = "Kommandant Molotov hat persönlich angeordnet, dass Ihr direkt an unseren Außenposten versetzt werdet. Wir bereiten uns darauf vor, Truppen in die Ruinen zu schicken, um den Naga Einhalt zu gebieten und das Artefakt zurückzuholen. Molotov möchte, dass Ihr eine dieser Truppen anführt.\n\nBegebt Euch in den Nordwesten des Strands und folgt dem Weg nach oben zu unserem Außenposten.", sourceObjective = "Meldet Euch bei Hauptmann Tork am Außenposten in den Ruinen von Eldarath.", completion = "{name}! Ihr habt es heil hierher geschafft, gut!\n\nWir haben viele Aufgaben in den Ruinen für Euch, aber wir stellen Euch unsere Besten zur Seite. Ihr arbeitet jetzt mit der ZOGGA-Truppe, die Zasterorientierte Organisation für gewinnbringende Goblin-Akquisen. Molotov ist davon überzeugt, dass Ihr es schafft. Mehr muss ich nicht wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24449] = { id = 24449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landgang", description = "Für den Augenblick stehen die Dinge gut hier. Es war mir eine Freude, mit Euch zusammenzuarbeiten, Soldat.\n\nWenn Ihr bereit seid, das Artefakt zurückzubringen, könnt Ihr einen Gyrokopter zurück zum Bilgewasserhafen nehmen und es Onkel Tollhaus persönlich geben.", sourceObjective = "Bringt das Herz von Arkkoroc zu Onkel Tollhaus im Bilgewasserhafen.", progress = "Ah, der Mann der Stunde!", completion = "Und Ihr habt das Artefakt dabei! Dann war die Mission wohl ein Erfolg. Die Zasterorientierte Organisation für gewinnbringende Goblin-Akquisen kann sich sehen lassen. Dieses Ding bringt sicher ordentlich Knete ein.\n\nUnd Ihr… Ich habe gehört, dass Ihr da unten beeindruckende Arbeit geleistet habt. Wahrscheinlich habt Ihr die Kosten ganz allein um 10% gesenkt. Genau das ist der clevere Geschäftssinn, den ich mir in meiner Armee wünsche!\n\nHier ist Euer versprochener Sold. Und ich habe noch etwas draufgelegt. Ich hoffe, es gefällt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24451] = { id = 24451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz mit dem Arkanisten", description = "Ich habe den Wappenrock mit einem Zauber belegt, sodass Ihr für kurze Zeit die Verteidigung der Silbernen Enklave umgehen könnt. Das dürfte Euch genügend Zeit verschaffen, um in die obere Ebene der Silbernen Enklave zu gelangen und jemanden vom Silberbund namens Arkanist Tybalin zu treffen.\n\nNutzt Eure Tarnung, um das Exemplar von \"Uralte drachengeschmiedete Klingen\", das seine Leute von Wyrmruh geliehen haben, zu beschaffen und zu mir zu bringen.", sourceObjective = "Holt den Folianten \"Uralte drachengeschmiedete Klingen\" bei Arkanist Tybalin.", progress = "Habt Ihr das Buch vom Wyrmruhtempel besorgt?", completion = "Ausgezeichnete Arbeit! Jetzt, wo es sich in unserem Besitz befindet, müssen wir es so schnell wie möglich zu Myralion Sonnenfeuer bringen. Wir dürfen nicht riskieren, dass das Buch wieder in die Hände des Silberbunds gelangt.\n\nIch kümmere mich darum, dass Shandy Lackglanz seinen Wappenrock unbeschadet zurückbekommt und für seine Hilfe entschädigt wird. Sobald sich das Buch in Myralions Händen befindet, stellt der Silberbund keine Bedrohung mehr dar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24452] = { id = 24452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Profit", description = "Die Dinge scheinen sich langsam etwas zu beruhigen. Gallywix blättert sicher weiter Bares hin, damit wir hier draußen bleiben, aber ich glaube, wir können noch ein bisschen mehr aus unserem Deal herausschlagen.\n\nNaga und Meerriesen sind sich normalerweise nicht grün, also müssen die Naga sie irgendwie kontrollieren. Nehmt diesen Tarnfeldgenerator, schleicht Euch in die Ruinen und lasst mich wissen, wenn Ihr etwas von Wert findet.", sourceObjective = "Schleicht Euch mit dem Tarnfeldgenerator in die Ruinen von Eldarath und findet das Herz von Arkkoroc.", progress = "Schon zurück?", completion = "Haha! Sehr gut. Damit bringe ich die Sache ins Rollen. Jetzt brauche ich nur noch einen Käufer und die Genehmigung von Onkel Tollhaus.\n\nHier ist der Lohn für Eure Arbeit. Tolle Leistung, Soldat!", sourceObjectiveStatus = "unverified-source-field" }
quests[24453] = { id = 24453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespräch unter Gefreiten", description = "Hört mal… ein letzter Gefallen, bevor Ihr Euch vom Acker macht.\n\nGefreiter Worcester ist immer noch an diesem Turm und \"rekrutiert\". Lasst ihn wissen, dass wir bereit sind, zusammenzupacken.\n\nEs war mir eine Ehre, mit Euch zu arbeiten, Rekrut.", sourceObjective = "Sprecht mit Gefreiter Worcester am Umschlagplatz der Raketenbahn von Orgrimmar.", completion = "Was?! Ich habe gar nichts von der Mission mitbekommen? Im Ernst?\n\nNa gut, na gut… Ihr überbringt ja nur die Nachricht. Vielen Dank, Kumpel. Vielleicht sehen wir uns ja mal wieder in der Stadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24454] = { id = 24454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Caladis Prunkspeer zurück", description = "Wir müssen dieses Buch umgehend zu Caladis Prunkspeer bringen. Würdet Ihr das tun? Ich kann mich auf niemand anderen verlassen, das Buch zu transportieren, und Ihr habt Euch geschickt darin erwiesen, die Sonnenhäscher auf Abstand zu halten.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Caladis und das Schwert werden auf Euch warten. Je eher wir die Klinge identifizieren, desto eher können wir Anspruch darauf erheben.", sourceObjective = "Bringt \"Uralte drachengeschmiedete Klingen\" zu Caladis Prunkspeer nach Quel'Delars Ruh.", progress = "Wir haben Eure Rückkehr erwartet. Was hat Euch zurückgehalten?", completion = "<Caladis nimmt das schwere Buch entgegen und fängt an es durchzublättern.>\n\nIch wusste, dass mir die Symbole auf der Klinge bekannt vorkamen. Die Waffe wurde ganz bestimmt von den Drachen geschmiedet und als Geschenk an eine der sterblichen Rassen übergeben. Aber welche Klinge soll das sein und wie kommt es, dass sie in Eiskrone ruht?", sourceObjectiveStatus = "unverified-source-field" }
quests[24455] = { id = 24455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Entsendung", description = "Ihr meldet Euch sofort zum Dienst. Hauptmann Desoto überwacht die Entsendung der Truppen an der Rampe der Raketenstartstation.\n\nMacht uns reich, Soldat! Weggetreten!", sourceObjective = "Meldet Euch bei Hauptmann Desoto im Bilgewasserhafen, um entsendet zu werden.", completion = "Schön Euch zu treffen, Soldat. Kommandant Molotov lobt Euch in höchsten Tönen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24456] = { id = 24456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerhornsäuberung", description = "Der Stamm der Grimmtotem glaubt, dass Kalimdor alleine den Tauren gehören sollte. Ihr Hass und Ärger füllen sie mit einem korrumpierendem Durst nach Macht. Magatha, ihre Anführerin, hat den Oberhäuptling Cairne Bluthuf selbst vergiftet, in einem Versuch, die Macht über Donnerfels zu erlangen. Sie wurde besiegt und die Grimmtotem ins Exil geschickt.\n\nJetzt scheinen sie Mulgore in die Verderbnis führen zu wollen, bevor sie diese Ländereien für immer verlassen müssen. Schnell, {name}, begebt Euch zum Brunnen der Donnerhörner nördlich von hier und führt das Ritual aus!", sourceObjective = "Benutzt das Läuterungstotem der Donnerhörner beim Brunnen der Donnerhörner.", completion = "Ihr habt sowohl mir als auch meinen Vorfahren heute einen großen Gefallen getan. Bitte, nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24457] = { id = 24457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritus der Vision", description = "Ich kann Euch gar nicht genug für die Säuberung des Brunnens unseres Stamms danken, {name}, und dafür, dass Ihr die wilden Grimmtotem bekämpft habt. Es gibt aber noch mehr zu tun; für Euch ist die Zeit gekommen, Eure Reise außerhalb vom Dorf der Bluthufe fortzusetzen.\n\nSucht Zarlman Zwillingsmond bei den Feuern im Norden des Dorfes aus. Sprecht mit ihm, um mehr von dem nächsten Ritual zu erfahren, das auf Euch zukommt.", sourceObjective = "Sprecht mit Zarlman Zwillingsmond im Dorf der Bluthufe.", completion = "Ich habe bereits mit Eurem Besuch gerechnet, {class}. Ich weiß immer, wer versuchen möchte, die Riten der Erdenmutter zu bestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24458] = { id = 24458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod am Nachmittag", description = "{name}, ich habe die gereinigte Probe Azsharit, die Ihr aus dem Labor gerettet habt, waffenfähig gemacht. Wenn meine Berechnungen richtig sind, wird es mit genug Kraft detonieren, um eine Stadt dem Erdboden gleichzumachen.\n\nWenn ich mich irre, könnten wir den Planeten in zwei Hälften reißen.\n\nDie einzige Möglichkeit, das herauszufinden, ist ein Probelauf! Bringt den Azsharitkern zu der Riesenkanone in Bilgewasser und meldet Euch bei Bleenik Zischlunte. Mein Mietpilot Friz Bodendreh hier kann Euch hinbringen.\n\nIch komme nach ... mit Sicherheitsabstand.", sourceObjective = "Liefert den scharfgemachten Azsharitkern bei Bleenik Zischlunte im Bilgewasserhafen ab. Sprecht mit Friz Bodendreh für einen Freiflug.", progress = "Was habt Ihr denn da - hat Wurfhammer Euch geschickt?", completion = "Oh! Das ist er. Der große Knall.\n\n<Zischlunte ruft seine Arbeiter herbei.>\n\nJungs, es ist soweit!", sourceObjectiveStatus = "unverified-source-field" }
quests[24459] = { id = 24459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morin Wolkenpirscher", description = "Ihr habt vielleicht schon einmal etwas von der Venture Company gehört. Sie sind ein \"Kartell\" der Goblins - das ist so etwas ähnliches wie ein Stamm.\n\nObwohl sich eines dieser Kartelle der Horde angeschlossen hat, ist die Venture Company eigentlich nur der Gier gegenüber loyal. Die gierigen Goblins und ihre Arbeiter haben schon lange versucht, die Rohstoffe und Ressourcen Mulgores auszubeuten - bisher mit wenig Erfolg.\n\nEiner unserer Kundschafter, Morin Wolkenpirscher, hat sich aufgemacht, um die Überreste einer der Karawanen der Goblins zu untersuchen. Wenn Ihr ihm helfen möchtet, müsst Ihr nur der Straße folgen, die aus dem Dorf und nach Osten führt.", sourceObjective = "Findet Morin Wolkenpirscher im östlichen Teil des Dorfs der Bluthufe.", completion = "Schön, Euch zu treffen. Wenn Ahmo Euch die Einzelheiten zu dieser Art Goblin schon verraten hat, können wir gleich mit der Arbeit anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24460] = { id = 24460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außer Betrieb", description = "Heda {class}, Ich will, das Ihr den Kataklysmus löst. Jagt ein paar Zombies.", sourceObjective = "Pauls Testquestgeber möchte, dass Ihr Zombies tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24461] = { id = 24461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert neu schmieden", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", sourceObjective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und schmiedet damit Quel'Delar neu.", progress = "Konntet Ihr Quel'Delar wiederherstellen?", completion = "Ihr habt die Klinge Quel'Delars wiederhergestellt, obwohl Blutkönigin Lana'thel verkündet hat, es würde nicht gelingen. Zwar muss die Klinge noch getempert werden, doch Lana'thel und ihr Meister werden uns nicht daran hindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[24463] = { id = 24463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Eschental vordringen", description = "Obwohl der Abschaum aus Darnassus sich aus Azshara zurückgezogen hat, bekomme ich immer noch widersprüchliche Meldungen von meinen Reitern, die in Eschental im Westen stationiert sind. Es ist möglich, dass die Nachtelfen einen Angriff auf unser Gebiet im Brachland durchführen.\n\n{class}, Ihr müsst über die Grenze schleichen und mit einem meiner Späher sprechen. Sucht nach Kulg Blutspritzer direkt hinter der Brücke am südwestlichen Rand der Talrendisspitze. Findet heraus, was in jenen Wäldern vor sich geht!", sourceObjective = "Sprecht mit Kulg Blutspritzer im Eschental.", completion = "Ihr sagt, dass die Talrendisspitze gefallen ist? Das sind gute Nachrichten!\n\nDas erklärt auch den Exodus von Elfen, den ich auf dieser Straße gesehen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24467] = { id = 24467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergang ins Schwarze", description = "Jetzt können wir diesen Wahnsinn beenden! Wir müssen den schwarzen Drachenschwarm vollkommen von Azshara fernhalten, bevor sie ihrem Meister irgendeine Nachricht überbringen können.\n\nIch weiß immer noch nicht, welches Ass sie für unsere Entführung im Ärmel haben, deshalb möchte ich Euch ein letztes Mal um etwas bitten: Geht zum Säbelrücken und tötet ihre Anführer, Zwielichtfürstin Katrana und Malicion.\n\nWenn es eng wird, komme ich und helfe. Ich möchte nur nicht riskieren, in die Falle zu gehen, die sie Azuregos gestellt haben.", sourceObjective = "Tötet Zwielichtfürstin Katrana und Malicion am Säbelrücken.", completion = "Ihr versetzt mich in Erstaunen, sterbliches Wesen. Nur selten trifft man jemanden, der so entschlossen und erfinderisch ist.\n\nAzuregos und ich werden Azshara wahrscheinlich für eine Weile verlassen und untertauchen. Ich hoffe allerdings, dass wir uns eines Tages wiedersehen. Vielleicht bereiten wir ja Todesschwinge selbst ein Ende.\n\nLebt wohl, {name}. Passt auf Euch auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[24468] = { id = 24468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrandet im Moor", description = "Die Oger haben zwei unserer Postkutschen erwischt: diese hier und eine, die nicht weit von hier im Norden ins Moor gestürzt ist.\n\nGeht dorthin und rettet die Überlebenden, während wir uns überlegen, wie wir mit diesen Ogern fertig werden.", sourceObjective = "Rettet 5 Unfallüberlebende aus dem Hagelwaldmoor.", completion = "Ihr habt es wieder geschafft, {name}. Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[24469] = { id = 24469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stellung halten!", description = "Hey, Ihr da! Ihr seid doch <ein kräftig aussehender/eine kräftig aussehende:c> {class}. Würdet Ihr uns helfen?\n\nEs scheint, als ob das heutige Erdbeben eine Gruppe dieser barbarischen Troggs aufgerüttelt hat und die sind über irgendetwas ziemlich erbost. Meine Leute tun, was sie können, um sie fernzuhalten, aber wir könnten Hilfe gebrauchen.\n\nTragt Euren Teil dazu bei - geht Richtung Süden und helft meinen Gebirgsjägern aus der Klemme. Wir müssen die Stellung halten!", sourceObjective = "Tötet 6 Eindringlinge der Felsenkiefertroggs.", completion = "Beeindruckende Arbeit, mein Junge. Von jetzt an können wir die Stellung wieder alleine halten.\n\nHier, nehmt das für Eure Bemühungen. Es könnte sich als nützlich erweisen, zumal ich Euch um etwas noch Wichtigeres bitten muss...", sourceObjectiveStatus = "unverified-source-field" }
quests[24470] = { id = 24470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut sie!", description = "Also gut, hört zu. Ich weiß ein oder zwei Dinge über Troggs, und eins davon ist, dass die größten und stärksten Troggs den meisten Respekt genießen. Diese Rohlinge ziehen Stärke allem anderen vor.\n\nSeht Ihr diese großen, starken Troggs hinter ihren Frontlinien? Sie sind das, was einem Anführer am nächsten kommt. Geht und erledigt ein paar von denen, damit sie wissen, was es heißt, sich mit den Töchtern und Söhnen von Eisenschmiede anzulegen!", sourceObjective = "Tötet 3 Stümper der Felsenkiefertroggs.", completion = "Hmm... Sie machen uns dafür verantwortlich, ihre Höhle zerstört zu haben, sagt Ihr? Das waren nicht wir, das war dieses schreckliche Erdbeben heute früh. Sind die so beschränkt, dass sie nicht sehen, dass unser Lager auch beinah zerstört wurde?\n\nIch kann allerdings keinem Trogg vorwerfen, dass er für seine Heimat kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[24471] = { id = 24471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Verwundeten", description = "Hört zu, {name}! Ich brauche nicht wie Joren Eure Klinge, aber ich benötige jemanden mit einer ruhigen Hand und etwas Mut.\n\nUnsere Gebirgsjäger sind ausgebildet, um das Dorf vor einem Wolfsangriff zu schützen... nicht vor einer ausgewachsenen Trogginvasion! Viele unserer Besten liegen verletzt und erschöpft darnieder, und ich brauche Eure Hilfe, um sie zu versorgen.\n\nHier, nehmt mein Erste-Hilfe-Set und helft so vielen, wie Ihr könnt.", sourceObjective = "Verwendet Stens Erste-Hilfe-Set, um 4 verwundeten Gebirgsjägern der Eisklamm zu helfen.", completion = "Viele von jenen, die Ihr gerettet habt, sind schon ins Lager zurückgekehrt. Ihre Wunden scheinen gut versorgt! Ihr könntet eine Zukunft im Bereich der Ersten Hilfe haben, wenn Euch dergleichen zusagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24472] = { id = 24472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorstellen ist angebracht", description = "Die Verlassenen sind uns dicht auf den Fersen und nun versuchen auch diese Oger, uns in die Zange zu nehmen, {name}.\n\nSie sind Diener des Ettins Koroth, dem bösartigsten und zerstörerischsten Wesen in ganz Gilneas.\n\nWenn wir Koroth dazu bringen könnten, die Vorhut der Verlassenen anzugreifen, können wir uns vielleicht sicher zurückziehen und etwas Zeit gewinnen.\n\nAber das gelingt uns nur, wenn wir Koroth wütend machen. Seine Diener zu töten reicht nicht. Wir müssen uns seinen wertvollsten Besitz schnappen, sein Banner aus Tigerfell.", sourceObjective = "Tötet 4 Ogerdiener und besorgt Euch Koroths Banner in Koroths Bau.", progress = "Wie ist es gelaufen, {name}?", completion = "Ihr habt den Ettin wirklich sehr wütend gemacht, {name}. Ich habe ihn selbst gehört.\n\nHoffen wir, dass es funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[24473] = { id = 24473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambossar abriegeln", description = "Wir wissen Eure Hilfe hier draußen zu schätzen, doch es gibt einen Ort, an dem Ihr noch mehr gebraucht werdet.\n\nDank der Angriffe durch die Troggs - ganz zu schweigen von dem starken Erdbeben, das wir gerade erlebt haben - müssen wir alle Zivilisten in Ambossar im Nordwesten abriegeln.\n\nGeht und sprecht mit meiner Frau Jona in Ambossar. Ich bin sicher, sie kann <einen kräftigen Kerl/ein kräftiges Mädel> wie Euch gut brauchen.", sourceObjective = "Sprecht mit Jona Eisenquell in Ambossar.", completion = "Hmpf... und was wollt IHR nun wieder? Seht Ihr nicht, dass ich beschäftigt bin!? Geht jemand anders auf die Nerven, ich hab' keine Zeit.\n\nMoment, was sagt Ihr da? Joren hat Euch geschickt, um zu helfen? Warum habt Ihr das nicht gleich gesagt!", sourceObjectiveStatus = "unverified-source-field" }
quests[24474] = { id = 24474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wichtigste zuerst: Wir brauchen Bier", description = "Ich kann mir nicht vorstellen, wie wir hier IRGENDWAS auf die Beine stellen wollen, solange wir kein Bier haben! Unser Biervorrat hier in Ambossar ist bedenklich niedrig.\n\nZum Glück haben wir für solche Fälle ein paar Notfallfässer aufbewahrt. Westlich von Ambossar, entlang der nördlichen Grenze des Tals, werdet Ihr Fässer mit Sturmhammer-Starkbier und Theramore Hell finden. Gleich östlich von hier findet Ihr einen Vorrat mit Gnomenbräu. Das ist mein Lieblingsbier!", sourceObjective = "Bringt je ein Fässchen Sturmhammer-Starkbier, Theramore Hell und Gnomenbräu an Euch.", progress = "Das Bier, Kumpel, das Bier!", completion = "<Jona nimmt einen tiefen Zug von dem Gnomenbräu.>\n\nAhh... Das hat gut getan. Jetzt können wir hier endlich ordentlich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24475] = { id = 24475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ganze andere Zeug", description = "Wenn wir hier eine ganze Weile die Schotten dichtmachen, werden wir etwas zu futtern brauchen und Decken, um die Kleinen warmzuhalten. Würde es Euch etwas ausmachen, hinauszugehen und ein paar Vorräte zu besorgen?\n\nIhr werdet feststellen, dass einige der kleinen Eber ein paar Keulen von stattlicher Größe haben... perfekt zum Essen. Dann brauchen wir noch Felle von jungen Wölfen.\n\nIhr findet fast überall in Eisklamm solches Wild.", sourceObjective = "Erlangt 3 Wildschweinschenkel und 4 struppige Wolfsbälge.", progress = "Die Leute werden schon unruhig. Habt Ihr die Vorräte schon?", completion = "Das muss fürs Erste reichen. Wir haben eine Menge Mäuler zu stopfen, aber wir müssen mit dem hinkommen, was wir haben. Mit ein bisschen Glück schickt uns König Bronzebart in Eisenschmiede ja bald Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24476] = { id = 24476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge tempern", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die Gefrorenen Hallen.", sourceObjective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", progress = "Solange das Schwert nicht getempert wurde, ist es nutzlos.", completion = "Ich... ich verstehe nicht. Das Schwert zu tempern hätte die Klinge wieder in ihren ursprünglichen Zustand bringen sollen. Was ist hier geschehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24477] = { id = 24477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakte der Zwerge", description = "{name}, <mein Junge/meine hübsche Blume>! Interessiert Ihr Euch für Archäologie?\n\nWir haben hier genau vor unserer Nase eine aufregende Gelegenheit. Das Beben des heutigen seismischen Ereignisses hat einige Artefakte aus der Erde unter unserem Lager herausgeschüttelt. Wenn Ihr den nördlichen Rand des Tals inspiziert, solltet Ihr alle möglichen Schätze finden. Bringt einige zurück zu mir und vielleicht können wir sie zusammen untersuchen.\n\nAlles klar! Ab mit Euch!", sourceObjective = "Beschafft 5 vergessene Zwergenartefakte.", progress = "Ja?", completion = "Wunderbar! Schaut Euch dieses hier an... Das muss mehr als 200 Jahre alt sein!\n\nJetzt aber zu anderen Dingen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24478] = { id = 24478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Frosts", description = "Wisst Ihr, einige meiner Lehrlinge haben mich als kaltherzig bezeichnet. Ich sage allerdings immer, lasst die Temperatur meines Körpers Euch nicht daran hindern, zu lernen.\n\nWenn Ihr Euch zur Prüfung des Frosts begeben möchtet, berührt den Frostkristall, um ein Portal zu öffnen. Wenn Ihr dort seid, ist das Ziel ganz einfach: Sammelt die kleinen schwebenden Eiskügelchen ein.\n\nDamit es nicht zu einfach wird, könnte der Gefrierbrand Euren Fortschritt hemmen. Wenn Ihr besonders raffiniert sein wollt, könnt Ihr die Runenfallen benutzen, um über sie hinwegzuspringen, wenn sie vorbeidriften. Klasse, nicht wahr?", sourceObjective = "Schließt die Prüfung des Frosts ab, indem Ihr 20 Essenzen des Eises einsammelt, ohne von Gefrierbrand getroffen zu werden.", progress = "Nein. Einfach nein. Macht es diesmal richtig.", completion = "Großartig. Ihr lasst Euch ganz bestimmt nicht von kalten Füßen aufhalten. Oder sonstigen kalten Körperteilen!\n\nNein? ...noch zu früh?", sourceObjectiveStatus = "unverified-source-field" }
quests[24479] = { id = 24479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Schattens", description = "Lassen wir uns nicht von den Grenzen des Magierepertoires der Magier einschränken. Ich jedenfalls will keiner Klasse angehören. Nekromantie kann so viel Spaß machen!\n\nBerührt den Schattenkristall, um ein Portal zu meiner Prüfung des Schattens zu öffnen. Sobald Ihr dort eintrefft, begebt Euch zu dem Altar, wenn Ihr bereit seid.\n\nKlagende Seelen werden Euch verfolgen...Euer Ziel ist es, sie in die Fallen zu locken. Achtet darauf, dass sie Euch nicht berühren.", sourceObjective = "Schließt die Prüfung des Schattens ab, indem Ihr 20 Klagende Seelen zu den Schattenrunen lockt, ohne von ihnen berührt zu werden.", progress = "Ihr seid nicht besonders gut darin. Ihr sollt die Prüfung beenden, BEVOR Ihr zu mir zurückkommt und mit mir sprecht. Nachvollziehbar?", completion = "Es gefällt mir, wie Ihr Euch bewegt, Lehrling.\n\nMacht Euch keine Sorgen darüber, wo ich all die Seelen herhabe. Sie wurden auf absolut humane Art und Weise besorgt, das versichere ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24480] = { id = 24480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Reflexion", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den Gefrorenen Hallen auf Euch.", sourceObjective = "Bringt Quel'Delar nach Schwertruh ins Innere der Hallen der Reflexion.", progress = "Was ist im Inneren der Hallen der Reflexion geschehen?", completion = "Ich hätte es nicht für möglich gehalten, dass das Böse von solch einem Schwert Besitz ergreifen kann, doch ich nehme an, dass das naiv von mir war. Wenn die größte Schöpfung der Drachen verdorben und gegen sie gerichtet werden kann, weshalb sollte da ein Schwert die Ausnahme bilden?\n\nUthers Rat ist weise, {name}, und ich würde Euch nahelegen, ihn schleunigst zu befolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24483] = { id = 24483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmsiel", description = "Unsere Kutschenfahrer wurden angewiesen, sich im Fischerdorf Sturmsiel zu sammeln. Die Späher berichten, dass wir dort Schutz und Vorräte finden können.\n\nTrefft Euch dort mit Gwen Armstead. Sie ist für die Leute verantwortlich.", sourceObjective = "Sprecht mit Gwen Armstead in Sturmsiel.", completion = "Ihr habt es also geschafft, {name}. Anscheinend haben es fast alle geschafft.\n\nFür eine Ausnahmesituation schlagen wir uns nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24484] = { id = 24484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfung", description = "Was sagt Ihr dazu, {name}? Die ganze Zeit über war Sturmsiel halbwegs intakt.\n\nSchade, dass die Verlassenen noch immer unterwegs ins Landesinnere sind, aber immerhin ist es ein guter Platz, um für ein oder zwei Nächte die Füße hochzulegen.\n\nDie andere Hälfte der Stadt ist voll von Spinnen, deswegen habe ich den Leuten gesagt, sie sollen sich von dort fernhalten.\n\nVielleicht könntet Ihr ja helfen, die Spinnen zu beseitigen? Unsere Verwundeten können bestimmt besser schlafen, wenn sie wissen, dass jemand diese achtbeinigen Ungeheuer in Schach hält.", sourceObjective = "Tötet 6 Giftbruthuscher.", completion = "Das habt Ihr gut gemacht, {name}. Aber diese Spinnen sind überall und ich fürchte, ihre Zahl hat kaum abgenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24486] = { id = 24486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedet das Eisen, solange es noch heiß ist", description = "Das Dorf der Troggs im Südwesten wurde fast ebenso sehr beschädigt, wie unseres. Nun sollte man logischerweise annehmen, dass da auch einige Troggartefakte aus dem Boden ragen!\n\nLeider scheinen Troggplünderer die meisten Artefakte bereits aufgesammelt zu haben. Bitte schaut, ob Ihr eine Möglichkeit findet, sie zurückzuholen. Ob Ihr es glaubt oder nicht, aber Wissen über die Troggs könnte schließlich dazu führen, dass man noch mehr Wissen über die mächtigen Zwerge erlangt!", sourceObjective = "Besorgt 5 unbezahlbare Felsenkieferartefakte von den Strauchdieben der Felsenkiefertroggs.", progress = "Habt Ihr den Troggs einige Artefakte entreißen können?", completion = "Oh, nun schaut Euch das an! Eine Axtklinge, einige Pfeilspitzen und eine Art einfacher Löffel. Das ist in der Tat faszinierend.\n\nNoch einmal vielen Dank für Eure Hilfe, {name}. Ich werde viel mit meinen Studien zu tun haben, wenn Joren uns hier abriegelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24487] = { id = 24487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weißbart braucht Euch", description = "Ihr habt uns hier einen großen Dienst erwiesen, doch befürchte ich, dass wir Euch weiterschicken müssen.\n\nEin guter Freund von mir, Grelin Weißbart, hat mich wissen lassen, dass er ein wenig Verstärkung gebrauchen könnte. Ihr findet ihn in der Nähe der Trolllager in Richtung Südwesten. Folgt der Straße Richtung Westen, dann solltet Ihr ihm früher oder später begegnen.\n\nAlles Gute, {name}. Troggs mögen vielleicht eine Plage sein, aber Trolle sind nicht zu unterschätzen.", sourceObjective = "Meldet Euch bei Grelin Weißbart im Eisklammtal.", completion = "Seid gegrüßt, {class}. Bereit, Euch an die Arbeit zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24488] = { id = 24488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ersatz", description = "Meine Jungs sitzen alle verletzt auf der Bank! Unsere Schredder sind nur noch Schrott! Der Schiri pfeift das Spiel gleich ab!\n\nDie letzte Minute läuft und ich brauche Euch, {name}!!!\n\nWir müssen einen dieser Schredder auf Vordermann bringen. Im Bilgepier liegen genügend Ersatzteile herum. Jeder grünblütige Kezanier überlässt sie Euch sicher gerne, wenn die Bukaniere dann eine Chance auf den Sieg haben.\n\nWir werden diesen nichtsnutzigen Dampfdruckhaien schon zeigen, wie man Fußbombe spielt.", sourceObjective = "Sammelt 6 Ersatzteile.", progress = "Wir verlassen uns auf Euch, {name}!", completion = "Das ist mein Junge! Jetzt muss ich diesen wertlosen Metallschrott nur noch in einen funktionierenden Zustand bringen und Euch raus aufs Spielfeld schicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[24489] = { id = 24489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollt Euch und lauscht", description = "Ich bin unglaublich schlecht darin, den Gesichtsausdruck von Trollen zu deuten. Daher kommen diese Trolle mir gar nicht wütend vor. Sie scheinen verwirrt... vielleicht ein wenig verängstigt.\n\nHier ist etwas passiert, was wir übersehen, {name}. Wir sollten der Sache ein wenig auf den Grund gehen, bevor wir einfach alle Trolle umbringen.\n\nHier in der Gegend gibt es drei Trolllager: eins im Südosten, eins im Südwesten und eins ganz im Westen. In jedem Lager gibt es eine Sterndeuterin... Schaut, ob ihr nahe genug an sie herankommt, dass Ihr belauschen könnt, was sie sagen.", sourceObjective = "Stellt Euch in jedem der Frostmähnenlager in die Nähe einer Sterndeuterin der Frostmähnen und lauscht dem, was sie zu sagen hat.", completion = "Hmm... interessant. Nach dem, was Ihr berichtet, scheint ein Feuerelementar sich aus der Sengenden Schlucht eingeschlichen zu haben. Oder das Erdbeben hat einen Riss in der Elementarebene geöffnet...\n\n<Soren lacht gequält.>\n\nSo oder so, das sind schlechte Neuigkeiten. Ihr solltet das lieber Grelin berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24490] = { id = 24490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Trip nach Eisenschmiede", description = "Die Präsenz eines Feuerelementars hier im Eisklammtal ist keine Kleinigkeit. Dieses Erdbeben hat doch mehr angerichtet, als nur ein paar Troggs zu verärgern... Es hat die Welt genug verändert, um einen Riss in der Elementarebene zu verursachen. Wir sollten einen Bericht nach Eisenschmiede schicken.\n\nIhr wärt nicht eventuell bereit, eine kleine Reise zu unternehmen, oder? Keine Sorge, Ihr seid genau <der Richtige/die Richtige>. Redet mit Hands Federspross beim Tunnel am östlichen Ende des Tals. Er weist Euch den richtigen Weg.", sourceObjective = "Sprecht mit Hands Federspross im Eisklammtal.", completion = "Nach Eisenschmiede? Nun, zuerst müsst Ihr durch Kharanos, aber davor müsst Ihr noch durch diesen Tunnel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24491] = { id = 24491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt diesem Gyrokopter", description = "H-h-habt Ihr das gesehen? Wie die ganze Höhle einfach so zusammengestürzt ist? Ich glaube, Ihr seid genau rechtzeitig gekommen, keine Minute zu früh.\n\nObwohl diese Entwicklung meinen Job, die Höhle zu untersuchen, entschieden vereinfacht, wird es für Euch nun schwerer, nach Kharanos zu gelangen.\n\nHe, wartet, ich habe eine Idee! Die Luftfahrer aus Gnomeregan haben einen Flugpunkt nicht weit von hier. Ich werde ein Signal absetzen und sie sollten Hilfe schicken. Ich vermute, dass sie drüben in Ambossar landen werden.", sourceObjective = "Meldet Euch bei Milo Zwickrädchen nahe Ambossar.", completion = "Milo Zwickrädchen meldet sich zum Dienst. Ihr habt ein Notsignal abgesetzt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24492] = { id = 24492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Packt Eure Taschen", description = "Das Maximalgewicht meines Gyros ist dergestalt, dass ich nur <einen/eine:r> {race} mitnehmen kann. Sieht aus, als hättet Ihr Glück, {name}!\n\nDie Zwergin Jona hat mir erzählt, dass all Eure Sachen nach Ambossar gebracht wurden. Sammelt zusammen, was Ihr braucht, beendet Eure Angelegenheiten und kommt zu mir zurück, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Erlangt einen Bierkrug der Eisklamm, einen struppigen Wolfsbalgumhang und ein paar Eberfleischreste.", progress = "Seid Ihr absolut sicher, dass Ihr Euch um alles gekümmert habt? Ihr werdet keine Zeit haben, nochmal herzukommen.", completion = "Hat ja auch lang genug gedauert. Haltet Euch gut fest und schaut Euch nochmal gut um! Höchstwahrscheinlich werdet Ihr eine ganze Weile nicht mehr herkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24493] = { id = 24493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst uns nicht", description = "Ihr verlasst uns? Denkt daran, Eure Vorräte aufzufüllen, bevor Ihr aufbrecht.\n\nWichtiger noch, sprecht mit Tharek Schwarzstein sobald Ihr in Kharanos eintrefft. Sagt ihm, was hier im Eisklammtal geschehen ist und dass wir ein wenig Hilfe gebrauchen könnten. Er wird hoffentlich etwas für uns organisieren können.", sourceObjective = "Meldet Euch bei Tharek Schwarzstein in Kharanos.", completion = "Das Eisklammtal? Ich habe hier meine eigenen Probleme. Was, die werden nicht mit ein paar Troggs fertig? Und Trollen? Und Übergriffen aus den Elementarebenen?\n\nAllerdings, wenn ich so darüber nachdenke... Das ist eine Menge. Ich bin überrascht, wie gut sie sich unter den Umständen halten. Ich werde sehen, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24494] = { id = 24494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machterfüllte Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weiterreiche. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaub', sie stammt vom Schamanenlehrer Teo. Werft einen Blick auf die Rune und sucht ihn dann in Ambossar auf.", sourceObjective = "Lest die machterfüllte Rune und sprecht mit Teo Hammersturm in Ambossar.", progress = "Die Geister haben mir Eure Ankunft angekündigt, {name}. Habt Ihr sie ebenfalls gehört?", completion = "Wir leben in dunklen Zeiten, mein Freund. Seht Euch um... selbst hier im entlegenen Eisklammtal sind die Geister rebellisch. Das Land ruft um Hilfe. Dennoch, sogar in Zeiten wie diesen, werden die Geister immer ein offenes Ohr für diejenigen haben, die ihre Hilfe erbitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24495] = { id = 24495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetzen der Vergangenheit", description = "Ich habe das Tagebuch eines Mannes namens Bradshaw gefunden. Leider fehlen viele Seiten, besonders gegen Ende.\n\nWenn Ihr genügend Seiten zusammentragt, kann ich vielleicht herausfinden, was nach dem Ausbruch des Fluchs hier geschehen ist.\n\nWer weiß… Vielleicht haben die Leute in diesem Dorf einen Fluchtweg gefunden. Vielleicht gibt es da draußen noch Überlebende.\n\nVielleicht ist mein Vater noch am Leben.", sourceObjective = "Sammelt 6 alte Tagebuchseiten.", progress = "Hattet Ihr schon Erfolg bei der Suche nach diesen Seiten?", completion = "Danke, {name}. Es wird ein wenig dauern, aber ich versuche, in dem was wir haben einen Sinn zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24496] = { id = 24496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rune", description = "{name}, diese Rune hier sollte ich an Euch weitergeben. Nehmt Euch Zeit und lest sie gut durch, sobald Ihr könnt. Ich glaube, sie kommt von der Magierlehrerin Teegli. Werft einen Blick darauf und dann sucht sie in Ambossar auf.", sourceObjective = "Lest die Arkanrune und sprecht dann mit Teegli Merrowith im Eisklammtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[24497] = { id = 24497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder in der Luft", description = "Wir haben gerade aus Valormok erfahren, dass wir keine weiteren Windreiter entsenden sollen, sonst werden sie von Scharfschützen der Talrendisspitze abgeschossen. Wir können Valormok nicht aufgeben, wenn wir eine sichere Route nach Eschental haben wollen, also gehen wir auf einem anderen Weg hinein.\n\nDie Fliegenden Priester haben großzügigerweise angeboten, einige unserer Leute von oberhalb der Reichweite der Scharfschützen abzusetzen. Geht zum Militärviertel und sichert Euch einen Flug auf einem ihrer Flugzeuge. Sie werden Euch dort in einem Stück abliefern und wenn Ihr erst einmal dort seid, könnt Ihr unsere Windreiterlinien wieder sichern.", sourceObjective = "Sichert Euch einen Flug nach Valormok mit den Fliegenden Priestern an der Ostseite des Bilgewasserhafens.", completion = "Es ist schon längst überfällig, Azshara von diesem Nachtelfenabschaum zu säubern. Ich bin froh, dass ich jemanden mit Euren Fähigkeiten habe, der mir helfen kann, das deutlich zu machen.\n\nSeid Ihr bereit, an die Arbeit zu gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24498] = { id = 24498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Zitadelle", description = "Sie haben unsere gefangenen Soldaten zur Arbeit im Steinbruch eingesetzt!\n\nTötet ihre Entführer und befreit sie, <mein Held/meine Heldin>. Wir werden ihre Hilfe brauchen, wenn wir Geißelfürst Tyrannus entgegentreten.", sourceObjective = "Befreit 15 Allianzsklaven und tötet Schmiedemeister Garfrost.", completion = "Ihr habt heute gute Arbeit geleistet. Jetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[24499] = { id = 24499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos gequälter Seelen", description = "Wir sind eindeutig zu wenige, um uns in die Zitadelle zu wagen, doch so eine Gelegenheit dürfen wir uns nicht entgehen lassen.\n\nRäumt die Feinde bis ganz nach hinten aus dem Weg und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.", sourceObjective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", completion = "Genau zur rechten Zeit! Danke, {name}!\n\nDie Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion. Diesen Ort lässt Arthas nicht so stark bewachen, und an diesem Ort hoffen wir, ein Anzeichen von Schwäche bei ihm entdecken zu können... und vielleicht, aber nur vielleicht, ihn zu erlösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24500] = { id = 24500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Lichkönigs", description = "Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?\n\nViele Fragen sind noch offen, doch zuerst müsst Ihr Jaina finden und vor dem Lichkönig fliehen, so lange noch Zeit dazu ist.", sourceObjective = "Findet Lady Jaina Prachtmeer und flieht aus den Hallen der Reflexion.", completion = "<Jaina ringt noch immer nach Luft.>\n\nIch kann kaum glauben, dass wir noch am Leben sind. Es war dumm von mir, ihm zu folgen. Zu oft habe ich diesen Fehler begangen. Und Ihr... es war ziemlich unbesonnen, mir zu folgen, anstatt mit den Informationen zu fliehen. Aber... nun ja... danke. Das war wirklich heldenhaft!\n\nMit Uthers Hilfe haben wir vielleicht eine Chance, Arthas zu besiegen. Dann hätten alle, die heute gestorben sind, ihr Leben nicht umsonst gelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24501] = { id = 24501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinne am Morgen bringt Kummer und Sorgen", description = "Die Flut der Spinnen nimmt kein Ende, {name}. Ihr müsst in ihr Nest gehen und die Brutmutter töten.\n\nWir haben die riesige Spinne namens Rygna zuletzt am Rand des Schwarzforstes gesehen, in einer Gegend, die ganz mit dicken Netzen bedeckt war. Es wird gefährlich, aber wir verlassen uns auf Euch.", sourceObjective = "Tötet Rygna in Rygnas Hort.", progress = "Habt Ihr Rygna schon vernichtet, {name}?", completion = "Gute Arbeit, {name}. Wir haben gehört, dass es weiter oben in den Bergen noch Überlebende geben soll. Jetzt können wir endlich Späher dorthin schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24502] = { id = 24502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notwendige Gewaltanwendung", description = "Wir haben nur noch einen Schredder. Als gerade niemand hingesehen hat, habe ich ihn mit, nun ja, sagen wir, modifizierten Fußbomben geladen.\n\nIhr müsst diesen Schredder nehmen und ihnen das Leben zur Hölle machen!", sourceObjective = "Benutzt den Bilgewasserbukanier und werft die Fußbombe auf 8 Dampfdruckhaie.", sourceObjectiveStatus = "unverified-source-field" }
quests[24503] = { id = 24503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drölfmeterschießen", description = "Jetzt liegt es an Euch, <Junge/Mädel>! Ihr habt die Dampfdruckhaie vernichtet. Jetzt müsst Ihr nur noch das Siegtor schießen.\n\nJetzt mal unter uns. Ich finde, wir sollten dieses Mal alles richtig machen. Ich möchte nicht, dass Ihr einfach nur ein Tor schießt... Ich möchte, dass Ihr so weit schießt, dass die Bombe bis zwischen die beiden Schornsteine hinter dem Tor fliegt!\n\nIch habe die Fußbombe so präpariert, dass sie dafür die richtige Zusatzleistung hat.\n\nUnd jetzt raus da und macht mich stolz!", sourceObjective = "Schießt das Siegertor, indem Ihr die Fußbombe zwischen die beiden Schornsteine hinter dem gegnerischen Tor schießt.", completion = "Äh… Ihr habt es geschafft, Junge. Ihr habt es ECHT geschafft! Wir haben das Spiel gewonnen und… \n\nHABT IHR DIESEN DRACHEN GESEHEN?!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24504] = { id = 24504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säubert den Höhenpfad", description = "Hier entlang, {class}! Wie ich sehe, habt Ihr den Höhenpfad entdeckt.\n\nDie Allianz hofft, dass sie unsere Verbindungen zum Steinkrallengebirge abschneiden kann, aber sie haben vergessen, dass wir Tauren seit Generationen in diesen Landen jagen. Wir kennen jede Spitzkehre an den Hängen und jeden Wildpfad von hier nach Tausend Nadeln.\n\nAber damit diese Pfade offen bleiben, müssen wir die Menschen daran hindern, sie zu vermessen.\n\nLauft auf dem östlichen Pfad Patrouille und tötet alle Späher des Höhenpfads, die Ihr unterwegs findet. Dann sprecht mit Tunawa Stillwind, den Ihr ein Stück weiter den Pfad entlang findet.", sourceObjective = "Tötet 3 Späher des Höhenpfads.", completion = "Auf dem Höhenpfad zu patrouillieren ist eine lebensgefährliche Aufgabe, aber sie muss erledigt werden. Diese engen Bergpfade sind im Moment unsere einzige Lebenslinien ins Steinkrallengebirge. Sie müssen erhalten werden.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24505] = { id = 24505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Jägerhügel ausharren", description = "Ehrenwacht mag verloren sein, aber sein Geist ist niemals zerstört worden. Sogar jetzt harren Überlebende noch an einem Ort aus, der \"Jägerhügel\" genannt wird.\n\nFolgt dem Höhenpfad weiter und Ihr werdet ihr Lager genau vor uns finden. Wenn Ihr dort eintrefft, sprecht mit Onatay und lasst sie wissen, dass der Pfad - für den Moment jedenfalls - immer noch sicher ist.", sourceObjective = "Sprecht mit Onatay am Jägerhügel im Südlichen Brachland.", completion = "Also die Allianz erkundet die Drehungen und Wendungen des Höhenpfads?\n\nSelbst wenn es ihnen gelingt, ihn zu kartographieren, könnten sie diese Hügel nicht mit vielen Leuten angreifen. Dies ist unser Land, {name}. Und sie werden es teuer bezahlen, wenn sie etwas anderes glauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24506] = { id = 24506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der eisigen Zitadelle", description = "{class}! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Königin, Fürstin Sylvanas Windläufer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, hat sie mich mit der Suche nach grimmigen Kämpfern beauftragt, die sich dorthin wagen. Ihr scheint mir dafür geeignet.\n\nTrefft sie am Eingang der Schmiede, {class}!", sourceObjective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Fürstin Sylvanas Windläufer.", completion = "Gut. {name}, ich weiß einiges über Euch. Ihr seid wie gemacht für diese Aufgaben.\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24507] = { id = 24507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Zitadelle", description = "Sie lassen unsere entführten Soldaten im Steinbruch schuften. Tötet die Entführer und befreit die Gefangenen, {class}! Wir brauchen ihre Hilfe, wenn wir Geißelfürst Tyrannus gegenübertreten.", sourceObjective = "Befreit 15 Hordensklaven und tötet Schmiedemeister Garfrost.", progress = "Danke, {class}. Unser Blut und unser Stahl werden Euch zu Diensten sein.", completion = "Ihr habt heute gute Arbeit geleistet. Jetzt, wo viele der Sklaven befreit sind und wir Zugang zu den Schmieden haben, wird es nicht mehr lange dauern, bis ich eine starke Mannschaft zusammen habe, die uns helfen wird, uns aus den Fängen des Geißelfürsten Tyrannus und seiner widerwärtigen Grube zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[24510] = { id = 24510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der eisigen Zitadelle", description = "{class}! Kommt schnell her - ich muss mit Euch reden!\n\nMeine Herrin, Lady Jaina Prachtmeer, hat eine Lücke in der Verteidigung der Eiskronenzitadelle entdeckt, die zu einem Ort namens \"Die Seelenschmiede\" führt. Bevor sie sich auf den Weg machte, erhielt ich die Aufgabe, alle Hilfe zu suchen, die ich finden kann... und, nun ja, ich hatte da an Euch gedacht.\n\nBitte, sucht sie so schnell wie möglich dort auf!", sourceObjective = "Betretet die Seelenschmiede von der Seite der Eiskronenzitadelle und findet Lady Jaina Prachtmeer.", completion = "{name}! Ich bin so froh, dass Ihr gekommen seid!\n\nUns bietet sich die seltene Gelegenheit, die Eiskronenzitadelle zu erkunden. Doch wir müssen uns beeilen, wenn wir nicht wollen, dass Arthas etwas merkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24511] = { id = 24511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos gequälter Seelen", description = "Es ist ziemlich gefährlich, mit so wenig Leuten die Zitadelle zu betreten, doch so eine Gelegenheit bekommt man nicht alle Tage.\n\nBereitet einen Weg zum anderen Ende und sichert den Pfad zur Grube von Saron, damit unsere Leute weiter in die Zitadelle vordringen können.", sourceObjective = "Tötet Bronjahm und den Verschlinger der Seelen, um den Zugang zur Grube von Saron zu sichern.", completion = "Ihr kommt gerade recht, {class}!\n\nDie Grube von Saron liegt direkt vor uns, und wenn unsere Späher richtig liegen, befinden sich dahinter die Hallen der Reflexion. Diesen Ort lässt Arthas nicht so stark bewachen, und an diesem Ort hoffen wir, ein Anzeichen von Schwäche bei ihm entdecken zu können... und eine Möglichkeit zur Rache, die schon so lange überfällig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24512] = { id = 24512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung eines Kriegers", description = "Diejenigen, die sich beim Fall von Ehrenwacht ergeben haben, sind der Horde nicht länger würdig, {class}. Doch ich werde sie noch nicht aufgeben. Der Gefängnisturm unter uns ist nur leicht bewacht. Geben wir den Gefangenen eine letzte Chance, ehrenhaft zu sterben.\n\nIch habe Seile in Position gebracht, die es Euch erlauben werden, schnell den Berg hinauf- und hinunterzuklettern. Schleicht Euch hinunter, bringt die beschlagnahmten Waffen an Euch und bewaffnet die Gefangenen, die sich im Turm befinden.\n\nUnd {name} - bleibt beim Turm! Wir sind in der Basis noch nicht ausreichend ausgerüstet, um einen Angriff zu überstehen.", sourceObjective = "Bringt 5 Kisten mit konfiszierten Waffen aus Ehrenwacht an Euch und rüstet 5 Gefangene aus dem Steinkrallengebirge damit aus. Benutzt die Seile in der Nähe, um Euch schnell in das Lager der Allianz hinein- und hinauszubewegen.", completion = "Von hier oben habe ich einen genauen Überblick über das Chaos, das Ihr gerade angerichtet habt, {name}. Unsere verlorenen Brüder haben ein wenig ihrer Würde wiedergewonnen und die Hunde der Allianz wurden in die Flucht gejagt. Präzise Arbeit, mein Freund!\n\nWenn die Allianz heute Nacht gut schläft, machen wir etwas falsch.\n\nWir werden niemals nachgeben.\n\nWir werden niemals aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24513] = { id = 24513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Auge", description = "Wer ist da? Eure Schritte klingen nicht wie das faule Schlurfen der Wachen.\n\n<Ein/Eine:c> {class}, sagt Ihr? Immer noch tapfer und frei? Für mich gibt es keine Hoffnung, <mein Freund/meine Liebe>. Ich habe mein Augenlicht verloren und bin nicht länger kampftauglich.\n\nIch habe es gewagt, meine Stimme zu erheben, als Hauptmann Peake einen der Gefangenen schwer misshandelte. Als Antwort hat er mich gegen den Kopf getreten. Immer wieder. Er hat auf mir herumgetrampelt, bis ich blind war, {race}.\n\nIhr findet Hauptmann Peake oben auf seinem Turm. Wenn Ihr Gerechtigkeit wollt, bringt mir seine Augen.\n\nWenn er sie nicht freiwillig hergibt... so sei es.", sourceObjective = "Tötet Hauptmann Peake und bringt seine Augen zu Oltarg.", progress = "Peake ist ein Monster. Wenn seine Vorgesetzten davon wüssten, wären sie der Horde dankbar, dass diese ihm ein Ende bereitet hat.", completion = "Habt Ihr sie? Ich verlasse mich blind auf Euch. Zu hören, das Peake wie eins seiner Opfer brüllt, ist genug Belohnung für mich.\n\nNun lasst mich allein, {name}. Ich möchte meinem Klan keine Bürde sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24514] = { id = 24514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenreste", description = "Wir werden hier belagert, {class}. Durch den Abgrund einerseits und die ständige Belästigung durch die Allianz andererseits sind die Vorräte knapp geworden. Aber wir schlagen uns mit dem, was da ist, durch - so, wie wir Tauren das immer getan haben.\n\nWir haben keine Schmiede, aber wer geschickt in der Lederverarbeitung ist, kann unsere beschädigte Rüstung mit qualitativ hochwertigen Bälgen verstärken oder zusammenflicken.\n\nDort unten sind die Jagdgründe der Schreckenszahnraptoren. Sie sind nicht leicht zu töten - was zum Teil an der Robustheit ihrer dicken Bälge liegt. Jagt sie, {name} und bringt mir ihre Bälge!", sourceObjective = "Besorgt 8 Schreckenszahnbälge von Schreckenszahnläufern und Schreckenszahnsensenklauen.", progress = "Schreckenszahnraptoren jagen im Rudel und kreisen ihre Beute ein. Wir jagen sie, ja, aber wir respektieren sie auch.", completion = "<Onatay lässt ihren Blick über die frischen Bälge schweifen und nickt langsam.>\n\nJa {name}, damit kann ich arbeiten. Ihr arbeitet schnell!\n\nDiese Bälge werden uns dabei helfen, noch länger auszuharren, bis Verstärkung kommt. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24515] = { id = 24515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signale am Himmel", description = "Wendet Euren Blick nach Südosten. Seht Ihr den Rauch der Lagerfeuer von Camp Una'fe?\n\nVor noch nicht einmal zehn Minuten sah ich aus dem Zentrum des Lagers große weiße Rauchwolken gen Himmel aufsteigen. Das war ein altes Signal, das mein Dorf dazu verwendete, die Jagd über große Entfernungen hinweg zu koordinieren. Doch diesmal war es ein Notrufsignal.\n\n{name}, mein Bruder Makaba ist in diesen unnatürlichen Dschungel gegangen. Bitte geht dorthin und stellt sicher, dass er nicht in Schwierigkeiten steckt.\n\nEs gibt verschiedene Wege... Schaut Euch in der Wildnis nach Zelten um.", sourceObjective = "Begebt Euch nach Camp Una'fe in der Überwucherung des Südlichen Brachlands und sprecht mit Makaba Flachhuf.", completion = "Also hat meine Schwester die alten Signale erkannt? Ihre Jägeraugen sind scharf wie immer.\n\n{name}, als wir dieses Lager aufschlugen, waren wir am Rand des Dschungels. Jetzt schaut Euch um!\n\nIrgendetwas fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24517] = { id = 24517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt ihnen Angst ein", description = "Seht Ihr die Spur dort unter uns, {name}? Das ist MEINE Spur. Und wenn diese Hunde der Allianz sich an meine Spur heften, dann sollten sie aufpassen, was hinter ihnen vor sich geht.\n\nEs wird Zeit, dass ich meinen Wegzoll einfordere. Tötet die Fußsoldaten der Ehrenwacht und schaut, ob wir sie nicht wie die Hasen wieder hinter ihre Mauern jagen können.\n\nAchtet darauf, dass Ihr mindestens einen ihrer Offiziere tötet, die die Straße entlang patrouillieren. Ihnen muss klar werden, dass niemand sicher ist.", sourceObjective = "Tötet 8 Fußsoldaten der Ehrenwacht und 1 Offizier der Ehrenwacht.", completion = "Ausgezeichnet, {name}. Es wird eine Weile dauern, bevor wir die Festung selbst angreifen können, aber bis dahin müssen wir ihnen Angst vor dem Brachland einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24518] = { id = 24518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiefenpfad", description = "Dieser Stapel Papiere wurde in einer Ledertasche unter den Kleidern des Offiziers versteckt gefunden.\n\nSchlachtpläne der Region, die Ehrenwacht darstellen, das mit einer langen, unfertigen Straße verbunden zu sein scheint, die sich von Theramore aus quer durch das Brachland erstreckt. Es sieht so aus, als ob die Allianz plant, eine Straße von der Küste bis hinein ins Herz von Kalimdor zu bauen.\n\nKilrok Grindhammer wird das sicher sehen wollen.", sourceObjective = "Liefert die Straßenbaupläne bei Kilrok Grindhammer am Jägerhügel im Südlichen Brachland ab.", progress = "Ah, Ihr sagt, Ihr hättet etwas bei einer der Leichen gefunden?", completion = "<Kilrok überfliegt die Pläne, die Ihr entdeckt habt.>\n\nDas erklärt einiges, {name}. Kein Wunder, dass unsere Feinde so versessen darauf sind, das Südliche Brachland einzunehmen. Es ist das Zentrum ihrer Pläne für den Kontinent!\n\nAber sie haben die Rechnung ohne uns gemacht, nicht wahr, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24519] = { id = 24519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vermessung unterbinden", description = "Diese Karten wurden alle von derselben ruhigen Hand gezeichnet. Ich hab einen Vermesser der Menschen gesehen, der die Straße zwischen der Burg und dem Dschungel im Osten entlanggelaufen ist.\n\nWir können ihnen einen Strich durch die Rechnung machen, indem wir an diesem Vermesser ein Exempel statuieren, {name}.\n\n<Kilrok zeigt auf die Unterschrift unten auf den Karten.>\n\nWas meint Ihr, was dort steht? \"Zykes\"? Sogar menschliche Namen klingen dünn und schwach. Tötet ihn!", sourceObjective = "Findet und tötet den Feldmesser Henry Zykes.", completion = "Gut, gut! Wir müssen Ehrenwacht isoliert halten.\n\nAlleine...verängstigt... {name}, wenn wir sie unter Druck setzen, werden sie vielleicht eines Tages sogar den Pfad einfach aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24520] = { id = 24520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten für Sassy", description = "Ich würde ja mit Euch feiern, aber ich fürchte, dass der Drache dem guten alten Kajaro ganz schön zugesetzt hat. Ich… äh… Ich glaube, ich packe meine Sachen und nehme das erste Schiff, das die Insel verlässt.\n\nIhr solltet jedenfalls zum Hauptgeschäftssitz zurückkehren und Sassy erzählen, dass Ihr den Fußbombentitel für uns gewonnen habt. Ich bin mir sicher, dass sie auch über den Drachen und den Kajaro Bescheid wissen möchte.\n\nViel Glück!", sourceObjective = "Sprecht mit Sassy Hartzang im Hauptgeschäftssitz der HGK auf Kezan.", completion = "Ihr macht Witze, oder?! TODESSCHWINGE?!!!\n\n<Sassy sieht einen Moment lang panisch aus.>\n\nOkay, das wird schon. Wir veranstalten Eure Party, und bis wir damit fertig sind, ist der Drache sicher schon lange weg und der Boden hat zu zittern aufgehört.\n\nFalls nicht, können wir immer noch ein Schiff chartern und von hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24522] = { id = 24522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sonnenbrunnen", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, {name}! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", sourceObjective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", progress = "Was führt Euch hierher?", completion = "Ihr wollt Zugang zum Sonnenbrunnen? Das ist unmöglich! Der Sonnenbrunnen ist unserem Volk der heiligste und wichtigste Ort. Erst kürzlich konnten wir ihn durch die Hilfe der Offensive der Zerschmetterten Sonne zurückgewinnen. Er ist kein Ort für Touristen und Reisende.", sourceObjectiveStatus = "unverified-source-field" }
quests[24523] = { id = 24523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem der Wildmähnen", description = "Es gibt nur noch einen Brunnen, der gesäubert werden muss; er trägt den Namen des Wildmähnenklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.\n\nAlphatiere streifen oft am Fuße unserer mächtigen Stadt Donnerfels umher.", sourceObjective = "Sammelt 4 Präriealphazähne von Präriewolfalphas.", progress = "{name}. Habt Ihr die Zähne, um die ich gebeten habe?", completion = "Sehr gut, {name}. Ich kann das Opfer fühlen, das das Land gebracht hat, und mein Geist ist erfüllt von Traurigkeit und Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24524] = { id = 24524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmähnensäuberung", description = "Die Geister sprechen von Eurer Säuberung der Brunnen der Winterhufe und Donnerhörner, {name}. Das Totem der Wildmähnen ist fertig und die letzte Aufgabe erwartet Euch.\n\nDer Brunnen der Wildmähnen liegt nördlich von Donnerfels. Führt das Ritual durch! Heilt das Land vom Gift der Grimmtotem! Lasst das Wasser wieder klar und rein fließen!", sourceObjective = "Benutzt das Läuterungstotem der Wildmähnen beim Brunnen der Wildmähnen.", progress = "Einer der Brunnen stinkt immer noch und verbreitet sein Gift, {name}. Ihr müsst Euch beeilen.", completion = "Ihr habt es geschafft. Ihr habt die Brunnen gesäubert und unser Land geheilt. Das Dorf der Bluthufe dankt Euch, {name}.\n\nMöge der Wind Kunde von Euren Taten in alle Welt tragen und mögen die Wasser von Mulgore bis in alle Ewigkeit rein sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24525] = { id = 24525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hunde in Schach halten", description = "Nicht jeder, der aus Taurajo geflohen ist, hat es nach Una'fe geschafft, {name}. Einige starben unterwegs an ihren Verletzungen. Andere wurden von opportunistischen Stachelebern angegriffen.\n\nIch habe die grausige Aufgabe, die Leichen zu finden und einzusammeln. Aber Ihr könnt etwas für mich tun.\n\nFleischreißerstrauchdiebe durchstreifen die Lande südlich von hier und zerreißen die Leichen, zerren an ihren Eingeweiden herum und schleppen die Extremitäten der Toten davon. Bitte dezimiert sie, damit ich die gebotenen Beerdigungsrituale durchführen kann.", sourceObjective = "Tötet 6 Fleischreißerstrauchdiebe.", completion = "Es ist also vollbracht.\n\nEigentlich sind diese Strauchdiebe ein Teil des Lebenszyklus' der Erdenmutter. Aber im Zuge der Zerstörung, die sowohl die Allianz als auch der Kataklysmus über uns gebracht haben, wächst ihre Zahl ins Unermessliche. Es ist gut, sie wieder zu dezimieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24526] = { id = 24526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstocken des Zauberbuchs", description = "Exzellent! Lasst uns beginnen.\n\nZuerst werdet Ihr den Zauber 'Arkane Geschosse' lernen. Dieser Zauber unterscheidet sich ein wenig von jenen, die Ihr bereits gelernt habt. Jedes Mal, wenn Ihr einen anderen Zauber wirkt, ergibt sich die Möglichkeit, Arkane Geschosse zu verwenden. Warum gewinnt Ihr nicht ein Gefühl für den Zauber, indem Ihr die Trainingsattrapen benutzt, welche die Miliz vor dem Eingang nach Ambossar aufgestellt hat?", sourceObjective = "Erlernt 'Arkane Geschosse' von Teegli Merrowith. Wirkt den Zauber erfolgreich zweimal auf den Trainingsattrappen vor dem Eingang nach Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24527] = { id = 24527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn Eures Wegs", description = "Ausgezeichnet! Lasst uns anfangen.\n\nDie erste Fertigkeit, die Ihr lernen werdet, ist der 'Urtümliche Schlag'. Dabei ruft Ihr die uralten Götter an, die Euren Arm für einen mächtigen Schlag stärken.\n\nGanz schön hilfreich, findet Ihr nicht?", sourceObjective = "Erlernt 'Urtümlicher Schlag' von Teo Hammersturm. Übt anschließend 'Urtümlicher Schlag' zwei Mal an einer Übungsattrappe nahe des Eingangs zu Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24528] = { id = 24528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Lichts", description = "Seid Ihr bereit? Wunderbar! Wir sind froh, dass Ihr hier seid.\n\nBevor Ihr wieder nach draußen geht, muss ich Euch das \"Siegel der Rechtschaffenheit\" beibringen. Es verleiht jedem Eurer Schläge heiligen Schaden, sodass Ihr Euren Feinden schneller den Garaus machen könnt.\n\nIhr solltet auch wissen, dass Siegel Euch befähigen, die Macht des Lichts zu nutzen, um Eure Widersacher zu richten. Euer Richturteil wird jedes Mal Schaden verursachen, wenn Ihr es wirkt.", sourceObjective = "Erlernt bei Bromos Grummler 'Siegel der Rechtschaffenheit' und 'Richturteil'. Nachdem Ihr 'Siegel der Rechtschaffenheit' auf Euch selbst gewirkt habt, wendet 'Richturteil' auf eine der Übungsattrappen am Eingang zu Ambossar an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24529] = { id = 24529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Regen in die Traufe", description = "Als die Flüchtlinge von Taurajo aus nach Norden flohen, wurden einige von ihnen in der aufziehenden Dunkelheit von den anderen getrennt. Viele wurden von den Stachelebern der Borstennacken gefangengenommen, die ihre Lager im Westen und Südwesten von hier aufgeschlagen haben.\n\nIch weiß nicht, was die Stacheleber sich von uns erhofften, als sie unsere Flüchtlinge gefangennahmen - das Einzige, was sie sich dadurch zugezogen haben, ist mein Zorn. Und alles, was sie im Gegenzug erhalten werden, ist Rache.\n\nBefreit meine gefangenen Brüder und Schwestern und sendet den Stachelebern eine Botschaft, indem Ihr diejenigen tötet, die sie gefangen nahmen.", sourceObjective = "Rettet 5 eingesperrte Flüchtlinge aus Taurajo und tötet insgesamt 8 Dornenwirker oder Klingenwächter der Borstennacken.", completion = "Es ist schlimm genug, wenn das eigene Dorf ausgeraubt wird... aber die nächste Nacht in einem Stacheleberkäfig zu verbringen? Ich bin froh, dass Ihr da wart, um zu helfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24530] = { id = 24530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ah, das Leben eines Jägers", description = "Das Leben eines Jägers ist tief in Traditionen verwurzelt, wisst Ihr? Aufspüren mächtiger Bestien in wildem Terrain. Trinken. Die Lande bereisen, das Gewehr stets griffbereit. Trinken. Überleben dank Finesse, Mut und Instinkt, gefolgt von einem ordentlichen Schluck zu trinken.\n\nAber bevor wir zu den guten Sachen kommen, müsst Ihr die Grundlagen erlernen.", sourceObjective = "Erlernt 'zuverlässiger Schuss' von Thorgas Grimson und verwendet ihn dann 5 Mal bei den Trainingsattrappen vor dem Eingang nach Ambossar.", progress = "Ich weiß, das Leben eines Jägers ist jetzt schon aufregend, aber wartet nur ab... Es wird noch besser.", completion = "Nun, da Ihr einen neuen Jägertrick im Ärmel und ich etwas von Eurem Geld in der Tasche hab, geht da raus und erledigt ein paar Bestien! Kommt später wieder und wir reden weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[24531] = { id = 24531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereitmachen für die Schlacht", description = "Lektion eins. Abgesehen von Eurem Schwert und Schild, was ist das wichtigste Utensil in Eurem Arsenal?\n\n<Thran wartet auf eine Antwort.>\n\nAch, macht nichts, ich werde für Euch antworten. Es ist Eure Beweglichkeit. Eine der Stärken des Kriegers ist seine Fähigkeit, sich schnell auf dem Schlachtfeld bewegen zu können. Hier, {name}, ich werde Euch beibringen, Eure Beine zu Eurem Vorteil einzusetzen.", sourceObjective = "Erlernt 'Sturmangriff' von Thran Khorman und verwendet es dann bei einer der Trainingsattrappen vor dem Eingang nach Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24532] = { id = 24532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Gegner ausweiden", description = "Eines der Dinge, die den Schurken so gefährlich machen, ist unsere Fähigkeit, eine Kombination von Kampfmanövern zu verwenden und auf die Chance zu warten, eine vernichtende Technik anzuwenden.\n\nNun, da Ihr 'Finsterer Stoß' erlernen konntet, ist es an der Zeit, Euch eine Fähigkeit zu vermitteln, die im Anschluss sehr wirksam ist.\n\nBitte erlaubt mir, sie Euch beizubringen.", sourceObjective = "Lernt 'Ausweiden' von Solm Hargrin und wendet es dreimal auf die Trainingsattrappen vor dem Eingang nach Ambossar an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24533] = { id = 24533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Macht", description = "Nun, wenn Ihr wirklich etwas Besonderes werden wollt, solltet Ihr mit mir sprechen. Ein Priester ist ein Niemand ohne seine Zaubersprüche. Und ich kenne eine ganze Reihe Zauber, die ich Euch beibringen könnte.\n\nDer erste davon ist ein schneller Heilzauber, der Euch rasch wieder auf die Beine bringt, wenn Ihr Schaden erlitten habt. Sagt mir, <Junge/Mädel>, erleidet Ihr jemals Schaden?", sourceObjective = "Erlernt \"Blitzheilung\" bei Branstock Khalder. Wendet anschließend Blitzheilung 5 Mal auf verwundete Milizsoldaten in Ambossar an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24534] = { id = 24534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Sprache sprechen", description = "Die Stacheleber greifen uns an, weil sie Schwäche spüren. Stärke ist die einzige Sprache, die sie verstehen. Also werden wir ihnen Stärke zeigen.\n\n<Makaba zieht ein großes Horn aus seinem Beutel.>\n\nZugegeben, das hier ist primitive Arbeit, aber es wird reichen. Die Anführer der Borstennacken benutzen Hörner wie dieses, um sich gegenseitig zu Revierkämpfen herauszufordern.\n\n{name}, ich möchte, dass Ihr Säbelschnauze, den Champion der Borstennacken, zu einem Einzelkampf herausfordert. Besiegt ihn vor den Augen seiner Anhänger. Lasst das Horn am Herausforderungsring der Borstennacken südlich von hier erschallen.", sourceObjective = "Lasst das Horn der Herausforderung am Herausforderungsring der Borstennacken erschallen und besiegt Säbelschnauze in einem Einzelkampf.", progress = "Habt Ihr den Borstennacken einen Dämpfer versetzt?", completion = "Wie bitte? Er hat Euch mit einem Dutzend Eber angegriffen? Anscheinend haben die Stacheleber ihre eigenen Vorstellungen, was \"Einzelkampf\" bedeutet.\n\nDennoch, die Borstennacken werden nach dem Schlag, den Ihr ihnen versetzt habt, aus der Bahn geworfen sein. Es wird nicht lange dauern, bis ein neuer Champion sich in ihren Reihen erhebt, um weiteren Ärger zu verursachen...doch bis dahin haben wir ein wenig Zeit gewonnen, um die Flüchtlinge in Sicherheit zu bringen.\n\nDanke, {name}, die Überlebenden haben Euch viel zu verdanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24535] = { id = 24535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dämmersucher", description = "Solltet Ihr Quel'Delar wirklich bei Euch tragen, {name}, kann ich Euch vielleicht Zutritt zum Sonnenbrunnen verschaffen. Wenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Dämmersucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", sourceObjective = "Besucht die sterblichen Überreste Thalorien Dämmersuchers und erhaltet seinen Segen zum Führen Quel'Delars.", progress = "Seid Ihr an dem Ort gewesen, an dem Thalorien fiel, als er den Sonnenbrunnen verteidigte?", completion = "Ich gebe zu, dass ich nicht erwartet hätte, dass Thalorien Euch als Erben Quel'Delars anerkennt, aber ich respektiere sein Urteil. Ihr dürft zum Sonnenbrunnen gehen, doch ich erinnere Euch daran, dass Ihr an unserem allerheiligsten Ort zu Gast seid und Euch dementsprechend zu verhalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24536] = { id = 24536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas stinkt hier", description = "Man sieh sich diese Kerle an. Das Dampfdruckkartell betreibt das Valentinstagsgeschäft schon seit Jahren, und plötzlich tauchen diese Typen auf. Die gehören nicht zum Kartell. Das Kartell hat mich beauftragt, der Sache auf den Grund zu gehen. Irgendwas stinkt hier, und damit meine ich nicht das Parfüm.\n\nNehmt das Gerät, das ich mitgebracht habe, um damit die Parfümwolken zu untersuchen, die die Wachen umgeben. Ich möchte wissen, was sie in das Zeug reintun. Irgendwas ist da faul.", sourceObjective = "Verwendet Schnappbolzens Luftanalysegerät, um die Luft zu untersuchen, die 6 stark parfümierte Wachen umgibt, und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Hey, vielen Dank! Gebt her und lasst mal sehen!\n\n<Er nimmt das Gerät an sich und hantiert damit herum.>\n\nOh, das ist gar nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[24539] = { id = 24539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Pflanzen angreifen", description = "Dieses Camp wurde am Rande dieses Dschungels erbaut und ist bereits vollkommen von Pflanzen überwuchert. Irgendetwas Unnatürliches geht hier vor.\n\nVor Kurzem habe ich den Fehler gemacht, einige der gesunden Flüchtlinge hinauszuschicken, um Nüsse und Beeren zu sammeln. Diejenigen, die zurückkehrten, berichteten, dass die Pflanzen nach ihren Beinen gegriffen oder sie sogar hochgehoben hätten. Ich mache mir Sorgen um diejenigen, die noch nicht zurückgekehrt sind.\n\n{class}, bitte rettet die Flüchtlinge, die in dem klammernden Überwuchs um das Camp herum festgehalten werden.", sourceObjective = "Rettet 5 Flüchtling aus Taurajo, indem Ihr den klammernden Überwuchs tötet, der sie festhält.", completion = "Danke, {name}. Aber wenden wir uns nun der eigentlichen Frage zu:\n\nWo kommt dieser Überwuchs her? Und warum ist er so außer Kontrolle?", sourceObjectiveStatus = "unverified-source-field" }
quests[24540] = { id = 24540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegstanz", description = "Unser Volk wird von vielen als Volk der sanftmütigen Riesen oder der edlen Wilden angesehen. Sie haben nie gesehen, wie wir uns gegenseitig bekämpfen... wie wir Verräter aus eigenen Reihen bekämpfen.\n\nDen Grimmtotem wurde durch das Exil Gnade erteilt, doch sie haben ihre Heimat verletzt, um Rache an uns zu üben. Wir werden sie in Mulgore nicht länger akzeptieren.\n\nIch habe bereits Krieger geschickt, um sie durch den Steinkrallenpass nördlich von hier zu schicken. Unsere Krieger sind sehr mutig im Kampf, {name}. Ich möchte, dass Ihr Euch diesem Kampf anschließt. Geht und helft unseren Kriegern, die Grimmtotem endlich zu vertreiben.", sourceObjective = "Besiegt Orno Grimmtotem in Steinkrallenpass.", completion = "Willkommen zurück, {name}.\n\n\n\nWas getan wurde, war weder aus Rache, noch aus Stolz. Es war einzig und allein zum Schutz Donnerfels', zum Schutz unseres Volkes vor Qualen und Angst. Heute ist Mulgore wieder ein sicherer Ort.\n\nDie Erdenmutter dankt Euch für all Eure mutigen Taten, {name}, und auch ich danke Euch. Ihr habt für Euer heldenhaftes Verhalten eine Belohnung verdient. Ihr sollt für immer in Donnerfels willkommen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24541] = { id = 24541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parfümdiebstahl", description = "Ich wusste, dass die was im Schilde führen! Das Zeug enthält irgendeine bewusstseinsverändernde Chemikalie, doch anhand so einer kleinen Probe kann ich nicht ermitteln, was genau es ist. Ich brauch das echte Zeug.\n\nGeht aber nicht einfach rüber und kauft es. Ich will nicht, dass Ihr den Halunken auch nur ein Kupfer gebt. Nein, wir müssen es von der Quelle besorgen, diskret.\n\nIch werde Euch als Lieferbursche verkleiden. Ich hab einen Vorratshaufen gesehen, der von ihren Schlägern bewacht wurde. Geht und lauft dort vorbei, und bleibt NICHT stehen, sonst halten sie Euch auf! Sie werden Euch eine Kiste zuwerfen, bringt diese hierher.", sourceObjective = "Begebt Euch, während Ihr als Lieferbursche verkleidet seid, zum Vorratslager der Chemiemanufaktur Krone vor den Toren Orgrimmars, kehrt dann mit dem Paket, das sie Euch zuwerfen, zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", progress = "Haben sie Euch eine Kiste zum Ausliefern zugeworfen?", completion = "Habt Ihr sie? Gut gemacht! Ganz ausgezeichnet! Mal sehen, was wir hier haben.\n\n<Er öffnet die Kiste und untersucht den Inhalt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24542] = { id = 24542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Blüte", description = "Der große Erzdruide Naralex ist vor Kurzem hier im Brachland erschienen. Entweder steckt er hinter diesem Chaos, oder er versucht, es wieder in Ordnung zu bringen. Wie auch immer - Ihr solltet mit ihm sprechen, bevor dieser Dschungel die ganze Welt einhüllt. Naralex befindet sich in einem kleinen Taurenlager im Südosten.\n\nEs wäre hilfreich, wenn Ihr unterwegs Pflanzenproben sammeln könntet, damit er sie studieren kann. Die neuesten Blumensamen werden ihm viel über die jüngsten Veränderungen im Dschungel sagen.", sourceObjective = "Sammelt zehn ungewöhnliche Blütenknospen von knospenden Blüten in der Überwucherung auf.", progress = "Ich bin sehr beschäftigt, {class}.", completion = "Ah, Proben von verschiedenen Bereichen der Überwucherung? Ja, die werden ausgesprochen hilfreich sein. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24543] = { id = 24543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gespaltene Familie", description = "Die Kinder, die Ihr hier seht, wurden alle aus Taurajo gerettet, als die Kämpfe ausbrachen. Ich versuche, ihre Eltern zu finden.\n\nEiner der Flüchtlinge, die Ihr von den Stachelebern gerettet habt, hat das stärkste Kind erkannt. Es gehört zu Kirge und Mawre Sternhorn. Außerdem sagte er, dass Kirge bei den Feldern des Blutes etwas nördlich des Ortes, an dem das Massaker von Taurajo stattfand, lagert.\n\n{name}, bitte geht dorthin und sagt Kirge Sternhorn, dass sein Kind lebt und es ihm gut geht!", sourceObjective = "Findet Kirge Sternhorn an der Vendettakuppe im Südlichen Brachland.", completion = "<Kirge hört angestrengt zu und fällt dann auf ein Knie.>\n\nAm Leben! Mein Junge lebt noch! Lobet die Erdenmutter - ich habe immer noch einen Sohn.\n\n<Kirge gewinnt seine Fassung zurück.>\n\n{class}, die Mutter meines Jungen hat es nicht lebend aus Taurajo herausgeschafft. Ich werde ihren Tod rächen, selbst wenn das bedeutet, dass mein Sohn dann vielleicht ohne seine Eltern aufwachsen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[24545] = { id = 24545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heiligen und die Verderbten", description = "Ich verwahre mich dagegen, Euch diesen Auftrag zu erteilen, {race}, da er Euch wahrscheinlich ins Verderben führt.\n\nWenn Ihr nichts auf meine Einschätzung gebt und Euch der Aufgabe stellt, werde ich Euch mit dem Wissen und den Ressourcen vertraut machen, die dazu notwendig sind.\n\nIhr müsst in die Frostgramhöhlen zurückkehren und Lichträcher, Arthas' abgelegten Hammer, finden. Neu geschmiedet aus Saronit und geschärft mit dem ätzenden Blut der Monstrositäten des Lichkönigs, wird er die Grundlage unserer Arbeit bilden.", sourceObjective = "Platziert Lichträcher, 25 Einheiten urtümliches Saronit sowie Modermienes und Fauldarms ätzendes Blut in Hochlord Mograines Runenschmiede in der Eiskronenzitadelle.\n\nModermienes ätzendes Blut und Fauldarms ätzendes Blut sind nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle erhältlich.", progress = "Je näher man kommt, umso bedrohlicher scheint das Feuer der Schmiede zu lodern...", completion = "Ein überwältigendes Gefühl von Furcht ergreift von Euch Besitz, als die Flammen die Gegenstände verschlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24546] = { id = 24546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Linie im Schmutz", description = "Die Allianz brennt eine Spur der Morde quer durch das Brachland. Wir müssen sie hier aufhalten oder es wird nichts für uns übrig bleiben.\n\nAuf den Feldern des Blutes gibt es eine Anzahl strategisch wichtiger Hügel, auf denen Holztürme und neutrale graue Banner stehen. Wir müssen diese Hügel einnehmen und halten, wenn wir den Vorstoß der Allianz aufhalten wollen!\n\nHaltet Ausschau nach den Türmen im Norden, Osten und Süden von dem, was von Taurajo übrig geblieben ist. Schnappt Euch eine neutrale Flagge und verteidigt den Hügel gegen die Gegenangriffe!", sourceObjective = "Erobert einen neutralen Hügel in den Feldern des Blutes und verteidigt ihn gegen den Gegenangriff der Allianz.", completion = "Ihr habt Euch also behauptet! Mit Eurer Beharrlichkeit könnten wir es noch schaffen, die Allianz aus unseren Landen zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24547] = { id = 24547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Seelenschmaus", description = "Schattenschneide ist eine der besten Waffen, in deren Besitz <ein/eine:c> {class} kommen kann.\n\nIst Eure Machtgier nun befriedigt, {race}?\n\n<Ihr fühlt Mograines eindringlichen Blick.>\n\nDas dachte ich mir. Dann noch eine letzte Warnung...\n\nNun beginnt der tückischste Teil Eurer Aufgabe. Zügelt Euer Bestreben, denn wenn Eure Ziele nicht rein sind, werdet Ihr Euer Leben, ja, Eure Seele verlieren.\n\nDie Waffe in Euren Händen ist nichts weiter als eine leere Hülle, ein bloßer Schatten dessen, zu was sie werden kann.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr mit Schattenschneide 50 Diener des Lichkönigs in der Eiskronenzitadelle tötet. Die Seelen sind in den Schwierigkeitsgraden für 10 oder 25 Mann erhältlich.", completion = "<Hochlord Mograine blickt Euch eine Weile stumm an.>\n\nIhr scheint diesen Teil Eurer Prüfung mit Bravour bestanden zu haben, {race}.\n\nBetet, dass Euch das Glück in Euren Bestrebungen weiterhin hold bleibt...", sourceObjectiveStatus = "unverified-source-field" }
quests[24548] = { id = 24548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zersplitterte Thron", description = "Der Thron des Lichkönigs war einst sein Gefängnis. Kil'jaeden höchstselbst hat das Behältnis aus Eiskristallen aus dem Wirbelnden Nether gefertigt. Sein alleiniger Zweck war es, Ner'zhuls rachsüchtigen Geist festzuhalten.\n\nIndem er den Kristall mit Frostgram berührte, befreite Arthas Ner'zhuls Seele und ließ sie mit seiner eigenen verschmelzen. Die Splitter dieses Zusammenstoßes sind jetzt überall in der Zitadelle verteilt.\n\nIch brauche die Scherben, die wir nur von den mächtigsten Dienern des Lichkönigs bekommen können, um die in Eurer Klinge enthaltene Kraft zu versiegeln.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr 50 Schattenfrostsplitter sammelt.\n\nSchattenfrostsplitter sind nur im Schwierigkeitsgrad für 25 Mann erhältlich.", progress = "Habt Ihr die Splitter des Frostthrons besorgt, {class}?", completion = "Das sollte genügen, {class}.\n\nKommt zu mir, wenn Schattenschneide mit ihren Kräften ausgestattet wurde, und ich werde versuchen, sie zu vervollständigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24549] = { id = 24549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattengram...", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr ihm Schattenschneide bringt.", completion = "Ich gratuliere, {class}.\n\nEntgegen aller unüberwindbaren Hindernisse habt Ihr den Sturm überstanden.\n\nIch vertraue darauf, dass Ihr Eure Belohnung als angemessen empfinden werdet...", sourceObjectiveStatus = "unverified-source-field" }
quests[24550] = { id = 24550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Donnerfels", description = "Die Brunnen wurden gereinigt und die Wasser in Mulgore fließen wieder sauber und süß. Ihr habt uns gerettet... aber auch die auf die Grimmtotem zurückzuführenden Geschehnisse zu Tage gebracht. Die Taten der Grimmtotem müssen bekannt gemacht werden.\n\nDie Zeit ist für Euch gekommen, nach Donnerfels zu reisen, unserer großen Stadt auf der Anhöhe. Geht zu unserem Anführer, Baine Bluthuf, Sohn des Cairne. Er muss davon erfahren.", sourceObjective = "Sprecht mit Baine Bluthuf in Donnerfels.", completion = "Willkommen in Donnerfels, {name}. Ihr habt für unser Volk viel Gutes getan.\n\nErzählt mir von Eurer Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[24551] = { id = 24551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der neue Boss", description = "Unter Gar'duls Kommando ist die Verteidigung des Brachlandes nicht sehr erfolgreich verlaufen, {name}. Garrosh hat Kriegsfürst Blutheft hierher entsandt, um die Sache in die Hand zu nehmen. Er ist hier im Camp und wenn Ihr einen guten Eindruck hinterlassen wollt, solltet Ihr etwas Initiative zeigen.\n\nGeht nach Osten in die Felder des Blutes und findet Aufklärer der Nordwacht. Wenn Ihr dem neuen Kriegshäuptling einen Stapel ihrer Verdienstabzeichen bringt, werdet Ihr Euch sicherlich einen Namen machen!", sourceObjective = "Tötet Aufklärer der Nordwacht und nehmt ihnen 10 Verdienstabzeichen von Theramore ab.", progress = "Ihr seht wie ein {race} aus, der sich durchsetzen kann. Welche Neuigkeiten bringt Ihr aus den Feldern?", completion = "<Blutheft schaut sich die Abzeichen an und lässt sie dann aus seinen Händen auf den Sandboden fallen. Seine Lippen verziehen sich zu einem breiten Grinsen.>\n\nDAS sehe ich doch gerne, {class}! Wie heißt Ihr noch gleich?\n\nIhr werdet es hier weit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24552] = { id = 24552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stolz des Löwen", description = "Wenn Ihr Rache an den Eindringlingen der Allianz nehmen wollt, seid Ihr gut beraten, die gefährlichsten Raubtiere im Brachland zu beobachten.\n\nDie Löwen, die sich durch das hohe Gras schleichen, sind gerissen, gut getarnt und mächtig. Nehmt Euch an ihnen ein Beispiel und Ihr werdet verstehen, welche Art Krieg wir führen müssen.\n\nJagt die Ebenenstreuner und -stolzmähnen. Dann kehrt zu mir zurück und wir unterhalten uns darüber, was Ihr gelernt habt. Ihr werdet sie oft im Schatten großer Bäume antreffen.", sourceObjective = "Tötet insgesamt 5 Ebenenstreuner oder Ebenenstolzmähnen.", completion = "Ah ja... Ich sehe eine Gerissenheit in Euren Augen, die dort vorher nicht zu finden war. Gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24553] = { id = 24553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt, und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Die Klinge wird sich an Euch binden. Wenn das passiert, tragt sie zu Caladis Prunkspeer in Qel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Was ist Euch beim Sonnenbrunnen widerfahren?", completion = "Das ist unglaublich, {name}! Ihr habt es tatsächlich geschafft! Alle Quel'dorei kennen die Geschichte von Thalorien Dämmersucher und Quel'Delar, aber keiner hätte je geglaubt, dass das Schwert wiederhergestellt werden würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24554] = { id = 24554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ramponierte Schwertgriff", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Die Sonnenhäscher wären sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", sourceObjective = "Bringt den ramponierten Schwertgriff zu Myralion Sonnenfeuer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", progress = "Was habt Ihr entdeckt?", completion = "<Myralion nimmt den Schwertgriff an sich und inspiziert das Artefakt.>\n\nDas habt Ihr aus der Zitadelle? Was hat es dort gemacht? Diese Klinge ist gewiss kein Erzeugnis der Geißel.\n\nWaffen dieser Qualität können nur von einigen wenigen Geschöpfen Azeroths hergestellt werden. Wir müssen mit ihnen in Verbindung treten und sehen, ob sie uns bei der Identifizierung der Waffe behilflich sein können.", sourceObjectiveStatus = "unverified-source-field" }
quests[24555] = { id = 24555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Drachen", description = "Dieser Schwertgriff stammt ganz eindeutig von einer sehr alten, sehr mächtigen Waffe. Nur von welcher? Diese Muster sind mir unbekannt, doch wir haben unsere Möglichkeiten noch nicht ausgeschöpft.\n\nKorialstrasz, besser bekannt als Krasus, ist schon lange Zeit mit den Quel'dorei und den Kirin Tor befreundet. Mit seinem umfangreichen Wissen und seinen Beziehungen kann er uns sicher weiterhelfen. Reist zur höchsten Ebene des Wyrmruhtempels und bittet ihn um Rat, meldet Euch dann bei Magister Hathorel in Sonnenhäschers Zuflucht in Dalaran.", sourceObjective = "Sprecht mit Krasus in der Spitze des Wyrmruhtempels.", completion = "Wir müssen uns das Buch vom Silberbund wiederbeschaffen. Ohne das Buch von Krasus haben wir kaum eine Chance, das Rätsel um das Schwert in Eiskrone zu lösen oder seine Macht freizusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24556] = { id = 24556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Verkleidung", description = "Euch ins Innere der Silbernen Enklave zu bringen, wird schwieriger sein, als es erscheint. Nur diejenigen, die über einen Wappenrock des Silberbunds verfügen, wird Zugang zur Zuflucht gewährt. Sollten wir an einen herankommen können, wird eine einfache Verzauberung den Rest erledigen.\n\nAuf dem Balkon über den Fäden des Schicksals werdet Ihr Shandy Lackglanz finden. Ich habe ihm in der Vergangenheit ein paar Mal geholfen - er schuldet mir also noch einen Gefallen. Er kümmert sich um die Wäsche etlicher Leute jeden Schlags aus der Stadt. Vielleicht kann er einen Weg finden, Euch einen Wappenrock eine Weile lang \"auszuleihen\".", sourceObjective = "Besorgt Euch von Shandy Lackglanz einen geliehenen Wappenrock.", progress = "Konnte Shandy Euch helfen, an einen Wappenrock des Silberbunds heranzukommen?", completion = "Ich wusste, dass Shandy einen Weg finden würde. Lasst mich ihn verzaubern, damit Ihr ihn verwenden könnt. Mit etwas Glück wird der Besitzer des Wappenrocks nicht einmal bemerken, dass er verschwunden ist, und Shandy wird unsere Spuren beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24557] = { id = 24557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan des Silberbunds", description = "Einer meiner Kontakte unten in den Kanälen der Schattenseite hat in der Taverne \"Zur Zauberkrähe\" einen Agenten des Silberbunds erblickt. Die Mitglieder des Silberbunds sind normalerweise nicht dafür bekannt, ein Interesse am dortigen Treiben zu hegen, was also sehr stark darauf hindeutet, dass sie etwas vorhaben.\n\nBegebt Euch zur Schattenseite, spürt diesen Agenten auf und schaltet ihn aus. Durchsucht ihn nach allen Informationen, die uns einen Hinweis über den Verbleib dieses Folianten vom Wyrmruhtempel liefern könnten. Wir können nicht zulassen, dass ihn diese albernen Schwächlinge vom Silberbund zuerst zurück nach Eiskrone bringen.", sourceObjective = "Besorgt die Befehle des Silberbunds.", progress = "Konntet Ihr irgendetwas Brauchbares bei diesem Agenten finden?", completion = "<Magister Hathorel liest die erbeuteten Befehle.>\n\nDer Agent, den Ihr abgefangen habt, sollte in der Silbernen Enklave jemanden namens Arkanist Tybalin treffen und dann den Folianten vom Wyrmruhtempel nach Eiskrone bringen. Wie müssen das Buch zurückbekommen, {name}, und es gibt nur eine Möglichkeit, solange es sich noch in der Stadt befindet. Jetzt ist schnelles Handeln gefragt!", sourceObjectiveStatus = "unverified-source-field" }
quests[24558] = { id = 24558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Myralion Sonnenfeuer", description = "Wir müssen dieses Buch zu Myralion Sonnenfeuer bringen. Würdet Ihr das übernehmen? Ich kann diese Aufgabe sonst niemandem anvertrauen, und Ihr habt Geschick darin bewiesen, die Leute vom Silberbund zu meiden.\n\nBringt es nach Quel'Delars Ruh südlich des Argentumturnierplatzes in Eiskrone. Myralion wird Euch dort erwarten. Wenn er die Klinge identifizieren kann, können wir sie im Namen Aethas Sonnenhäschers beanspruchen und Dalaran und der Allianz zeigen, dass wir den Angriff auf den Lichkönig anführen werden.", sourceObjective = "Bringt den Folianten \"Uralte drachengeschmiedete Klingen\" zu Myralion Sonnenfeuer in Quel'Delars Ruh.", progress = "Wir hatten Eure Rückkehr schon erwartet. Was hat Euch aufgehalten?", completion = "<Myralion nimmt das schwere Buch zur Hand und beginnt, darin zu blättern.>\n\nDie Symbole auf der Klinge kamen mir bekannt vor und jetzt weiß ich auch, warum. Das ist zweifellos eine Drachenklinge, die einem der sterblichen Völker zum Geschenk gemacht wurde. Nur um welche Klinge handelt es sich und wie ist sie nach Eiskrone gelangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24559] = { id = 24559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert neu schmieden", description = "Wir dürfen nicht zulassen, dass Quel'Delar in zerbrochenem und entehrtem Zustand bleibt. Nehmt die Überreste des Schwertes sowie den von Euch gefundenen ramponierten Schwertgriff und begebt Euch in die Grube von Saron in der Eiskronenzitadelle.\n\nIn der Grube lässt der Lichkönig Sklaven Saroniterz fördern sowie be- und verarbeiten. Dieses energieerfüllte Saronit brauchen wir, um Quel'Delar wiederherzustellen.\n\nIhr müsst energieerfüllte Saronitbarren sammeln und den Hammer des Schmiedemeisters erbeuten, Euch mit beidem zum Amboss des Schmiedemeisters begeben und das Schwert neu schmieden.", sourceObjective = "Besorgt 5 energieerfüllte Saronitbarren sowie den Hammer des Schmiedemeisters und verbindet sie mit den Überresten Quel'Delars, um das Schwert wiederherzustellen.", progress = "Konntet Ihr Quel'Delar wiederherstellen?", completion = "Ihr habt die Klinge Quel'Delars wiederhergestellt, der Behauptung Blutkönigin Lana'thels zum Trotz! Jetzt muss die Klinge nur noch getempert werden, bevor wir ihr beweisen können, wie töricht ihre Worte doch waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24560] = { id = 24560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge tempern", description = "Endlich wurden die Bruchstücke von Quel'Delar wieder vereint und die Klinge ist ganz - doch sie muss zuerst getempert werden, bevor Ihr sie einsetzen könnt. Die gezackte Saronitschneide ist spröde und würde beim ersten Kontakt zerbrechen.\n\nIn den Tiefen der Seelenschmiede in der Eiskronenzitadelle gibt es einen Ort, an dem sie sicher getempert werden kann. Nehmt Quel'Delar mit Euch zum Domizil des Verschlingers der Seelen und sucht nach dem Schmelztiegel. Taucht die Klinge dort hinein und bringt sie zurück zu mir in die Gefrorenen Hallen.", sourceObjective = "Tempert das neugeschmiedete Quel'Delar im Schmelztiegel der Seelen.", progress = "Solange das Schwert nicht getempert ist, ist es nutzlos.", completion = "Das Tempern des Schwertes sollte die Klinge wiederhergestellt haben. Warum hat es nicht funktioniert?", sourceObjectiveStatus = "unverified-source-field" }
quests[24561] = { id = 24561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Reflexion", description = "Ihr habt das Schwert zwar neu geschmiedet und getempert, dennoch ruht es in seiner Scheide und zeigt nichts von der Macht, die es besitzen soll. Ihr sagt, dass es Euch zieht, als hätte es einen eigenen Willen?\n\nWagt Ihr es, das Schwert an den von ihm gewünschten Ort zu bringen? Es ist nicht richtig, dass es so ruhig und doch so hartnäckig ist, und ich fürchte, wir werden nie erfahren weshalb, solltet Ihr es nicht an seinen Zielort bringen. Bringt es in die Hallen der Reflexion in der Eiskronenzitadelle. Seid jedoch auf der Hut! Ich warte in den Gefrorenen Hallen auf Euch.", sourceObjective = "Bringt Quel'Delar nach Schwertruh in den Hallen der Reflexion.", progress = "Was ist in den Hallen der Reflexion geschehen?", completion = "Wie kann sich das Böse in solch einem Schwert einnisten? Ich hätte das nicht für möglich gehalten, wenn sich der Beweis nicht direkt vor meinen Augen befände. Wenn die größte Schöpfung der Drachen verdorben und gegen sie gerichtet werden kann, weshalb sollte da ein Schwert die Ausnahme bilden?\n\nIch glaube, Uther hat Recht. Ihr müsst seinem Rat schnell folgen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24562] = { id = 24562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sonnenbrunnen", description = "Bringt Quel'Delar so schnell wie möglich zum Sonnenbrunnen, {name}! Glaubt Uthers Worten, dass Ihr die Kontrolle über die Klinge nicht immer behalten könnt, wenn sie dem bösen Einfluss des Lichkönigs ausgesetzt ist. Ihr müsst zur Insel von Quel'Danas reisen und versuchen, zum Sonnenbrunnen zu gelangen, um das Schwert zu läutern.\n\nDie Wächter des Sonnenbrunnens werden Euch nicht so einfach Zutritt gewähren. Daher müsst Ihr Euch an Halduron Wolkenglanz wenden, der ein Auge auf die Wachen dort hat.", sourceObjective = "Sprecht mit Halduron Wolkenglanz am Eingang des Sonnenbrunnenplateaus auf der Insel von Quel'Danas.", progress = "Was führt Euch hierher?", completion = "Ich hoffe, Ihr habt Verständnis dafür, dass ich Euch nicht einfach so Zutritt zum Sonnenbrunnen gewähren kann, {name}. Dies ist der heiligste den Sin'dorei bekannte Ort, und wir haben erst kürzlich Kontrolle über ihn zurückerlangt.\n\nIhr wollt unserem Volk mit Märchen über Quel'Delar Hoffnungen machen? Ohne Beweis für die Wahrhaftigkeit Eurer Behauptungen sehe ich keine Veranlassung, Euch Glauben zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[24563] = { id = 24563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dämmersucher", description = "Ihr arbeitet mit Myralion Sonnenfeuer zusammen, nicht wahr? Ich weiß, wie wir das Schwert testen können.\n\nWenn Ihr die Geschichte der Klinge kennt, erinnert Ihr Euch vielleicht, dass Thalorien Dämmersucher sie bei der Verteidigung des Sonnenbrunnens gegen die Geißel führte. Er fiel dort, wo sich heute die Todesschneise befindet, und verschaffte so seinen Leuten Zeit, eigene Vorbereitungen zu treffen. Seine sterblichen Überreste befinden sich am südlichen Ende der Todesschneise auf dieser Insel. Begebt Euch dorthin, damit sein Geist Euch den Segen erteilt, zum Sonnenbrunnen zu gehen.", sourceObjective = "Besucht die sterblichen Überreste Thalorien Dämmersuchers und erhaltet seinen Segen für den Gebrauch Quel'Delars.", progress = "Seid Ihr an dem Ort gewesen, an dem Thalorien fiel, als er den Sonnenbrunnen verteidigte?", completion = "Ihr tragt wirklich Quel'Delar bei Euch. Heute ist ein großer Tag für ganz Quel'Thalas und die Sin'dorei! Ihr habt meine Erlaubnis, zum Sonnenbrunnen zu gehen und die Wiederherstellung des Schwertes abzuschließen. Lasst den Kopf nicht hängen, {name}. Die Söhne und Töchter Silbermonds haben viele Jahre auf diesen Tag gewartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24564] = { id = 24564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Was ist beim Sonnenbrunnen geschehen?", completion = "Sind meine Augen tatsächlich auf die Waffe Thalorien Dämmersuchers gerichtet? Heute ist ein großer Tag für alle Sonnenhäscher und alle Sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24565] = { id = 24565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biologischer Eingriff", description = "Die Energien, die hier freigesetzt wurden, sind durch die Wildtiere geflossen. Dadurch wurden sie mächtig und instabil. Wenn wir zulassen, dass sie sich über diesen Hain hinaus ausbreiten, werden diese Mutationen eine katastrophale Auswirkung auf das Ökosystem haben, die Beutetiere verschlingen und die schwächeren, natürlichen Kreaturen vertreiben.\n\nIhr müsst gehen und bei dem Bestand der Überwucherung eine Auslese treffen. Kehrt zurück, wenn diese Aufgabe erfüllt ist.", sourceObjective = "Tötet 5 Deviatschreckenszähne und 5 Deviatebenenschreiter.", completion = "Danke, {name}. Ich bin froh, dass Ihr unverletzt zurückgekehrt seid; die Bösartigkeit dieser Kreaturen ist wirklich erschreckend.", sourceObjectiveStatus = "unverified-source-field" }
quests[24566] = { id = 24566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aussaat einer Lösung", description = "Aufgrund dessen, was Ihr mir überbracht habt, denke ich, dass wir vielleicht eine Lösung haben. Ich hab die Peitschenrankensamen mit heilenden Energien erfüllt.\n\nEinfacher Kontakt mit ihnen sollte den Kreaturen hier genug Energie verleihen, um den verderbnisreichen Einfluss abzuschütteln.\n\nGeht und versucht, die mutierten Raptoren und Ebenenschreiter zu heilen, indem Ihr die Samen über sie streut. Dann berichtet mir von dem Ergebnis.", sourceObjective = "Benutzt die beruhigenden Samen bei 6 Deviatschreckenszähnen oder Deviatebenenschreitern und beobachtet die Ergebnisse.", completion = "Oh weh! Anscheinend sind die Kräfte, die hier am Werk sind, schwer unter Kontrolle zu bringen...\n\nBitte behelligt Naralex nicht damit. Es wird ihn nur aufregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24567] = { id = 24567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch für ein Testspiel", description = "{name}, Trainer Blutgrätsch, der Kopf unserer furchtlosen Bilgewasserbukaniere, sucht Euch.\n\nEr sagt, dass der Ligatitel gegen die Dampfdruckhaie in Gefahr ist und dass nur Ihr den Pokal nach Hause holen könnt!\n\nGeht nach Westen in die Stadt. Ihr könnt das Kajarofeld nicht verfehlen.\n\nEin Fußbombenstar. Das wird sich hervorragend auf Euer Image auswirken!", sourceObjective = "Sprecht mit Trainer Blutgrätsch auf dem Kajarofeld auf Kezan.", completion = "Da seid Ihr ja, mein Junge! Schnell, wir haben keine Zeit zu verlieren! Wir müssen diese Schredder wieder funktionstüchtig machen.\n\nIch hole Euch von der Ersatzbank… Ihr werdet das Spiel und den Titel für uns gewinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24568] = { id = 24568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Mauern!", description = "{name}, sie versammeln sich an den Toren! Die Allianz versucht, nach Mulgore hineinzudrängen. Ihre Fußsoldaten versuchen, die Wachen zu überwältigen.\n\nWir haben so wenig, womit wir die Mauern verteidigen können. Wir haben kochendes Wasser in Töpfen, um die Angreifer in Schach zu halten, bis Hilfe eintrifft... Das muss reichen.\n\nAber wir brauchen jemand, der unsere Verteidigung organisiert. Ihr müsst nur ein Wort sagen und ich werde Euch zu einer Übersicht aus der Vogelperspektive über das Schlachtfeld verhelfen.\n\nWir brauchen Euch, {name}!", sourceObjective = "Sprecht mit Winnoa Kiefernwald an den Feldern des Blutes, um die Tore von Mulgore gegen den Angriff zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24569] = { id = 24569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsbrecher", description = "{name}, Ihr habt Euch auf den Feldern des Blutes als würdig erwiesen. Aber die Allianz bedroht immer noch unsere Taurenfreunde.\n\nDie Belagerungsmaschinen außerhalb der Tore von Mulgore sind wie Speere, die direkt auf unsere Herzen zielen. Ich möchte, dass Ihr zu den Toren südlich von uns geht und diese Belagerungsfahrzeuge aus dem Spiel nehmt.\n\nHier, benutzt die Haftbomben. Wir haben sie freundlicherweise von unseren neuen Goblinverbündeten bekommen. Sieht so aus, als ob sie Schwarzpulver in... es sieht aus wie... ölverschmierte Socken gestopft haben. Aber die werden schon reichen.", sourceObjective = "Zerstört 4 Belagerungsmaschinen der Nordwacht vor den Toren von Mulgore.", progress = "Warum hat Gar'dul zugelassen, dass die Allianz so viele schwere Belagerungsmaschinen aufstellt? Warum wurde kein Gegenschlag angeordnet, bevor ich hier eintraf? Gar'dul wird sich dafür noch rechtfertigen müssen...", completion = "Sehr gut! Jetzt werden sie wohl mit Infanterie auf die Tore losstürmen müssen.\n\nGlaubt Ihr, sie haben den Mumm dazu?", sourceObjectiveStatus = "unverified-source-field" }
quests[24570] = { id = 24570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenabzug", description = "Die Verderbnis, die hier entfesselt wurde, muss eingehend erforscht werden, wenn wir einen wirksamen Weg finden wollen, sie zu bekämpfen.\n\nZum Glück haben sich hier nicht alle Kreaturen gleichermaßen verändert. Die kleineren Schlangen trinken wenig Wasser und fressen keine Pflanzen, also sind sie den Energien nur in geringem Maße ausgesetzt worden. Dennoch haben sie genug aufgenommen, um ihre Farbe zu verändern.\n\nGeht, sammelt einige dieser Schlangen aus der Überwucherung und bringt sie zu mir, damit wir sehen können, was genau mit den Kreaturen hier geschieht.", sourceObjective = "Besorge 5 entkräftete Ottern.", progress = "Habt Ihr genügend eingesammelt? Wir benötigen einige, um aussagekräftige Vergleiche anstellen zu können.", completion = "Die sind genau richtig. Bunte Farben wie diese entstehen im Brachland nicht auf natürliche Weise, aber bisher haben sich bei ihnen noch keine weiteren Mutationen herausgebildet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24571] = { id = 24571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peitschenrankensamen", description = "Es muss einen Weg geben, diese armen Kreaturen zu heilen, ohne ihnen das Leben zu nehmen. Ich habe eine Idee, aber ich brauche Eure Hilfe, {class}.\n\nDie Pflanzen der Peitschenranke, die hier umherstreifen, enthalten Samen prallvoll mit der urtümlichen Energie dieses Ortes. Sammelt sie für mich ein und bringt sie hierher, dann sehen wir, was man tun kann.", sourceObjective = "Besorgt 4 zuckende Samen von Peitschenranken.", progress = "Habt Ihr die Samen?", completion = "Es beunruhigt mich, wie ... aktiv sie sind. Dennoch bedeutet das nichts anderes, als dass wir schnell handeln müssen, bevor die Verderbnis hier noch schlimmer wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[24572] = { id = 24572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taurajo zurückerobern", description = "Ausgezeichnete Arbeit dort an den Toren, {name}! Der größte Teil der Streitkräfte der Allianz befindet sich auf dem Rückzug. Aber das genügt mir nicht.\n\nSie haben Taurajo geplündert, das nur ein einfaches Lager der Jäger war. Die \"Allianz\" wurde demaskiert und man weiß jetzt, was sie wirklich ist: Eine Bande abtrünniger Schlächter.\n\nSogar jetzt lungert eine Gruppe Menschen dort herum und wühlt in den Knochen des noch schwelenden Taurajo herum.\n\n<Blutheft schleudert eine Axt in den Staub.>\n\nSie sollen leiden.", sourceObjective = "Tötet 8 Plünderer von Taurajo in den Überresten von Camp Taurajo.", completion = "Ausgezeichnet. Ich werde ihre Leichen entlang der Goldstraße als Botschaft für die Allianz aufhängen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24573] = { id = 24573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Toten ehren", description = "Jetzt, da die unmittelbare Bedrohung vorüber ist, könntet Ihr bei einer traurigen Aufgabe helfen?\n\nWir Tauren beerdigen unsere Toten nicht, wir bereiten ihre Körper auf die Rückkehr zu den Elementen vor und bringen sie zu unseren heiligen Grabstätten. Diejenigen, die während des Taurajomassakers getötet wurden, wurden nicht bestattet und ich fürchte, dass fehlgeleitete Soldaten der Allianz die Körper der Toten verbrennen, bevor die richtigen Rituale durchgeführt wurden.\n\n{name}, bitte bringt dieses Totem nach Taurajo und führt die Bestattungszeremonie für Krulmoo, Dranh, Yonada und Omusa durch. Sie... haben es dort nicht herausgeschafft.", sourceObjective = "Benutzt das Bestattungstotem an den Leichnamen von Krulmoo, Dranh, Yonada und Omusa in den Überresten von Camp Taurajo.", progress = "Haben ihre Geister ihren Frieden mit der Erdenmutter gemacht?", completion = "<Winnoa neigt ihren Kopf.>\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24574] = { id = 24574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...wird Chaos ernten", description = "Wenn ich wirklich Chaos gesät habe, wird es Zeit für mich, die Ernte einzubringen.\n\nDie schwerfälligen Auswüchse der Pflanzenwelt schlurfen durch den magieerfüllten Strom hier, {name}. Sie sind eine Manifestation der instabilen Kräfte, die diese Gegend verändern. Tötet so viele Ihr könnt und vielleicht können wir die weitere Verbreitung der Überwucherung verlangsamen.\n\nUnd wenn Ihr schon dabei seid... ich suche nach Teilen von ihnen, die besonders befallen erscheinen. Bringt solche Teile zu mir.", sourceObjective = "Tötet 5 Auswüchse und findet ein sich windendes Herz.", progress = "Die Auswüchse zu beschneiden, wird uns höchstens etwas Zeit verschaffen. Habt Ihr irgendwelche verdächtigen Teile gefunden?", completion = "<Naralex nimmt langsam das sich windende Herz aus Euren Händen und ist sichtlich verstört.>\n\nIch war ein Narr. Die eine Wahrheit, die ich nicht akzeptieren wollte, hat mir die ganze Zeit ins Gesicht gestarrt...dieses widerwärtige Ding ist der Beweis dafür.\n\nWir beide haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[24575] = { id = 24575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung", description = "Wir haben kürzlich herausgefunden, dass die Dorfbewohner in Glutstein die schlimmsten Verheerungen des Fluchs überlebt haben.\n\nLeider hatte ihr Dorf beim Einmarsch der Verlassenen nicht so viel Glück.\n\nDie Verlassenen haben die Dorfbewohner gefangen genommen und zwingen sie, in der nahegelegenen Mine als Sklaven zu arbeiten.", sourceObjective = "Befreit 5 versklavte Dorfbewohner in der Glutsteinmine.", progress = "Habt Ihr die Dorfbewohner befreit, {name}? Ich kann mir nicht vorstellen, welche Qualen Sie unter den Verlassenen erleiden müssen.", completion = "Ihr habt es wieder geschafft, {name}. Die befreiten Dorfbewohner wollen uns mit allen Kräften im Kampf gegen die Verlassenen unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
